/* Source-bound facts use the shared dialog, controls and layout primitives. */
.working-facts { overflow-wrap: anywhere; }
.working-facts fieldset { min-width: 0; border: 0; padding: 0; margin: 0; }
.working-facts details { border-bottom: 1px solid var(--border); padding-block: var(--space-2); }
.working-facts summary { cursor: pointer; font-weight: var(--weight-semibold); }
.working-facts details > .ui-stack { padding-block: var(--space-3); }
.working-facts p, .working-facts blockquote { margin: 0; }
.working-facts blockquote { border-inline-start: 1px solid var(--border); padding-inline-start: var(--space-3); }
/* Composable response surfaces. Controls stay owned by the shared UI kit. */
.rich-layout,.rich-layout-content{display:flex;flex-direction:column;gap:var(--space-4);min-width:0}
.rich-layout[data-mode="grid"]{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,24rem),1fr));align-items:start}
.rich-layout-group{min-width:0}
.rich-layout-group>h3{font-size:var(--font-size-sm);font-weight:var(--weight-semibold);color:var(--text-secondary);margin:0 0 var(--space-3)}
.rich-layout[data-density="compact"] .rich-layout-content{gap:var(--space-2)}
.rich-layout .rich-block{margin:0;min-width:0}
.rich-indicator-grid,.rich-resource-overview{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,12rem),1fr));gap:var(--space-3)}
.rich-indicator,.rich-resource-capacity{padding:var(--space-4);border:var(--control-edge-inset) solid var(--border);border-radius:var(--radius);background:var(--bg-secondary);min-width:0}
.rich-indicator h3,.rich-resource-capacity h4{margin:0 0 var(--space-2);font-size:var(--font-size-sm);font-weight:var(--weight-medium);color:var(--text-secondary)}
.rich-indicator-value,.rich-resource-capacity>strong{display:block;font-size:var(--font-size-2xl);font-weight:var(--weight-semibold);font-variant-numeric:tabular-nums;color:var(--text-primary)}
.rich-indicator p,.rich-resource-capacity p{margin:var(--space-2) 0 0;color:var(--text-secondary);font-size:var(--font-size-xs);overflow-wrap:anywhere}
.rich-indicator[data-tone="warning"],.rich-notice[data-tone="warning"]{border-color:var(--warning-border)}
.rich-indicator[data-tone="error"],.rich-notice[data-tone="error"]{border-color:var(--error-border)}
.rich-indicator[data-tone="success"],.rich-notice[data-tone="success"]{border-color:var(--success-border)}
.rich-sparkline{display:block;width:100%;height:2.5rem;margin-top:var(--space-3);overflow:visible;color:var(--accent)}
.rich-sparkline polyline{fill:none;stroke:currentColor;stroke-width:2;vector-effect:non-scaling-stroke}
.rich-indicator details{font-size:var(--font-size-xs);margin-top:var(--space-2)}
.rich-notice{border-inline-start:var(--space-1) solid var(--info-border);border-radius:var(--radius);padding:var(--space-3) var(--space-4);background:var(--bg-secondary)}
.rich-notice p{margin:0;color:var(--text-secondary)}
.rich-notice .rich-notice-message{color:var(--text-primary);font-weight:var(--weight-medium)}
.rich-notice p+p{margin-top:var(--space-2)}
.rich-workflow{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:var(--space-3)}
.rich-workflow li{display:grid;grid-template-columns:auto 1fr;gap:var(--space-1) var(--space-3);align-items:baseline;padding:var(--space-3);border:var(--control-edge-inset) solid var(--border);border-radius:var(--radius);background:var(--bg-secondary)}
.rich-workflow li>p{grid-column:2;margin:0;color:var(--text-secondary);font-size:var(--font-size-sm)}
.rich-workflow li>strong{font-weight:var(--weight-medium);font-size:var(--font-size-sm)}
.rich-step-status{font-size:var(--font-size-xs);font-weight:var(--weight-semibold);color:var(--text-secondary)}
.rich-workflow [data-state="running"] .rich-step-status{color:var(--info-text)}
.rich-workflow [data-state="completed"] .rich-step-status{color:var(--success-text)}
.rich-workflow [data-state="failed"] .rich-step-status{color:var(--error-text)}
.rich-workflow [data-state="blocked"] .rich-step-status{color:var(--warning-text)}
.rich-next-step{padding:var(--space-3);margin:var(--space-3) 0 0;border-radius:var(--radius);background:var(--info-bg);color:var(--info-text);font-size:var(--font-size-sm)}
.rich-resource-panel{display:flex;flex-direction:column;gap:var(--space-3);min-width:0}
.rich-resource-panel p{margin:0}
.rich-resource-status{font-size:var(--font-size-sm);color:var(--text-secondary)}
.rich-resource-panel[data-state="error"] .rich-resource-status{color:var(--warning-text)}
.rich-resource-panel[data-state="loading"] .rich-resource-status{color:var(--info-text)}
.rich-resource-provenance,.rich-resource-note{font-size:var(--font-size-xs);color:var(--text-secondary);overflow-wrap:anywhere}
.rich-resource-scroll-hint{font-size:var(--font-size-xs);color:var(--text-secondary)}
.rich-resource-filters{display:grid;grid-template-columns:2fr 1fr 1fr;gap:var(--space-3);min-width:0}
.rich-resource-panel table{width:100%;font-size:var(--font-size-sm);font-variant-numeric:tabular-nums}
.rich-resource-panel th,.rich-resource-panel td{text-align:start;padding:var(--space-2) var(--space-3);vertical-align:top}
.rich-resource-panel th[scope="row"]{font-weight:var(--weight-medium);overflow-wrap:anywhere;min-width:10rem;max-width:20rem}
.rich-resource-panel td:nth-child(n+3){white-space:nowrap;text-align:end}
.rich-resource-empty{padding:var(--space-5);text-align:center;color:var(--text-secondary);border:var(--control-edge-inset) dashed var(--border);border-radius:var(--radius)}
.rich-resource-source{font-size:var(--font-size-xs);color:var(--text-secondary)}
.rich-resource-source pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:20rem;overflow:auto}
.rich-resource-panel [hidden]{display:none!important}
@media(max-width:600px){.rich-resource-filters{grid-template-columns:1fr}.rich-resource-overview{grid-template-columns:1fr}.rich-indicator-value{font-size:var(--font-size-xl)}}

.rich-guidance-form,.rich-guidance-form fieldset{display:flex;flex-direction:column;gap:var(--space-3);min-width:0}
.rich-guidance-form fieldset{border:0;padding:0;margin:0}
.rich-guidance-form>p{margin:0;color:var(--text-secondary);font-size:var(--font-size-sm)}
.rich-resource-launcher{padding:var(--space-4);border:var(--control-edge-inset) solid var(--border);border-radius:var(--radius);background:var(--bg-primary)}
.rich-resource-launcher>summary{font-weight:var(--weight-semibold);cursor:pointer}
.rich-resource-launcher[open]>summary{margin-bottom:var(--space-4)}
.rich-resource-launcher>.ui-toolbar{margin-bottom:var(--space-3)}
/* Version-bound owner review shares kit controls and the existing panel. */
.artifact-review {
  flex: 0 1 auto;
  min-height: 0;
  max-height: 70%;
  overflow: auto;
  padding: var(--space-3);
  border-bottom: thin solid var(--border);
}
.artifact-review[hidden], .artifact-review [hidden] { display: none; }
.artifact-review h3, .artifact-review p { margin: 0; }
.artifact-review h3 { font-size: var(--font-size-lg); }
.artifact-review > .ui-btn { align-self: flex-start; }

.artifact-review[data-turn-review] { max-height: none; overflow-wrap: anywhere; border-bottom: 0; }
.artifact-review fieldset { min-width: 0; border: 0; padding: 0; margin: 0; }
.artifact-review legend { font-weight: var(--weight-semibold); margin-block-end: var(--space-2); }
/* Project workspace layout; controls and modal behavior belong to the UI kit. */
.coordination-workspace {
  width: min(72rem, calc(100vw - var(--space-6)));
  max-width: calc(100vw - var(--space-6));
}
.coordination-workspace p,
.coordination-workspace h3 { margin: var(--space-0); }
.coordination-workspace h3 { font-size: var(--font-size-lg); }
.coordination-workspace small { color: var(--text-secondary); }
.coordination-workspace article,
.coordination-entry { overflow-wrap: anywhere; min-width: 0; }
.coordination-entry { border-inline-start: var(--space-1) solid var(--accent); }
.coordination-work-grid { grid-template-columns: repeat(auto-fit, minmax(min(100%, 19rem), 1fr)); }
@media (max-width: 480px) {
  .coordination-workspace { width: calc(100vw - var(--space-2)); max-width: calc(100vw - var(--space-2)); }
}

/* Conversation-first project chrome; ordinary chat retains its canvas. */

.coordination-conversation-column { display: flex; flex-direction: column; flex: 1; min-width: 0; min-height: 0; overflow: hidden; }
#projectCoordinatorEntry { flex-shrink: 0; }
/* The sidebar entry is a compact project hub card: identity mark, role name and
 * a one-line work tally, so it reads as navigation instead of a stray label. */
.coordination-leader {
  display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-2);
  padding: var(--space-2); margin: var(--space-2) var(--space-2) var(--space-1);
  border: 1px solid var(--border); border-radius: var(--radius-sm);
  background: var(--bg-primary); color: var(--text-primary);
  transition: border-color var(--motion-fast) var(--ease-standard), background var(--motion-fast) var(--ease-standard);
}
.coordination-leader[data-coordinator-id]:not([data-coordinator-id=""]) { cursor: pointer; }
.coordination-leader[data-coordinator-id]:not([data-coordinator-id=""]):hover,
.coordination-leader[data-coordinator-id]:not([data-coordinator-id=""]):focus-visible {
  border-color: var(--accent); background: var(--bg-hover); outline: none;
}
.coordination-leader[data-coordinator-id]:not([data-coordinator-id=""])[aria-current="page"] {
  border-color: var(--accent); background: var(--accent-subtle);
}
.coordination-leader-mark {
  display: inline-flex; align-items: center; justify-content: center;
  inline-size: var(--space-6); block-size: var(--space-6); flex-shrink: 0;
  border-radius: var(--radius-xs); background: var(--accent-subtle); color: var(--accent);
}
.coordination-leader-mark svg { inline-size: var(--space-4); block-size: var(--space-4); display: block; }
.coordination-leader-body { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.coordination-leader-label {
  font-weight: var(--weight-semibold); line-height: var(--leading-tight);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.coordination-leader-meta {
  color: var(--text-tertiary); font-size: var(--font-size-xs); line-height: var(--leading-tight);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.coordination-leader-go { color: var(--text-tertiary); flex-shrink: 0; font-size: var(--font-size-lg); line-height: 1; }
.coordination-leader-actions {
  flex-basis: 100%; display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-1);
}
.coordination-leader-actions small { color: var(--text-secondary); }

.coordination-summary {
  padding: var(--space-3); color: var(--text-secondary);
  border: 1px solid var(--border); border-radius: var(--radius);
  background: var(--bg-secondary); min-width: 0; max-width: 100%; box-sizing: border-box;
}
.coordination-summary summary {
  cursor: pointer; color: var(--text-primary); font-weight: var(--weight-semibold);
  display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-1) var(--space-2); min-width: 0;
}
.coordination-summary-title { flex: 1 1 8rem; min-width: 0; }
.coordination-summary-tally {
  color: var(--text-tertiary); font-size: var(--font-size-xs); font-weight: var(--weight-regular);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.coordination-summary-actions { display: inline-flex; flex-wrap: wrap; align-items: center; gap: var(--space-1); font-weight: var(--weight-normal); }
.coordination-summary p { margin: var(--space-1) var(--space-0); white-space: pre-wrap; overflow-wrap: anywhere; }
.coordination-summary-work { padding-block: var(--space-2); }

#presenceStrip:has(.coordination-summary) { padding: var(--space-3) var(--space-4); }
.coordination-summary summary:focus-visible { outline: var(--control-edge-inset) solid var(--accent); box-shadow: var(--focus-ring); }

/* Graph workspace: geometry uses the same --space-4 cells as the projection.
 * Container queries select wires and node positions together, including split panes. */
.coordination-task-graph { display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; max-width: 100%; color: var(--text-primary); }
.coordination-task-graph h3, .coordination-task-graph p { margin: var(--space-0); }
.coordination-task-graph h3 { font-size: var(--font-size-md); }
.coordination-task-graph small { color: var(--text-secondary); font-size: var(--font-size-sm); }
.coordination-canvas { container: coordination-canvas / inline-size; min-width: 0; }
.coordination-canvas-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-1); margin-block: var(--space-2); }
.coordination-zoom-label { color: var(--text-secondary); font-size: var(--font-size-xs); font-variant-numeric: tabular-nums; }
.coordination-graph-viewport {
  min-width: 0; max-width: 100%; max-height: min(48vh, 36rem); overflow: auto; overscroll-behavior: contain;
  border: 1px solid var(--border); border-radius: var(--radius); background: var(--bg-primary);
  background-image: radial-gradient(var(--border) 1px, transparent 1px); background-size: var(--space-4) var(--space-4);
}
.coordination-graph-viewport:focus-visible { outline: var(--control-edge-inset) solid var(--accent); box-shadow: var(--focus-ring); }
.coordination-graph-sheet {
  --graph-width: var(--graph-width-3); --graph-height: var(--graph-height-3);
  width: calc(var(--graph-width) * var(--space-4) * var(--coordination-zoom, 1));
  height: calc(var(--graph-height) * var(--space-4) * var(--coordination-zoom, 1));
}
.coordination-graph-stage {
  position: relative; width: calc(var(--graph-width) * var(--space-4)); height: calc(var(--graph-height) * var(--space-4));
  transform: scale(var(--coordination-zoom, 1)); transform-origin: top left;
}
.coordination-graph-edges { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
.coordination-graph-edges:not([data-columns="3"]) { display: none; }
.coordination-graph-edges path { fill: none; stroke: var(--text-tertiary); stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.coordination-graph-edges [data-edge-kind="dispatch"] { stroke-dasharray: 4 4; }
.coordination-graph-edges [data-edge-kind="dependency"] { stroke: var(--accent); stroke-width: 2; }
.coordination-graph-edges [data-edge-kind="rework"] { stroke: var(--warning-text); stroke-dasharray: 2 3; }
.coordination-graph-node {
  --graph-x: var(--graph-x-3); --graph-y: var(--graph-y-3);
  position: absolute; left: calc(var(--graph-x) * var(--space-4)); top: calc(var(--graph-y) * var(--space-4));
  width: calc(14 * var(--space-4)); height: calc(7 * var(--space-4)); box-sizing: border-box;
  display: grid; grid-template-columns: var(--space-4) minmax(0, 1fr); align-content: start; align-items: start; gap: var(--space-2);
  padding: var(--space-2); border: 1px solid var(--border); border-radius: var(--radius);
  background: var(--bg-primary); box-shadow: var(--shadow-sm); color: var(--text-primary);
}
.coordination-graph-node[data-node-kind="coordinator"] { border-color: var(--accent); background: var(--accent-subtle); }
.coordination-graph-node[data-node-kind="reference"] { border-style: dashed; }
.coordination-graph-node[data-selected="true"] { outline: var(--control-edge-inset) solid var(--accent); }
.coordination-graph-node button { min-width: 0; max-height: calc(4 * var(--space-4)); overflow: hidden; justify-content: flex-start; text-align: start; }
.coordination-node-title { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; overflow: hidden; line-height: var(--leading-tight); }
.coordination-node-signal { display: inline-flex; align-items: center; justify-content: center; min-height: var(--space-6); font-size: var(--font-size-lg); color: var(--text-secondary); }
.coordination-graph-node[data-status="running"] .coordination-node-signal { color: var(--accent); }
.coordination-graph-node[data-status="completed"] .coordination-node-signal { color: var(--success-text); }
.coordination-graph-node[data-status="failed"] .coordination-node-signal { color: var(--error-text); }
.coordination-graph-node[data-status="blocked"] .coordination-node-signal { color: var(--warning-text); }
.coordination-node-digest { grid-column: 1 / -1; color: var(--text-secondary); font-size: var(--font-size-xs); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.coordination-node-inspector { display: flex; flex-direction: column; align-items: flex-start; gap: var(--space-2); padding: var(--space-3); margin-block-start: var(--space-2); background: var(--bg-primary); border-inline-start: var(--space-1) solid var(--accent); border-radius: var(--radius-sm); overflow-wrap: anywhere; }
.coordination-node-inspector[hidden] { display: none; }
.coordination-node-inspector > * { min-width: 0; max-width: 100%; }
.coordination-node-inspector p { font-size: var(--font-size-sm); }
.coordination-edge-legend { display: flex; flex-wrap: wrap; gap: var(--space-3); padding-block: var(--space-2); color: var(--text-secondary); font-size: var(--font-size-xs); }
.coordination-edge-legend span { display: inline-flex; align-items: center; gap: var(--space-1); }
.coordination-edge-legend span::before { content: ''; width: var(--space-4); border-top: 1px dashed var(--text-tertiary); }
.coordination-edge-legend [data-edge-legend="dependency"]::before { border-top: 2px solid var(--accent); }
.coordination-edge-legend [data-edge-legend="rework"]::before { border-color: var(--warning-text); border-top-style: dotted; }
.coordination-canvas-empty { padding: var(--space-3); color: var(--text-secondary); font-size: var(--font-size-sm); }
.coordination-graph-coverage { color: var(--text-secondary); font-size: var(--font-size-xs); }
.coordination-graph-coverage summary { cursor: pointer; font-weight: var(--weight-regular); }
.coordination-graph-coverage small { display: block; padding-block-start: var(--space-1); }
@container coordination-canvas (max-width: 800px) {
  .coordination-graph-sheet { --graph-width: var(--graph-width-2); --graph-height: var(--graph-height-2); }
  .coordination-graph-node { --graph-x: var(--graph-x-2); --graph-y: var(--graph-y-2); }
  .coordination-graph-edges[data-columns="3"] { display: none; }
  .coordination-graph-edges[data-columns="2"] { display: block; }
}
@container coordination-canvas (max-width: 530px) {
  .coordination-graph-sheet { --graph-width: var(--graph-width-1); --graph-height: var(--graph-height-1); }
  .coordination-graph-node { --graph-x: var(--graph-x-1); --graph-y: var(--graph-y-1); }
  .coordination-graph-edges[data-columns="2"] { display: none; }
  .coordination-graph-edges[data-columns="1"] { display: block; }
}
@media (max-width: 480px) { .coordination-summary { padding: var(--space-2); } }

/* Coordinator attention is tied to a real assistant message, not task counts. */
.coordination-leader-unread { margin-inline-start: var(--space-2); color: var(--accent); }
.coordination-leader[data-unread="true"] .coordination-leader-meta { color: var(--text-primary); }
.coordination-report { color: var(--text-primary); margin-block-end: var(--space-2); padding: var(--space-2) var(--space-3); border: 1px solid var(--border); border-radius: var(--radius); background: var(--bg-primary); }
.coordination-report[data-unread="true"] { border-inline-start: var(--space-1) solid var(--accent); }
.coordination-report summary { cursor: pointer; overflow-wrap: anywhere; font-size: var(--font-size-sm); }
.coordination-report-kind { color: var(--text-secondary); font-size: var(--font-size-xs); margin-inline-end: var(--space-2); }
.coordination-report-body { display: flex; flex-direction: column; align-items: flex-start; gap: var(--space-2); padding-block-start: var(--space-3); max-height: min(30vh, 20rem); overflow: auto; }
.coordination-report-body p { margin: var(--space-0); white-space: pre-wrap; overflow-wrap: anywhere; font-size: var(--font-size-sm); }
.coordination-report-body small { color: var(--text-secondary); font-size: var(--font-size-xs); }
.coordination-report summary:focus-visible, .coordination-report-body:focus-visible { outline: var(--control-edge-inset) solid var(--accent); box-shadow: var(--focus-ring); }
.coordinator-budget-metrics,
.coordinator-budget-fields {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 12rem), 1fr));
  gap: var(--space-4);
}

.coordinator-budget,
.coordinator-budget-settings {
  min-width: 0;
  overflow-wrap: anywhere;
}

/* Lists are primary; topology and exact references are independent disclosures.
 * Cap the in-chat attachment so the ordinary conversation keeps its reading space. */
.coordination-work-list { min-width: 0; color: var(--text-primary); }
.coordination-work-rows { max-height: min(26vh, 18rem); overflow: auto; overscroll-behavior: contain; }
.coordination-workspace .coordination-work-rows { max-height: min(42vh, 28rem); }
.coordination-work-row { display: flex; flex-wrap: wrap; align-items: flex-start; gap: var(--space-2); padding-block: var(--space-2); border-block-end: 1px solid var(--border); min-width: 0; }
.coordination-work-body { flex: 1 1 14rem; min-width: 0; display: flex; flex-direction: column; gap: var(--space-1); }
.coordination-work-body strong { font-size: var(--font-size-sm); font-weight: var(--weight-semibold); line-height: var(--leading-tight); overflow-wrap: anywhere; }
.coordination-work-body small { font-size: var(--font-size-xs); color: var(--text-secondary); }
.coordination-work-digest { font-size: var(--font-size-xs); color: var(--text-secondary); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; }
.coordination-work-row[data-status="failed"] .coordination-work-status { color: var(--error-text); }
.coordination-work-row[data-status="blocked"] .coordination-work-status,
.coordination-work-row[data-status="waiting"] .coordination-work-status { color: var(--warning-text); }
.coordination-work-actions { display: flex; flex-wrap: wrap; align-items: flex-start; gap: var(--space-1); min-width: 0; max-width: 100%; }
.coordination-list-paging { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-2); padding-block-start: var(--space-2); }
.coordination-list-paging small { color: var(--text-secondary); font-size: var(--font-size-xs); }
.coordination-topology { min-width: 0; padding-block-start: var(--space-2); }
.coordination-topology > summary { font-size: var(--font-size-sm); cursor: pointer; }
.coordination-reference { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-1); min-width: 0; max-width: 100%; }
.coordination-reference details { min-width: 0; max-width: 100%; }
.coordination-reference summary { font-size: var(--font-size-xs); font-weight: var(--weight-regular); cursor: pointer; }
