  transition:background var(--motion-fast) var(--ease-standard),border-color var(--motion-fast) var(--ease-standard)
}
.new-chat-btn>svg{width:var(--space-4);height:var(--space-4);flex-shrink:0;color:var(--accent)}
.new-chat-btn:hover{background:var(--chat-primary-hover);border-color:var(--accent)}
.new-chat-btn:focus-visible{outline:calc(2 * var(--control-edge-inset)) solid var(--accent);outline-offset:calc(2 * var(--control-edge-inset))}
.new-chat-btn:active{background:var(--bg-active)}
/* new-folder-btn removed — folders use tab bar with "+" button */
/* ── Folder create/rename dialog ── */
.folder-dialog-overlay{position:fixed;inset:0;height:var(--vh100,100vh);background:rgba(0,0,0,0.5);z-index:9999;display:flex;align-items:center;justify-content:center;animation:fadeIn 0.15s ease}
.folder-dialog{background:var(--bg-secondary);border:1px solid var(--border-light);border-radius:var(--radius);padding:var(--space-5) var(--space-6);width:340px;max-width:90vw;box-shadow:0 8px 32px rgba(0,0,0,0.5)}
.folder-dialog-title{font-size:15px;font-weight:600;color:var(--text-primary);margin-bottom:14px}
.folder-dialog-input{width:100%;padding:9px var(--space-3);background:var(--bg-primary);border:1px solid var(--border);border-radius:var(--radius-xs);color:var(--text-primary);font-size:var(--font-size-lg);font-family:inherit;outline:none;transition:border-color var(--transition)}
.folder-dialog-input:focus{border-color:var(--accent)}
.folder-dialog-path{margin-top:var(--space-2)}
.folder-dialog-label{font-size:var(--font-size-md);font-weight:600;color:var(--text-secondary);margin:12px 1px 6px}
.folder-dialog-hint{font-size:var(--font-size-sm);color:var(--text-tertiary);margin:6px 1px 0}
/* ── Multi-path default-root picker ── */
.fpp{margin-top:2px}
.fpp-chips{display:flex;flex-wrap:wrap;gap:var(--space-1);min-height:26px;padding:var(--space-1);background:var(--bg-primary);border:1px solid var(--border);border-radius:var(--radius-xs)}
.fpp-chip{display:inline-flex;align-items:center;gap:6px;padding:3px 6px 3px 9px;background:var(--bg-tertiary);border:1px solid var(--border);border-radius:999px;font-size:var(--font-size-sm);color:var(--text-primary);max-width:100%}
.fpp-chip-primary{border-color:var(--accent)}
.fpp-chip-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:180px}
.fpp-chip-badge{font-size:10px;line-height:14px;padding:0 5px;border-radius:6px;background:var(--accent-subtle);color:var(--accent);font-weight:600}
.fpp-chip-x{display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;padding:0;border:none;background:transparent;color:var(--text-tertiary);cursor:pointer;border-radius:50%;font-size:14px;line-height:1}
.fpp-chip-x:hover{color:var(--text-primary);background:var(--bg-hover)}
.fpp-empty{font-size:var(--font-size-sm);color:var(--text-tertiary);padding:2px 4px}
.fpp-toolbar{display:flex;gap:var(--space-2);margin-top:var(--space-2)}
.fpp-path-input{flex:1;min-width:0;padding:6px var(--space-2);background:var(--bg-primary);border:1px solid var(--border);border-radius:var(--radius-xs);color:var(--text-primary);font-size:var(--font-size-md);font-family:inherit;outline:none}
