 * worker starts assembling the final Chinese, so it never doubles. */
.stream-content-tail-hidden{display:none}

/* Send-path auto-translate failed → original text was sent. Quiet amber pill
   under the user bubble; clicking it retranslates just that message. */
.translate-failed-notice{display:inline-flex;align-items:center;gap:7px;margin-top:var(--space-2);padding:5px 11px;font-size:11.5px;line-height:1.3;color:#fbbf24;background:rgba(245,158,11,0.08);border:1px solid rgba(245,158,11,0.22);border-radius:999px;cursor:pointer;user-select:none;transition:background .2s ease,border-color .2s ease}
.translate-failed-notice:hover{background:rgba(245,158,11,0.14);border-color:rgba(245,158,11,0.4)}
.translate-failed-notice .tfn-icon{flex-shrink:0;opacity:.9}
.translate-failed-notice .tfn-text{opacity:.92}
.translate-failed-notice .tfn-retry{margin-left:2px;padding-left:var(--space-2);border-left:1px solid rgba(245,158,11,0.3);font-weight:600;opacity:.85}
.translate-failed-notice:hover .tfn-retry{opacity:1;text-decoration:underline}
/* Display-translation terminal failure (assistant / critic / VU bubble): a
   quiet borderless inline retry line — no filled pill, no box, matching the
   "just typographic weight" understatement of the translate family. Muted
   tertiary text at rest; lifts to the accent color + spins its glyph on
   hover/focus to read as "click to retry". The full upstream error (429/402
   quota etc.) sits on the title tooltip. */
.translate-retry-line{display:inline-flex;align-items:center;gap:6px;margin-top:7px;font-size:11.5px;line-height:1.3;color:var(--text-tertiary);cursor:pointer;user-select:none;border-radius:var(--radius-sm);transition:color .18s ease}
.translate-retry-line:hover,.translate-retry-line:focus-visible{color:var(--accent);outline:none}
.translate-retry-line .trl-icon{flex-shrink:0;display:block;opacity:.75;transition:opacity .18s ease,transform .5s ease}
.translate-retry-line:hover .trl-icon,.translate-retry-line:focus-visible .trl-icon{opacity:1;transform:rotate(-180deg)}
.translate-retry-line .trl-text{opacity:.9}
.translate-retry-line:hover .trl-text{text-decoration:underline;text-underline-offset:2px}
/* Subtle inline translating indicator on user message — replaces the old separate ✨ bubble */
@keyframes translatePulse{0%,100%{opacity:.4}50%{opacity:1}}
/* ★ Perf: content-visibility:auto on search blocks — off-screen blocks skip layout/paint.
 * contain-intrinsic-size provides estimated height to preserve scrollbar accuracy. */
.search-result-item{padding:10px 14px;border-top:1px solid rgba(59,130,246,0.1);transition:background var(--transition)}.search-result-item:hover{background:rgba(59,130,246,0.04)}.search-result-title{font-size:var(--font-size-md);font-weight:600;color:#93c5fd;display:flex;align-items:center;gap:6px;flex-wrap:wrap}.search-result-title a{color:#93c5fd;text-decoration:none}.search-result-title a:hover{text-decoration:underline;color:#bfdbfe}.search-result-source{font-size:10px;color:var(--text-tertiary);padding:1px 6px;background:var(--bg-tertiary);border-radius:4px;font-family:'JetBrains Mono',monospace}.search-result-snippet{font-size:var(--font-size-sm);color:var(--text-secondary);margin-top:var(--space-1);line-height:1.5;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.search-result-url{font-size:10px;color:var(--text-tertiary);margin-top:3px;font-family:'JetBrains Mono',monospace;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.search-result-fetched{font-size:9px;color:#34d399;background:rgba(52,211,153,0.1);padding:1px 6px;border-radius:4px;font-family:'JetBrains Mono',monospace;margin-left:var(--space-1);white-space:nowrap}.search-result-fetched.pdf{color:#f59e0b;background:rgba(245,158,11,0.1)}

/* ── Vertical-domain card (HF Papers / Semantic Scholar / arXiv / etc.) ── */
.vertical-card{margin:6px 14px 10px;border:1px solid rgba(168,85,247,0.25);border-radius:var(--radius-sm);background:linear-gradient(180deg,rgba(168,85,247,0.06),rgba(99,102,241,0.04));overflow:hidden}
.vertical-card-header{display:flex;align-items:center;gap:var(--space-2);padding:7px var(--space-3);background:rgba(168,85,247,0.08);border-bottom:1px solid rgba(168,85,247,0.15);font-size:var(--font-size-sm)}
.vertical-card-icon{display:inline-flex;align-items:center;color:#c4b5fd;flex-shrink:0}
.vertical-card-title{font-weight:600;color:#c4b5fd;letter-spacing:0.2px}
.vertical-card-sources{font-size:var(--font-size-xs);color:var(--text-tertiary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;min-width:0}
.vertical-card-count{font-size:10px;font-family:'JetBrains Mono',monospace;color:var(--text-muted);background:rgba(168,85,247,0.10);padding:1px 7px;border-radius:8px}
.vertical-card-body{padding:var(--space-1) 0}
.vertical-row{padding:7px 14px;border-top:1px solid rgba(168,85,247,0.10)}
.vertical-row:first-child{border-top:none}
.vertical-row:hover{background:rgba(168,85,247,0.04)}
.vertical-row-title{font-size:var(--font-size-md);font-weight:600;color:#ddd6fe;line-height:1.35}
.vertical-row-title a{color:#ddd6fe;text-decoration:none}
.vertical-row-title a:hover{text-decoration:underline;color:#ede9fe}
.vertical-row-meta{display:flex;flex-wrap:wrap;gap:6px;margin-top:3px}
.vertical-meta-pill{font-size:10px;color:#c4b5fd;background:rgba(168,85,247,0.10);padding:1px 7px;border-radius:4px;font-family:'JetBrains Mono',monospace;white-space:nowrap}
.vertical-row-snippet{font-size:var(--font-size-sm);color:var(--text-secondary);margin-top:var(--space-1);line-height:1.5;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.vertical-card-more{padding:6px 14px;font-size:var(--font-size-xs);color:var(--text-muted);text-align:center;font-style:italic}
.ptool-badge.vertical-badge{background:rgba(168,85,247,0.15);color:#c4b5fd;border:1px solid rgba(168,85,247,0.25);text-transform:capitalize;max-width:40%;overflow:hidden;text-overflow:ellipsis;flex-shrink:1;min-width:0}

/* ── Vertical card: light/tofu theme contrast overrides ──
 *    The default palette is tuned for the dark theme (pale lavender on
 *    translucent purple).  On the cream (tofu) and light themes that text
 *    washes out to near-invisible, so we darken titles/meta and warm the
 *    card to match each theme. */
[data-theme="light"] .vertical-card{border-color:rgba(124,58,237,0.28);background:linear-gradient(180deg,rgba(124,58,237,0.05),rgba(99,102,241,0.03))}
[data-theme="light"] .vertical-card-header{background:rgba(124,58,237,0.07);border-bottom-color:rgba(124,58,237,0.16)}
[data-theme="light"] .vertical-card-icon,[data-theme="light"] .vertical-card-title{color:#6d28d9}
[data-theme="light"] .vertical-card-count{color:#6d28d9;background:rgba(124,58,237,0.1)}
[data-theme="light"] .vertical-row{border-top-color:rgba(124,58,237,0.1)}
[data-theme="light"] .vertical-row:hover{background:rgba(124,58,237,0.05)}
[data-theme="light"] .vertical-row-title,[data-theme="light"] .vertical-row-title a{color:#5b21b6}
[data-theme="light"] .vertical-row-title a:hover{color:#4c1d95}
[data-theme="light"] .vertical-meta-pill{color:#6d28d9;background:rgba(124,58,237,0.1)}
[data-theme="light"] .ptool-badge.vertical-badge{color:#6d28d9;background:rgba(124,58,237,0.12);border-color:rgba(124,58,237,0.28)}

[data-theme="tofu"] .vertical-card{border:2px solid rgba(150,120,170,0.4);border-radius:var(--radius);background:rgba(150,120,170,0.05);box-shadow:var(--clay-sm)}
[data-theme="tofu"] .vertical-card-header{background:rgba(150,120,170,0.1);border-bottom-color:rgba(150,120,170,0.25)}
[data-theme="tofu"] .vertical-card-icon,[data-theme="tofu"] .vertical-card-title{color:#7A5C8A}
[data-theme="tofu"] .vertical-card-sources{color:#716A55}
[data-theme="tofu"] .vertical-card-count{color:#7A5C8A;background:rgba(150,120,170,0.14);border-radius:var(--radius)}
[data-theme="tofu"] .vertical-row{border-top-color:rgba(150,120,170,0.14)}
[data-theme="tofu"] .vertical-row:hover{background:rgba(150,120,170,0.06)}
[data-theme="tofu"] .vertical-row-title,[data-theme="tofu"] .vertical-row-title a{color:#5E4670}
[data-theme="tofu"] .vertical-row-title a:hover{color:#4A3656}
[data-theme="tofu"] .vertical-row-snippet{color:#716A55}
[data-theme="tofu"] .vertical-meta-pill{color:#7A5C8A;background:rgba(150,120,170,0.12);border-radius:var(--radius-sm)}
[data-theme="tofu"] .ptool-badge.vertical-badge{color:#7A5C8A;background:rgba(150,120,170,0.12);border:1px solid rgba(150,120,170,0.3);border-radius:var(--radius-sm);box-shadow:var(--clay-sm)}

/* ── Engine Breakdown section (inside search results panel) ── */
.eb-section{border-top:1px solid rgba(59,130,246,0.15);margin-top:var(--space-1);padding:0}.eb-toggle{display:flex;align-items:center;gap:6px;padding:var(--space-2) 14px;font-size:var(--font-size-xs);color:var(--text-tertiary);cursor:pointer;user-select:none;transition:background var(--transition)}.eb-toggle:hover{background:rgba(59,130,246,0.04)}.eb-total{font-size:10px;color:var(--text-muted);font-family:'JetBrains Mono',monospace}.eb-arrow{font-size:10px;margin-left:auto;transition:transform .2s ease}.eb-section.eb-expanded .eb-arrow{transform:rotate(90deg)}.eb-content{max-height:0;overflow:hidden;transition:max-height .3s ease}.eb-section.eb-expanded .eb-content{max-height:2000px}.eb-engine{padding:var(--space-1) 14px 6px}.eb-engine-name{font-size:var(--font-size-xs);font-weight:600;color:#60a5fa;margin-bottom:2px}.eb-engine-count{font-weight:400;color:var(--text-tertiary);font-size:10px}.eb-engine-urls{padding-left:var(--space-2);border-left:2px solid rgba(59,130,246,0.15)}.eb-url-item{padding:2px 0 2px var(--space-2);font-size:var(--font-size-xs);line-height:1.4}.eb-url-item a{color:var(--text-secondary);text-decoration:none}.eb-url-item a:hover{text-decoration:underline;color:#93c5fd}.eb-url-text{font-size:9px;color:var(--text-muted);font-family:'JetBrains Mono',monospace;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.error-block{padding:var(--space-3) var(--space-4);border:1px solid var(--error-border);border-radius:var(--radius-sm);background:var(--error-bg);font-size:var(--font-size-md);color:var(--error-text);overflow:hidden;word-break:break-word;white-space:pre-wrap;line-height:1.55}.stream-status{font-size:var(--font-size-xs);color:var(--text-tertiary);padding:var(--space-1) 0;display:flex;align-items:center;gap:6px;font-family:'JetBrains Mono',monospace}.stream-status .pulse{width:6px;height:6px;background:var(--thinking-text);border-radius:50%;animation:pulse 1.5s infinite}.stream-phase{display:flex;align-items:flex-start;gap:var(--space-2);padding:var(--space-2) 14px;margin-top:var(--space-2);border-radius:var(--radius-sm);background:linear-gradient(135deg,rgba(110,86,207,0.08),rgba(59,130,246,0.08));border:1px solid rgba(110,86,207,0.15);font-size:var(--font-size-sm);line-height:1.5;font-family:'JetBrains Mono',monospace;color:var(--accent);transition:opacity .3s ease}.stream-phase-icon{flex-shrink:0;display:inline-flex;align-items:center;height:1.5em}.stream-phase-text{flex:1;min-width:0;opacity:0.85;line-height:1.5;white-space:normal;overflow-wrap:anywhere;word-break:break-word}.stream-phase-ctx{display:inline;margin-left:6px;opacity:0.6;font-size:var(--font-size-xs)}.stream-phase-dots{display:inline-flex;gap:1px;margin-left:2px}.stream-phase-dots span{animation:phaseDot 1.4s infinite;opacity:0;font-weight:bold}.stream-phase-dots span:nth-child(2){animation-delay:0.2s}.stream-phase-dots span:nth-child(3){animation-delay:0.4s}@keyframes phaseDot{0%,80%,100%{opacity:0}40%{opacity:1}}@keyframes phaseIconPulse{0%,100%{opacity:0.6;transform:scale(1)}50%{opacity:1;transform:scale(1.1)}}.stream-phase-retrying{background:linear-gradient(135deg,rgba(245,158,11,0.10),rgba(234,179,8,0.06));border-color:rgba(245,158,11,0.20);color:#f59e0b}.stream-phase-retrying .stream-phase-icon{animation:phaseIconPulse 1.5s ease-in-out infinite}.stream-phase-thinking{background:linear-gradient(135deg,rgba(168,85,247,0.10),rgba(139,92,246,0.06));border-color:rgba(168,85,247,0.20)}.stream-phase-thinking .stream-phase-icon{animation:phaseIconPulse 2s ease-in-out infinite}.stream-phase-counter{display:inline-block;margin-left:var(--space-2);padding:1px 7px;border-radius:8px;background:rgba(168,85,247,0.15);font-size:10px;font-weight:600;color:rgba(196,167,255,0.85);letter-spacing:0.3px;min-width:48px;text-align:center;transition:background .2s ease}@keyframes pulse{0%,100%{opacity:.4}50%{opacity:1}}@keyframes searchOrbit{0%{transform:rotate(0deg) translateX(10px) rotate(0deg)}100%{transform:rotate(360deg) translateX(10px) rotate(-360deg)}}.search-orbit-container{width:22px;height:22px;position:relative;display:inline-block;flex-shrink:0}.search-orbit-center{position:absolute;inset:6px;border-radius:50%;background:var(--search-blue);opacity:.6;animation:pulse 1.2s infinite}.search-orbit-dot{position:absolute;width:4px;height:4px;border-radius:50%;top:50%;left:50%;margin:-2px;animation:searchOrbit 1.2s linear infinite}.search-orbit-dot:nth-child(2){background:#60a5fa}.search-orbit-dot:nth-child(3){background:#a78bfa;animation-delay:-.4s}.search-orbit-dot:nth-child(4){background:#34d399;animation-delay:-.8s}
/* Completed reply awaiting a look: quiet accent, distinct from success/error. */
.conv-review-dot {
  width:var(--space-2);height:var(--space-2);border-radius:var(--radius-pill);
  background:var(--accent);flex-shrink:0;
}
.conv-status-review {
  color:var(--text-primary);background:var(--accent-subtle);animation:none;
}
/* Sidebar defaults editor. Project chrome/controls belong to the UI kit;
   this owner only supplies workbench layout and evidence hierarchy. */
.folder-settings{display:flex;flex:1;flex-direction:column;gap:var(--space-4);min-width:0;min-height:0}
.folder-settings-content{display:flex;flex-direction:column;gap:var(--space-4);min-height:0;overflow:auto}
.folder-settings-fields{display:flex;flex-direction:column;gap:var(--space-5);border:0;padding:0;margin:0;min-width:0}
.folder-settings-identity{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:var(--space-4)}
.folder-settings-workbench{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:var(--space-4);align-items:start;min-width:0}
.folder-settings-workspace,.folder-settings-recents{padding:var(--space-4);border:var(--project-panel-width) solid var(--text-primary);border-radius:var(--radius);background:var(--bg-primary);min-width:0}
.folder-settings-workspace{display:flex;flex-direction:column;gap:var(--space-3)}
.folder-settings-section-heading{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2)}
.folder-settings-count{display:inline-flex;align-items:center;justify-content:center;min-width:var(--space-6);height:var(--space-6);border-radius:var(--radius-pill);background:var(--bg-tertiary);color:var(--text-primary);font-size:var(--font-size-sm);font-weight:var(--weight-semibold)}
.folder-settings-heading{margin:0;font-size:var(--font-size-lg);font-weight:var(--weight-bold);color:var(--text-primary)}
.folder-settings-hint{margin:0;font-size:var(--font-size-md);line-height:var(--leading-body);color:var(--text-secondary);overflow-wrap:anywhere}
.folder-settings-roots{display:flex;flex-direction:column;gap:var(--space-2);list-style:none;padding:0;margin:0;min-width:0;max-height:calc(var(--control-h-lg) * 7);overflow:auto}
.folder-settings-root{display:flex;flex-direction:column;gap:var(--space-2);padding:var(--space-3);background:var(--bg-secondary);border:var(--control-edge-inset) solid var(--border);border-radius:var(--radius-sm);min-width:0}
.folder-settings-root[data-primary="true"]{border-color:var(--accent);background:var(--bg-tertiary)}
.folder-settings-root-name{font-size:var(--font-size-lg);font-weight:var(--weight-semibold);color:var(--text-primary);overflow-wrap:anywhere}
.folder-settings-full-path{font-family:var(--font-mono);font-size:var(--font-size-sm);line-height:var(--leading-body);overflow-wrap:anywhere;color:var(--text-secondary);user-select:text}
.folder-settings-root-actions,.folder-settings-actions{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-2)}
.folder-settings-footer{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;flex-shrink:0;gap:var(--space-2);padding-top:var(--space-4);border-top:var(--control-edge-inset) solid var(--border)}
.folder-settings-empty{padding:var(--space-2) 0;font-size:var(--font-size-md);color:var(--text-secondary);line-height:var(--leading-body)}
.folder-settings-status{margin:0;color:var(--text-secondary);font-size:var(--font-size-sm);overflow-wrap:anywhere}
.folder-settings-status:empty,.folder-settings-hint:empty{display:none}

/* Exact paths remain announced without duplicating each selected-root card. */
.folder-settings-announcement{position:absolute;width:var(--control-edge-inset);height:var(--control-edge-inset);overflow:hidden;clip-path:inset(50%)}
.folder-settings-error{padding:var(--space-3);margin:0;border:var(--control-edge-inset) solid var(--error-border);border-radius:var(--radius-sm);background:var(--error-bg);color:var(--error-text);font-size:var(--font-size-md);line-height:var(--leading-body);overflow-wrap:anywhere}
.folder-settings-browser{display:flex;flex-direction:column;gap:var(--space-3);padding-top:var(--space-3);border-top:var(--control-edge-inset) solid var(--border);min-width:0}
.folder-settings-browser[hidden],.folder-settings-error[hidden]{display:none}
.folder-settings-directories,.folder-settings-recent-list{display:flex;flex-direction:column;align-items:stretch;gap:var(--space-2);max-height:calc(var(--control-h-lg) * 7);overflow:auto;min-width:0}
.folder-settings-directory-name{width:100%;text-align:start;overflow-wrap:anywhere}

.folder-settings-directories>button,.folder-settings-recent-list>button{flex-shrink:0}
.folder-settings-recents>summary{cursor:pointer;color:var(--text-primary);font-size:var(--font-size-lg);font-weight:var(--weight-bold);min-height:var(--control-h-sm);line-height:var(--leading-body)}
.folder-settings-recents[open]>summary{margin-bottom:var(--space-3)}
.folder-settings-recents>summary:focus-visible{outline:none;box-shadow:var(--focus-ring);border-radius:var(--radius-sm)}
.folder-settings-recent-copy{display:flex;flex-direction:column;gap:var(--space-1);width:100%;min-width:0;text-align:start;padding:var(--space-2);border:var(--control-edge-inset) solid var(--border);border-radius:var(--radius-sm);background:var(--bg-secondary)}
.folder-settings-recent-name{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:var(--font-size-lg);font-weight:var(--weight-semibold);color:var(--text-primary)}
.folder-settings-recent-path{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:var(--font-mono);font-size:var(--font-size-sm);font-weight:var(--weight-regular);color:var(--text-secondary);line-height:var(--leading-body)}
.folder-settings-delete-name{margin:0;color:var(--text-primary);font-weight:var(--weight-semibold);overflow-wrap:anywhere}
.folder-tab-copy{display:flex;flex:1;min-width:0;text-align:start}
/* Root details remain in the tooltip/settings, not a second row per tile. */
.folder-tab-summary{display:none}
/* Navigation is not a card/button surface. Scope above generic theme button
   chrome; keep the shared controls inside the settings dialog unchanged. */
#folderTabs.project-rail{background:var(--bg-secondary);border-inline-end:var(--control-edge-inset) solid var(--border)}
#folderTabs .project-rail-title,#folderTabs .project-rail-collapse{color:var(--text-secondary)}
#folderTabs .folder-tab-inbox-dot,#folderTabs .folder-tab-add-dot{color:var(--text-secondary)}
#folderTabs .folder-tab.active::before{background:var(--accent)}
#folderTabs .folder-tab{border:0;box-shadow:none;background:transparent;color:var(--text-primary);font-family:var(--font-ui);min-height:var(--control-h-lg);font-weight:var(--weight-medium);padding-inline-end:calc(var(--control-h-sm) + var(--space-2));transform:none}
#folderTabs .folder-tab:hover{background:var(--bg-hover);color:var(--text-primary)}
#folderTabs .folder-tab.active{background:var(--accent-subtle);color:var(--text-primary);font-weight:var(--weight-semibold)}
#folderTabs .folder-tab-uncat{margin-block-end:var(--space-2)}
#folderTabs .folder-tab-count{position:absolute;inset-inline-end:var(--space-2);width:var(--control-h-sm);min-width:0;height:auto;line-height:inherit;padding:0;border-radius:0;background:transparent;color:var(--text-secondary);font-size:var(--font-size-xs);font-weight:var(--weight-regular);font-variant-numeric:tabular-nums;text-align:end}
#folderTabs .folder-tab-settings{position:absolute;inset-inline-end:var(--space-2);opacity:0;pointer-events:none;background:transparent;color:var(--text-secondary);border:0;box-shadow:none;transform:none}
#folderTabs .folder-tab-row:hover .folder-tab-settings,#folderTabs .folder-tab-row:focus-within .folder-tab-settings{opacity:1;pointer-events:auto}
#folderTabs .folder-tab-row:hover .folder-tab-count,#folderTabs .folder-tab-row:focus-within .folder-tab-count{visibility:hidden}
#folderTabs .folder-tab.folder-tab-drop{background:var(--accent-subtle);box-shadow:inset 0 0 0 var(--control-edge-inset) var(--accent)}
#folderTabs .folder-tab:focus-visible,#folderTabs .folder-tab-settings:focus-visible{box-shadow:var(--focus-ring)}
.sidebar.rail-collapsed .folder-tab-copy{display:none}
.sidebar.rail-collapsed #folderTabs .folder-tab{padding-inline-end:0}
.sidebar.rail-collapsed #folderTabs .folder-tab.active{background:transparent}
.sidebar.rail-collapsed #folderTabs .folder-tab-uncat{margin-block-end:0}
.sidebar.rail-collapsed #folderTabs .folder-tab-settings{display:none;inset-inline-end:0;inset-block-start:0}
.folder-tab:focus-visible,.project-rail-collapse:focus-visible,.folder-tab-menu-item:focus-visible{outline:none;box-shadow:var(--focus-ring)}
/* Touch keeps the menu visible beside the count; inbox reserves the same
   two slots so its count still aligns with every project. */
