.upd-hero{display:flex;align-items:center;justify-content:center;gap:calc(var(--space-1) * 2.5);padding:var(--space-5) calc(var(--space-1) * 4.5);background:linear-gradient(180deg,var(--bg-tertiary),var(--bg-secondary));border:1px solid var(--border);border-radius:14px;margin-bottom:calc(var(--space-1) * 4.5)}
