.upd-apply-btn{margin-top:var(--space-4);width:100%;padding:calc(var(--space-1) * 2.75) var(--space-4);background:var(--accent);color:var(--text-on-accent);border:none;border-radius:10px;font-size:var(--font-size-lg);font-weight:700;cursor:pointer;transition:background-color .15s ease,opacity .15s ease;display:flex;align-items:center;justify-content:center;gap:var(--space-2)}
