/* Pending lifecycle approvals (human-approval gate, pt_40d00fd526e5479a) */
.upd-lc-card{margin-top:var(--space-4);padding:var(--space-3) calc(var(--space-1) * 3.5);border:1px solid var(--border);border-radius:12px;background:var(--bg-tertiary)}
