.upd-restart.is-preparing .upd-restart-fill::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,color-mix(in srgb, var(--text-on-accent) 55%, transparent),transparent);transform:translateX(-100%);animation:updRestartPrepareSweep 1.35s ease-in-out infinite}
@keyframes updRestartPrepareSweep{to{transform:translateX(100%)}}
.upd-restart.is-online .upd-restart-fill{background:linear-gradient(90deg,var(--success-text),var(--success-text))}
