.upd-restart-now-btn{display:inline-flex;align-items:center;gap:calc(var(--space-1) * 1.75);padding:var(--space-2) calc(var(--space-1) * 3.5);background:transparent;color:var(--text-secondary);border:1px solid var(--border);border-radius:9px;font-size:var(--font-size-md);font-weight:600;cursor:pointer;transition:background-color .15s ease,color .15s ease,border-color .15s ease}
