.mic-btn{position:relative;display:inline-flex;width:32px;height:32px;min-width:32px;background:none;border:none;border-radius:8px;cursor:pointer;align-items:center;justify-content:center;color:var(--text-tertiary);transition:color .2s,background-color .2s,transform .15s;flex-shrink:0;padding:0;-webkit-tap-highlight-color:transparent}
