/* ── Toolbar Sub-menus ── */
.toolbar-submenu{position:relative;flex-shrink:0}
.submenu-trigger{display:flex;align-items:center;gap:var(--space-1);padding:var(--space-1) 10px;min-height:32px;box-sizing:border-box;background:none;border:1px solid transparent;border-radius:10px;cursor:pointer;color:var(--text-tertiary);font-size:var(--font-size-sm);font-weight:600;font-family:'Jakarta Toolbar','Plus Jakarta Sans','Jakarta Fallback',sans-serif;transition:all .15s ease;white-space:nowrap;line-height:1}
.submenu-trigger:hover{color:var(--text-primary);background:var(--bg-hover);border-color:var(--border-light)}
