.submenu-dropdown{position:absolute;bottom:calc(100% + 8px);left:50%;min-width:236px;background:var(--bg-secondary);border:1px solid var(--border-light);border-radius:14px;box-shadow:var(--submenu-shadow,0 12px 40px rgba(0,0,0,0.36),0 2px 10px rgba(0,0,0,0.18));padding:5px;z-index:100;opacity:0;visibility:hidden;transform:translateX(-50%) translateY(6px) scale(.97);transform-origin:bottom center;transition:opacity .16s ease,transform .18s cubic-bezier(0.16,1,0.3,1),visibility .16s ease}
