/* ═══════════════════════════════════════════════════════════
   PORTRAIT-TABLET READING MODE  (769px–1024px, coarse pointer)
   ───────────────────────────────────────────────────────────
   The single-pane block above (`≤768 ∪ (≤1024 ∧ coarse)`) correctly collapses
   the side-by-side split into one full-screen pane + bottom switcher on a
   portrait tablet — but it applies the SAME 360px-phone compaction it uses for
   a true handset: 14px reader padding, shrunk 12px tab buttons, tiny
   arxiv-search rows. A ~900px-wide tablet has plenty of room; that cramped
   treatment wastes it and yields finger-hostile targets. This block runs AFTER
   the shared one (source order) so it re-inflates the reading surface for the
   tablet form factor only, WITHOUT touching the ≤768 phone. Keep the width
   bounds in sync with the chat tablet-drawer block + core.js TOFU_BP.tablet. */
@media(min-width:769px) and (max-width:1024px) and (pointer:coarse){
  /* Roomier reading gutters — closer to the desktop 20px than the phone 14px,
   * so long-form prose isn't jammed against the pane edges on a tablet. */
  .paper-report-content,.paper-report-body{padding:var(--space-6) 28px}
  [data-theme="tofu"] .paper-pdf-container{padding:var(--space-5)}

  /* Bottom switcher is a touch bar — give the two targets a comfortable height
   * and label size (the base 54px min from --paper-switch-h stays). */
  .paper-mobile-switch-btn{font-size:var(--font-size-lg)}

  /* Reader tabs (Q&A / Report / Babel) — restore roomy, tappable pills instead
   * of the phone's cramped 10px/6px. */
  .paper-tab-btn{padding:var(--space-3) var(--space-4);font-size:var(--font-size-md);gap:6px}
  .paper-tab-btn svg{width:15px;height:15px}
  [data-theme="tofu"] .paper-tab-btn{padding:var(--space-3) var(--space-4);font-size:var(--font-size-md)}

  /* Reader comfort controls + PDF toolbar buttons → 36px touch targets. */
  .paper-reader-set-btn{height:36px;min-width:40px}
  .paper-toolbar-btn{width:36px;height:34px}

  /* The arxiv landing keeps its comfortable desktop row on a tablet (the phone
   * block stacks it into a full-width column + hides the search icon — overkill
   * for ~900px). Undo that stacking. */
  .paper-arxiv-input{flex-direction:row}
  .paper-arxiv-input .paper-arxiv-search-icon{display:inline-flex}
  .paper-arxiv-btn{width:auto}
  .paper-landing{padding:36px var(--space-8)}

  /* Library rows in the drawer get a touch-comfortable size (mirrors the phone
   * treatment — a tablet drawer is still finger-driven). */
  .paper-lib-item{padding:14px;min-height:48px}
}

/* ═══════════════════════════════════════════════════
   ★ Paper Reading Mode — Per-Theme Flair
   Each theme transforms Reading Mode into a distinct
   reading environment. Dark = Midnight Scholar's Desk
   with aurora glow + glass panels. Light = Modern
   Reading Room with cream paper. Tofu = Cozy Study
   Nook with dashed stitches + claymorphic cards.
   ═══════════════════════════════════════════════════ */

/* ─────────────────────────────────────────
   DARK — Midnight Scholar's Desk
   Aurora gradient backdrop + glass-morphism
   panels + neon-underline active tab.
   ───────────────────────────────────────── */
html:not([data-theme="light"]):not([data-theme="tofu"]) .paper-mode-container,
[data-theme="dark"] .paper-mode-container{
  background:
    radial-gradient(1100px 700px at 8% -10%,rgba(99,102,241,0.16),transparent 60%),
    radial-gradient(900px 600px at 95% 110%,rgba(56,189,248,0.10),transparent 55%),
    radial-gradient(700px 500px at 60% 40%,rgba(168,85,247,0.07),transparent 65%),
    var(--bg-primary);
  position:relative;
}
html:not([data-theme="light"]):not([data-theme="tofu"]) .paper-mode-container::before,
[data-theme="dark"] .paper-mode-container::before{
  content:'';position:absolute;inset:0;pointer-events:none;z-index:0;
  background-image:
    radial-gradient(circle at 22% 18%,rgba(255,255,255,0.06) 0.6px,transparent 1.2px),
    radial-gradient(circle at 73% 62%,rgba(255,255,255,0.05) 0.5px,transparent 1px),
    radial-gradient(circle at 41% 83%,rgba(255,255,255,0.05) 0.6px,transparent 1.2px);
  background-size:240px 240px,320px 320px,180px 180px;
  opacity:0.7;
}
html:not([data-theme="light"]):not([data-theme="tofu"]) .paper-body,
[data-theme="dark"] .paper-body{position:relative;z-index:1}

html:not([data-theme="light"]):not([data-theme="tofu"]) .paper-left,
[data-theme="dark"] .paper-left{border-right:1px solid rgba(255,255,255,0.06)}
html:not([data-theme="light"]):not([data-theme="tofu"]) .paper-right,
[data-theme="dark"] .paper-right{
  background:linear-gradient(180deg,rgba(255,255,255,0.025),rgba(255,255,255,0.01));
  backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);
  border-left:1px solid rgba(255,255,255,0.04)
}

html:not([data-theme="light"]):not([data-theme="tofu"]) .paper-pdf-toolbar,
[data-theme="dark"] .paper-pdf-toolbar{
  background:linear-gradient(180deg,rgba(24,28,44,0.75),rgba(18,22,34,0.55));
  backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);
  border-bottom:1px solid rgba(255,255,255,0.06)
