/* ══════════════════════════════════════
   Auto Setup Modal
   ══════════════════════════════════════ */
.stg-modal-overlay {
  /* ── Design tokens (duplicated from .settings-panel so the modal,
       which is appended to <body>, inherits them correctly) ── */
  --s-white:     #faf8f3;
  --s-cream:     #f2ecda;
  --s-skin:      #e4d6bf;
  --s-board:     #35302a;
  --s-board-lit: #443c32;
  --s-gold:      #c9993f;
  --s-gold-dim:  #a87d2e;
  --s-gold-glow: rgba(201,153,63,0.18);
  --s-ink:       #1a1814;
  --s-ink-soft:  #3d362c;
  --s-done:      #4ade80;
  --s-blocked:   #f87171;
  --s-accent:    #6366f1;
  --s-danger:    #dc2626;
  --s-line:        rgba(26, 24, 20, 0.08);
  --s-line-strong: rgba(26, 24, 20, 0.15);
  --s-shadow:    0 4px 10px rgba(26, 24, 20, 0.06), 0 18px 44px rgba(26, 24, 20, 0.14);
  --s-shadow-md: 0 2px 4px rgba(26, 24, 20, 0.05), 0 8px 22px rgba(26, 24, 20, 0.10);
  --s-shadow-sm: 0 1px 2px rgba(26, 24, 20, 0.04), 0 3px 8px rgba(26, 24, 20, 0.06);
  --s-shadow-xs: 0 1px 2px rgba(26, 24, 20, 0.05);
  --s-border:    1px solid var(--s-line-strong);
  --s-border-sm: 1px solid var(--s-line);
  --s-radius:    9px;
  --s-radius-sm: 6px;
  --s-radius-lg: 14px;

  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: stgFadeIn 0.15s ease;
  font-family: 'Inter', 'SF Pro', -apple-system, system-ui, sans-serif;
}
@keyframes stgFadeIn { from { opacity: 0; } to { opacity: 1; } }
.stg-modal {
  background: var(--s-white);
  border: 1px solid rgba(26, 24, 20, 0.18);
  box-shadow: 0 24px 70px rgba(26, 24, 20, 0.3), 0 6px 22px rgba(26, 24, 20, 0.14);
  border-radius: var(--s-radius-lg);
  color: var(--s-ink);
  width: 520px;
  max-width: 95vw;
  max-height: 90vh;
  max-height: calc(var(--vh100,100vh)*0.9);
  overflow: auto;
  animation: stgSlideUp 0.2s ease;
}
@keyframes stgSlideUp { from { transform: translateY(20px); opacity: 0; } to { transform: none; opacity: 1; } }
.stg-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 18px var(--space-3);
  border-bottom: 1px solid var(--s-line);
}
.stg-modal-title {
  font-size: 15px;
  font-weight: 900;
  color: var(--s-ink);
}
.stg-modal-close {
  background: none; border: none; cursor: pointer;
  font-size: var(--font-size-2xl); color: var(--s-ink-soft);
  padding: 0 var(--space-1); line-height: 1;
}
.stg-modal-close:hover { color: var(--s-blocked); }
.stg-modal-body {
  padding: 18px;
}
.stg-modal-desc {
  font-size: var(--font-size-sm);
  color: var(--s-ink-soft);
  line-height: 1.6;
  margin-bottom: var(--space-4);
}
.stg-modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-2);
  padding: var(--space-3) 18px var(--space-4);
  border-top: 1px solid var(--s-cream);
}
.stg-required { color: var(--s-blocked); font-weight: 900; }

/* Auto-setup status messages */
.stg-auto-status {
  margin-top: var(--space-3);
  padding: 10px var(--space-3);
  border-radius: var(--s-radius);
  font-size: var(--font-size-sm);
  font-weight: 700;
  line-height: 1.5;
}
.stg-auto-loading {
  background: rgba(99, 102, 241, 0.08);
  color: #6366f1;
  border: 1.5px solid rgba(99, 102, 241, 0.25);
  animation: stgPulse 1.5s ease infinite;
}
@keyframes stgPulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}
.stg-auto-success {
  background: rgba(22, 163, 74, 0.08);
  color: #16a34a;
  border: 1.5px solid rgba(22, 163, 74, 0.25);
}
.stg-auto-error {
  background: rgba(239, 68, 68, 0.08);
  color: var(--s-blocked);
  border: 1.5px solid rgba(239, 68, 68, 0.25);
}

/* ══════════════════════════════════════
   Onboarding wizard (first-run)
   ── The overlay element is .modal-overlay (the e2e dismiss contract —
      tests/conftest.py strips `.open` from exactly that selector), NOT
      .stg-modal-overlay, so the .stg-* design tokens are re-declared on
      .ob-modal itself: var(--s-*) would otherwise resolve to nothing and
      the reused .stg-modal shell would render unstyled. ──
   ══════════════════════════════════════ */
.ob-modal {
  --s-white:     #faf8f3;
  --s-cream:     #f2ecda;
  --s-skin:      #e4d6bf;
  --s-board:     #35302a;
  --s-board-lit: #443c32;
  --s-gold:      #c9993f;
  --s-gold-dim:  #a87d2e;
  --s-gold-glow: rgba(201,153,63,0.18);
  --s-ink:       #1a1814;
  --s-ink-soft:  #3d362c;
  --s-done:      #4ade80;
  --s-blocked:   #f87171;
  --s-accent:    #6366f1;
  --s-danger:    #dc2626;
  --s-line:        rgba(26, 24, 20, 0.08);
  --s-line-strong: rgba(26, 24, 20, 0.15);
  --s-shadow:    0 4px 10px rgba(26, 24, 20, 0.06), 0 18px 44px rgba(26, 24, 20, 0.14);
  --s-shadow-md: 0 2px 4px rgba(26, 24, 20, 0.05), 0 8px 22px rgba(26, 24, 20, 0.10);
  --s-shadow-sm: 0 1px 2px rgba(26, 24, 20, 0.04), 0 3px 8px rgba(26, 24, 20, 0.06);
  --s-shadow-xs: 0 1px 2px rgba(26, 24, 20, 0.05);
  --s-border:    1px solid var(--s-line-strong);
  --s-border-sm: 1px solid var(--s-line);
  --s-radius:    9px;
  --s-radius-sm: 6px;
  --s-radius-lg: 14px;
  width: 560px;
  font-family: 'Inter', 'SF Pro', -apple-system, system-ui, sans-serif;
}
.ob-step-line {
  display: block;
  font-size: var(--font-size-xs);
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--s-gold-dim);
  margin-bottom: var(--space-2);
}
.ob-cards { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 14px 0 var(--space-1); }
.ob-card {
  border: var(--s-border-sm);
  border-radius: var(--s-radius);
  background: var(--s-white);
  padding: 14px 14px var(--space-3);
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.12s ease, border-color 0.12s ease;
}
.ob-card:hover, .ob-card:focus-visible {
  border-color: var(--s-gold);
  box-shadow: var(--s-shadow-sm);
  transform: translate(-2px, -2px);
  outline: none;
}
.ob-card-icon { color: var(--s-gold-dim); margin-bottom: var(--space-2); }
.ob-card-icon > svg { display: block; }
.ob-card-title { font-size: 13.5px; font-weight: 800; color: var(--s-ink); margin-bottom: var(--space-1); }
.ob-card-desc { font-size: 11.5px; line-height: 1.55; color: var(--s-ink-soft); }
.ob-note {
  margin: 10px 0 0;
  font-size: 11.5px;
  line-height: 1.6;
  color: var(--s-gold-dim);
}
.ob-done { text-align: center; padding: 18px 6px var(--space-2); }
.ob-done-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px; height: 52px;
  border: var(--s-border);
  border-radius: 50%;
  color: #16a34a;
  margin-bottom: var(--space-3);
}
.ob-done-title { font-size: var(--font-size-xl); font-weight: 900; color: var(--s-ink); margin-bottom: 6px; }
@media (max-width: 560px) {
  .ob-cards { grid-template-columns: 1fr; }
}

/* ── Icon / secondary / primary buttons ── */
.stg-btn-icon {
  background: none;
  border: 1.5px solid transparent;
  color: var(--s-ink-soft);
  cursor: pointer;
  padding: var(--space-1);
  border-radius: var(--s-radius);
  font-size: var(--font-size-md);
  transition: color 0.1s, background 0.1s, border-color 0.1s;
}
.stg-btn-icon:hover {
  color: var(--s-ink);
  background: var(--s-cream);
  border-color: var(--s-ink);
}
.stg-btn-icon.danger:hover {
  color: var(--s-blocked);
  background: rgba(248, 113, 113, 0.1);
  border-color: var(--s-blocked);
}
.stg-btn-secondary {
  background: linear-gradient(180deg, #ffffff 0%, #f6f1e3 100%);
  border: 1px solid var(--s-line-strong);
  color: var(--s-ink);
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: 5px var(--space-3);
  border-radius: var(--s-radius);
  cursor: pointer;
  box-shadow: inset 0 1px 0 #ffffff, 0 1px 2px rgba(26, 24, 20, 0.10), 0 3px 8px rgba(26, 24, 20, 0.06);
  transition: transform 0.12s, box-shadow 0.12s, background 0.12s, border-color 0.12s;
}
.stg-btn-secondary:hover {
  transform: translateY(-1px);
  box-shadow: inset 0 1px 0 #ffffff, 0 2px 4px rgba(26, 24, 20, 0.12), 0 8px 18px rgba(26, 24, 20, 0.09);
  background: linear-gradient(180deg, #ffffff 0%, #faf5e9 100%);
}
.stg-btn-secondary:active {
  transform: translateY(1px);
  background: linear-gradient(180deg, #f3eddd 0%, #efe8d6 100%);
  box-shadow: inset 0 2px 4px rgba(26, 24, 20, 0.09), 0 1px 2px rgba(26, 24, 20, 0.08);
}
.stg-btn-primary {
  background: linear-gradient(180deg, #e3ba66 0%, #cfa14a 52%, #bd8f39 100%);
  border: 1px solid #a87d2e;
  color: var(--s-ink);
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.26);
  font-size: var(--font-size-xs);
  font-weight: 800;
  padding: 5px 14px;
  border-radius: var(--s-radius);
  cursor: pointer;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.38), inset 0 -1px 0 rgba(122, 84, 20, 0.20),
    0 1px 2px rgba(26, 24, 20, 0.14), 0 4px 12px rgba(201, 153, 63, 0.26);
  transition: transform 0.12s, box-shadow 0.12s, background 0.12s, border-color 0.12s;
}
.stg-btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.44), inset 0 -1px 0 rgba(122, 84, 20, 0.20),
    0 2px 4px rgba(26, 24, 20, 0.15), 0 8px 20px rgba(201, 153, 63, 0.32);
  background: linear-gradient(180deg, #ecc576 0%, #d8a951 52%, #c69840 100%);
}
.stg-btn-primary:active {
  transform: translateY(1px);
  background: linear-gradient(180deg, #c89940 0%, #bd8f39 100%);
  box-shadow: inset 0 2px 5px rgba(122, 84, 20, 0.32), 0 1px 2px rgba(26, 24, 20, 0.10);
}

.stg-empty, .stg-loading {
  text-align: center;
  padding: var(--space-5) 0;
  color: var(--s-ink-soft);
  font-size: var(--font-size-sm);
  font-weight: 600;
}
.stg-empty-sm {
  text-align: center;
  padding: 10px 0;
  color: var(--s-ink-soft);
  font-size: var(--font-size-xs);
  margin: 0;
  font-weight: 600;
}

