}
[data-theme="light"] .ptool-truncated {
  color: rgba(140,100,0,0.6);
  background: rgba(180,140,0,0.04);
  border-color: rgba(180,140,0,0.15);
}
[data-theme="light"] .ptool-truncated:hover {
  color: rgba(140,100,0,0.85);
  background: rgba(180,140,0,0.08);
  border-color: rgba(180,140,0,0.3);
}

/* Tool row geometry and readable intent; one theme-token vocabulary, code remains in its evidence owners. */
.ptool-line {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-3) var(--space-1) var(--space-4);
  min-height: var(--control-h-sm);
  color: var(--text-secondary);
  font-size: var(--font-size-md);
  transition: background var(--motion-fast) var(--ease-standard);
}
.ptool-line:hover { background: var(--bg-hover); }
.ptool-line.ptool-active { color: var(--text-primary); }
.ptool-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: var(--space-4);
  color: var(--text-secondary);
}
.ptool-line.ptool-active .ptool-icon { color: var(--accent); }
.ptool-text {
