}
.ptool-cmd-header .ptool-root { margin-left: 2px; }
/* Tool badges and saved-output continuations. One token palette across themes;
 * artifact intent/patterns are visible, technical scope is disclosure evidence. */
.ptool-mcp-link {
  color: var(--accent);
  text-decoration: none;
  border-bottom: 1px dotted currentColor;
}
.ptool-mcp-link:hover { border-bottom-style: solid; }
.ptool-badge {
