.ptool-badge-info { color: var(--chip-info-color); background: var(--chip-info-bg); }
.ptool-badge-ok { color: var(--chip-ok-color); background: var(--chip-ok-bg); }
.ptool-badge-err { color: var(--chip-err-color); background: var(--chip-err-bg); }

.ptool-artifact-header {
