/* Hover — gentle wash */
[data-theme="tofu"] .conv-item:hover{
  background:var(--bg-hover);
  border-color:transparent;
  box-shadow:none
}
/* Active — quiet selected row with a slim accent edge */
[data-theme="tofu"] .conv-item.active{
  background:var(--accent-subtle);
  border:1px solid transparent;
  border-left:2px solid var(--accent);
  box-shadow:none
}
/* (retired) pixel cursor indicator */
[data-theme="tofu"] .conv-item.active::before{
  content:none;
  display:none
}
[data-theme="tofu"] .conv-item .conv-title{
  font-size:13.5px;font-weight:500;letter-spacing:0.01em;
  color:var(--text-primary)
}
/* Date line — quiet sans timestamp */
[data-theme="tofu"] .conv-item .conv-date{
