  font-size:var(--font-size-sm);line-height:1.3;
  max-width:280px;min-width:0;
  animation:convRefChipIn .2s ease-out;
  transition:border-color .15s, box-shadow .15s;
}
.conv-ref-chip:hover{
  border-color:rgba(199,146,234,.7);
