/* ═══════════════════════════════════════════════════════════════════════
 * Compaction Viewer — inline markers + right-side drawer
 * (see static/js/compaction-viewer.js)
 * ═══════════════════════════════════════════════════════════════════════ */

/* Inline chips rendered inside the assistant bubble when a compaction fired */
.compaction-marker-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 10px 0 var(--space-1);
  padding: var(--space-2) 10px;
  border-left: 2px dashed color-mix(in srgb, var(--accent) 55%, transparent);
  background: color-mix(in srgb, var(--accent) 6%, transparent);
  border-radius: 3px;
}
.compaction-marker {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  font-size: 11.5px;
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
  color: var(--text-secondary);
  background: var(--bg-elevated, rgba(255,255,255,0.03));
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  border-radius: 4px;
  cursor: pointer;
  transition: all 120ms ease;
  text-align: left;
  line-height: 1.35;
}
.compaction-marker:hover {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border-subtle, rgba(255,255,255,0.08)));
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  color: var(--text-primary);
  transform: translateY(-1px);
}
.compaction-marker.is-progress {
  animation: compactionMarkerPulse 1.6s ease-in-out infinite;
}
@keyframes compactionMarkerPulse {
  0%, 100% { opacity: 0.78; }
  50%      { opacity: 1; }
}
.compaction-marker-icon {
  display: inline-flex;
  color: color-mix(in srgb, var(--accent) 75%, var(--text-tertiary));
}
.compaction-marker-trigger {
  font-weight: 600;
  letter-spacing: 0.01em;
}
.compaction-marker-trigger svg { width: 12px; height: 12px; vertical-align: -2px; }
.pdf-attach-icon svg { width: 22px; height: 22px; vertical-align: middle; }
.compaction-marker-stat {
  color: var(--text-tertiary);
  font-size: var(--font-size-xs);
}
.compaction-marker-reason {
  color: color-mix(in srgb, #f59e0b 70%, var(--text-tertiary));
  font-size: 10.5px;
  font-style: italic;
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.compaction-marker-cta {
  margin-left: auto;
  padding: 1px 6px;
  font-size: 10px;
  color: var(--accent);
  border: 1px solid color-mix(in srgb, var(--accent) 45%, transparent);
  border-radius: 3px;
  opacity: 0.85;
}
.compaction-marker:hover .compaction-marker-cta {
  opacity: 1;
  background: color-mix(in srgb, var(--accent) 18%, transparent);
}

/* ── Manual /compact boundary card (chat_render.js _isCompactionSummary) ── */
.compact-card {
  margin: var(--space-2) 0;
  border: 1px solid color-mix(in srgb, var(--accent) 24%, var(--border));
  border-radius: 12px;
  background:
    linear-gradient(105deg,
      color-mix(in srgb, var(--accent) 8%, var(--bg-primary)) 0%,
      color-mix(in srgb, var(--accent) 3%, var(--bg-primary)) 58%,
      var(--bg-primary) 100%);
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--accent) 62%, transparent);
  overflow: hidden;
}
.compact-card-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) 10px;
  width: 100%;
  padding: 10px var(--space-3);
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text);
  text-align: left;
  font: inherit;
}
.compact-card-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
}
.compact-card-icon > svg { display: block; width: 16px; height: 16px; }
.compact-card-title { font-weight: 650; font-size: var(--font-size-md); letter-spacing: .005em; }
.compact-card-toggle {
  margin-left: auto;
  font-size: var(--font-size-xs);
  color: var(--accent);
  opacity: 0.85;
}
.compact-card-head:hover .compact-card-toggle { opacity: 1; }
.compact-card-head:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 70%, white);
  outline-offset: -3px;
}
.compact-card-body {
  padding: var(--space-2) 14px 13px;
  border-top: 1px solid color-mix(in srgb, var(--accent) 20%, transparent);
}
.compact-card[data-collapsed="1"] .compact-card-body { display: none; }
details.compact-card > summary.compact-card-head { list-style: none; }
details.compact-card > summary.compact-card-head::-webkit-details-marker { display: none; }
details.compact-card:not([open]) > .compact-card-body { display: none; }
.compact-card-view {
  margin-top: var(--space-2);
  padding: var(--space-1) 10px;
  font-size: var(--font-size-sm);
  color: var(--accent);
  background: none;
  border: 1px solid color-mix(in srgb, var(--accent) 45%, transparent);
  border-radius: 4px;
  cursor: pointer;
}
.compact-card-view:hover {
  background: color-mix(in srgb, var(--accent) 15%, transparent);
}
.compact-card-view:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 72%, white);
  outline-offset: 2px;
}

/* The signature compaction read: two exact accounting stations connected by
 * one narrowing rail. It says “this context became that context” without
 * borrowing warning/error chrome. Shared by manual cards and Turn events. */
.compaction-token-flow {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 7px;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}
.compaction-token-stage {
  display: inline-grid;
  grid-template-columns: auto;
  gap: 1px;
  min-width: 72px;
  padding: var(--space-1) 7px 5px;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--bg-elevated, var(--bg-secondary)) 82%, transparent);
}
.compaction-token-stage.is-after {
  border-color: color-mix(in srgb, var(--accent) 34%, var(--border));
  background: color-mix(in srgb, var(--accent) 9%, var(--bg-elevated, var(--bg-secondary)));
}
.compaction-token-label {
  color: var(--text-tertiary);
  font-size: 9px;
  font-weight: 650;
  line-height: 1.15;
  letter-spacing: .055em;
}
.compaction-token-value {
  color: var(--text-primary, var(--text));
  font: 650 11px/1.2 var(--font-mono, 'JetBrains Mono', ui-monospace, monospace);
  white-space: nowrap;
}
.compaction-token-arrow {
  position: relative;
  width: 24px;
  height: 12px;
  flex: 0 0 24px;
  overflow: hidden;
  color: transparent;
  font-size: 0;
}
.compaction-token-arrow::before {
  content: '';
  position: absolute;
  top: 5.5px;
  left: 1px;
  right: 5px;
  height: 1px;
  background: linear-gradient(90deg,
    color-mix(in srgb, var(--text-tertiary) 55%, transparent),
    color-mix(in srgb, var(--accent) 80%, transparent));
}
.compaction-token-arrow::after {
  content: '›';
  position: absolute;
  top: -2px;
  right: 1px;
  color: color-mix(in srgb, var(--accent) 82%, var(--text-secondary));
  font: 600 15px/1 var(--font-sans, sans-serif);
}
.compaction-token-saved {
  display: inline-flex;
  align-items: center;
  min-height: 20px;
  padding: 0 7px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: color-mix(in srgb, var(--accent) 75%, var(--text-secondary));
  font: 650 9.5px/1 var(--font-mono, 'JetBrains Mono', ui-monospace, monospace);
  white-space: nowrap;
}
.compaction-token-flow.is-pending .compaction-token-stage.is-after {
  border-style: dashed;
}

@media (max-width: 640px) {
  .compact-card-head > .compaction-token-flow {
    order: 4;
    width: 100%;
    padding-left: 26px;
  }
  .compaction-token-stage { min-width: 64px; }
  .compaction-token-saved { padding-inline: 6px; }
}

/* Context disclosure styles live with the unified conversation bar. */

/* ── B: live-streaming summary overlay (context-bar.js _openLiveSummaryCard).
 *    A small anchored panel that "grows" the /compact summary as it streams,
 *    so the multi-second summary call feels responsive. Dissolves when the
 *    settled boundary card lands. ── */
.ctx-live-summary {
  z-index: 10000;

  box-sizing: border-box;
  overflow: auto;
  width: 340px;
  max-width: min(340px, 90vw);
  padding: 10px var(--space-3);
  background: var(--bg-elevated, var(--bg-secondary));
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.28);
}
.ctx-live-summary-head {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--accent);
  margin-bottom: 6px;
}
/* A small pulsing dot before the label conveys "streaming" without a glyph. */
.ctx-live-summary-head::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  animation: ctxLiveSummaryPulse 1s ease-in-out infinite;
}
@keyframes ctxLiveSummaryPulse { 0%,100%{opacity:1} 50%{opacity:0.3} }
@media (prefers-reduced-motion: reduce) {
  .ctx-live-summary-head::before { animation: none; opacity: 0.7; }
}
.ctx-live-summary-body {
  max-height: 240px;
  overflow-y: auto;
  font-size: var(--font-size-sm);
  line-height: 1.5;
  color: var(--text-secondary, var(--text));
  white-space: pre-wrap;
  word-break: break-word;
}

/* Drawer container */
.compaction-drawer {
  position: fixed;
  inset: 0;
  z-index: 9998;
  pointer-events: none;
  opacity: 0;
  transition: opacity 180ms ease;
}
.compaction-drawer.is-open {
  opacity: 1;
  pointer-events: auto;
}
.compaction-drawer-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.38);
  backdrop-filter: blur(1px);
  cursor: pointer;
}
.compaction-drawer-panel {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(780px, 94vw);
  background: var(--bg-primary, #1a1a1d);
  border-left: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  box-shadow: -20px 0 60px rgba(0, 0, 0, 0.45);
  display: flex;
  flex-direction: column;
  transform: translateX(30px);
  transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.compaction-drawer.is-open .compaction-drawer-panel {
  transform: translateX(0);
}

/* Drawer header */
.compaction-drawer-header {
  flex: 0 0 auto;
  padding: 18px 22px var(--space-3);
  border-bottom: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  background: var(--bg-elevated, rgba(255,255,255,0.02));
}
.compaction-drawer-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}
.compaction-drawer-header h3 {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
}
.compaction-drawer-close {
  background: transparent;
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  color: var(--text-secondary);
  border-radius: 4px;
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 120ms ease;
}
.compaction-drawer-close:hover {
  color: var(--text-primary);
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border-subtle, rgba(255,255,255,0.08)));
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}
.compaction-drawer-subtitle {
  margin: var(--space-2) 0 var(--space-3);
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text-tertiary);
}
.compaction-drawer-subtitle strong { color: var(--text-secondary); font-weight: 600; }
.compaction-drawer-subtitle em { color: color-mix(in srgb, #f59e0b 65%, var(--text-tertiary)); font-style: normal; }

/* Metadata grid */
.cd-meta-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 6px var(--space-4);
  font-size: 11.5px;
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
  margin-bottom: 10px;
}
.cd-meta-row { display: flex; gap: var(--space-2); align-items: baseline; }
.cd-meta-k {
  min-width: 68px;
  color: var(--text-tertiary);
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.cd-meta-v { color: var(--text-secondary); }
.cd-meta-v em { color: color-mix(in srgb, #22c55e 75%, var(--text-secondary)); font-style: normal; }
.cd-meta-trigger-reactive { color: #fb923c; font-weight: 600; }
.cd-meta-trigger-force { color: var(--accent); font-weight: 600; }
.cd-meta-reason { grid-column: 1 / -1; }
.cd-meta-reason .cd-meta-v { color: #fbbf24; font-style: italic; }

/* Tabs */
.compaction-drawer-tabs {
  display: flex;
  gap: 2px;
  margin-top: var(--space-2);
  border-bottom: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  margin-bottom: -13px;
}
.compaction-tab {
  background: transparent;
  border: none;
  padding: var(--space-2) var(--space-3);
  font-size: var(--font-size-sm);
  color: var(--text-tertiary);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: all 120ms ease;
}
.compaction-tab:hover { color: var(--text-secondary); }
.compaction-tab.is-active {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

/* Body */
.compaction-drawer-body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: var(--space-4) 22px;
}
.compaction-drawer-loading {
  padding: var(--space-10) 0;
  text-align: center;
  color: var(--text-tertiary);
  font-size: var(--font-size-sm);
}
.cd-empty { padding: var(--space-8) 0; text-align: center; color: var(--text-tertiary); font-size: 12.5px; line-height: 1.6; }
.cd-empty p { margin: var(--space-1) 0; }
.cd-empty.cd-error { color: #ef4444; }

/* Message list */
.compaction-msg-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.cd-msg {
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  border-radius: 6px;
  background: color-mix(in srgb, var(--bg-elevated, rgba(255,255,255,0.02)) 80%, transparent);
  overflow: hidden;
}
.cd-msg-system { border-left: 3px solid #64748b; }
.cd-msg-user   { border-left: 3px solid #3b82f6; }
.cd-msg-assistant { border-left: 3px solid color-mix(in srgb, var(--accent) 75%, #a855f7); }
.cd-msg-tool   { border-left: 3px solid #10b981; }
.cd-msg-function { border-left: 3px solid #10b981; }

.cd-msg-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px var(--space-3);
  font-size: 10.5px;
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  background: color-mix(in srgb, var(--bg-elevated, rgba(255,255,255,0.02)) 120%, transparent);
  border-bottom: 1px solid var(--border-subtle, rgba(255,255,255,0.06));
}
.cd-msg-idx  { color: var(--text-tertiary); min-width: 32px; }
.cd-msg-role { font-weight: 600; color: var(--text-secondary); }
.cd-msg-meta { margin-left: auto; color: var(--text-tertiary); font-size: 10px; text-transform: none; letter-spacing: 0; }
.cd-msg-body { padding: 10px var(--space-3); }
.cd-empty-body { color: var(--text-tertiary); font-size: var(--font-size-xs); }

.cd-content, .cd-toolcall-args, .cd-summary {
  margin: var(--space-1) 0;
  padding: var(--space-2) 10px;
  background: rgba(0, 0, 0, 0.22);
  border-radius: 3px;
  font-size: 11.5px;
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
  line-height: 1.55;
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 360px;
  overflow: auto;
}
.cd-summary { max-height: none; white-space: pre-wrap; }
.cd-summary-title {
  margin: 18px 0 var(--space-2);
  font-size: var(--font-size-sm);
  color: var(--text-secondary);
}
.cd-receipt {
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 25%, var(--border-subtle, rgba(255,255,255,0.08)));
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent) 4%, var(--bg-elevated, rgba(255,255,255,0.02)));
}
.cd-receipt-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
}
.cd-receipt-head h3 {
  margin: 0;
  font-size: var(--font-size-md);
  color: var(--text-primary);
}
.cd-receipt-status {
  padding: 2px 7px;
  border-radius: 999px;
  font: 10px/1.5 'JetBrains Mono', 'SF Mono', monospace;
  color: var(--text-tertiary);
  background: color-mix(in srgb, var(--text-tertiary) 12%, transparent);
}
.cd-receipt-status-completed { color: #22c55e; background: color-mix(in srgb, #22c55e 12%, transparent); }
.cd-receipt-status-failed,
.cd-receipt-status-aborted { color: #f59e0b; background: color-mix(in srgb, #f59e0b 12%, transparent); }
.cd-receipt-identity {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 7px;
  color: var(--text-tertiary);
  font-size: 10px;
}
.cd-receipt-identity code { color: color-mix(in srgb, var(--accent) 72%, var(--text-secondary)); }
.cd-receipt-outcome {
  margin: var(--space-2) 0 0;
  color: #fbbf24;
  font: 10.5px/1.5 'JetBrains Mono', 'SF Mono', monospace;
}
.cd-receipt-groups {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: var(--space-2);
  margin-top: var(--space-3);
}
.cd-receipt-group {
  padding: 10px;
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.07));
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.12);
}
.cd-receipt-group h4 {
  margin: 0 0 var(--space-2);
  color: var(--text-secondary);
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.cd-receipt-metrics { display: grid; gap: 5px; }
.cd-receipt-metric {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  font-size: 10.5px;
  color: var(--text-tertiary);
}
.cd-receipt-metric strong {
  color: var(--text-secondary);
  font: 500 10.5px/1.4 'JetBrains Mono', 'SF Mono', monospace;
  text-align: right;
}
.cd-receipt-flags { display: flex; flex-wrap: wrap; gap: 5px; margin-top: var(--space-2); }
.cd-receipt-flags span {
  padding: 2px 6px;
  border-radius: 3px;
  color: var(--text-tertiary);
  background: rgba(255, 255, 255, 0.035);
  font-size: 9.5px;
}
.cd-receipt-flags span.is-on { color: #22c55e; background: color-mix(in srgb, #22c55e 10%, transparent); }
.cd-receipt-files { margin-top: 9px; color: var(--text-tertiary); font-size: 10px; }
.cd-receipt-files ul { margin: 5px 0 0; padding-left: 18px; }
.cd-receipt-files li { margin: 3px 0; overflow-wrap: anywhere; }
.cd-receipt-files code { color: var(--text-secondary); }
.cd-content-blocks { display: flex; flex-direction: column; gap: var(--space-1); }

.cd-toolcall {
  margin: 6px 0;
  padding: 0;
}
.cd-toolcall-name {
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
  font-size: var(--font-size-xs);
  color: #22d3ee;
  margin: var(--space-1) 0;
}
.cd-toolcall-id {
  margin-left: var(--space-2);
  color: var(--text-tertiary);
  font-size: 10px;
  opacity: 0.7;
}

.cd-image-block {
  margin: var(--space-1) 0;
  padding: var(--space-2) 10px;
  background: rgba(0, 0, 0, 0.18);
  border: 1px dashed var(--border-subtle, rgba(255,255,255,0.1));
  border-radius: 4px;
}
.cd-image-head {
  font-size: var(--font-size-xs);
  color: var(--text-tertiary);
  margin-bottom: 6px;
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
}
.cd-image-placeholder button {
  background: transparent;
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.12));
  color: var(--accent);
  padding: var(--space-1) 10px;
  font-size: var(--font-size-xs);
  border-radius: 3px;
  cursor: pointer;
  transition: all 120ms ease;
}
.cd-image-placeholder button:hover {
  background: color-mix(in srgb, var(--accent) 15%, transparent);
  color: var(--text-primary);
}
.cd-image-placeholder img {
  max-width: 100%;
  max-height: 360px;
  border-radius: 3px;
  display: block;
}

.cd-thinking {
  margin-top: 6px;
  padding: 6px 10px;
  background: rgba(0, 0, 0, 0.15);
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.06));
  border-radius: 3px;
}
.cd-thinking summary {
  cursor: pointer;
  font-size: 10.5px;
  color: var(--text-tertiary);
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
}
.cd-thinking pre { margin: 6px 0 0; }

/* History tab */
.compaction-history-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}
.cd-history-item {
  padding: 10px var(--space-3);
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  border-radius: 4px;
  background: var(--bg-elevated, rgba(255,255,255,0.02));
  cursor: pointer;
  transition: all 120ms ease;
}
.cd-history-item:hover {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border-subtle, rgba(255,255,255,0.08)));
  background: color-mix(in srgb, var(--accent) 8%, transparent);
}
.cd-history-item.is-active {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
}
.cd-history-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-size: var(--font-size-sm);
}
.cd-history-trigger { font-weight: 600; }
.cd-history-trigger-reactive { color: #fb923c; }
.cd-history-trigger-force { color: var(--accent); }
.cd-history-time { color: var(--text-tertiary); font-size: 10.5px; margin-left: auto; }
.cd-history-result {
  padding: 1px 5px;
  border-radius: 999px;
  color: var(--text-tertiary);
  background: color-mix(in srgb, var(--text-tertiary) 10%, transparent);
  font: 9px/1.5 'JetBrains Mono', 'SF Mono', monospace;
}
.cd-history-result.cd-receipt-status-completed { color: #22c55e; }
.cd-history-result.cd-receipt-status-failed,
.cd-history-result.cd-receipt-status-aborted { color: #f59e0b; }
.cd-history-stats {
  margin-top: var(--space-1);
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
  font-size: 10.5px;
  color: var(--text-tertiary);
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.cd-history-stats em { color: #22c55e; font-style: normal; }
.cd-history-reason {
  margin-top: var(--space-1);
  font-size: var(--font-size-xs);
  color: #fbbf24;
  font-style: italic;
}

/* Footer */
.compaction-drawer-footer {
  flex: 0 0 auto;
  display: flex;
  gap: var(--space-2);
  padding: var(--space-3) 22px;
  border-top: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  background: var(--bg-elevated, rgba(255,255,255,0.02));
}
.compaction-drawer-btn {
  padding: 6px var(--space-3);
  font-size: var(--font-size-sm);
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.1));
  border-radius: 4px;
  cursor: pointer;
  transition: all 120ms ease;
}
.compaction-drawer-btn:hover {
  color: var(--text-primary);
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border-subtle, rgba(255,255,255,0.1)));
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}

/* Small screens — full-width drawer */
@media (max-width: 720px) {
  .compaction-drawer-panel {
    width: 100vw;
    border-left: none;
  }
  .cd-meta-grid { grid-template-columns: 1fr; }
  .cd-receipt-groups { grid-template-columns: 1fr; }
}

/* Context meter/disclosure styles are owned by 25-conversation-bar.css. */

/* ═══════════════════════════════════════════════════════════════════
   Per-turn context rail (.turn-ctx) — built by info-rail.js
   (buildTurnCtxSnapshot / renderTurnCtxNote) and spliced into each USER
   turn by renderMessage(). A frozen-in-time record of the context the turn
   ACTUALLY ran with: model + depth + run-mode + the tools that fired +
   the workspace roots.

   ── Why the WIDTH is a grid track the pane owns ──
   The first design anchored it at `left:calc(100% + 24px)` off the
   centered reading column and hid it under `@media (max-width:1280px)`.
   That predicate asks about the WINDOW, but the space the note lands in is
   `viewport − sidebar − drawer`: the sidebar has four widths (0/280/332/430)
   and the request-inspector drawer eats up to another 780px. Measured across
   all 64 combinations in a real browser, 35 of them clipped the note while
   the media query said "show it", and NONE were hidden while having room —
   i.e. no viewport threshold can be correct, because the predicate is blind
   to two of the three variables. The rail's WIDTH now comes from a real
   grid track that the pane OWNS (see `.chat-inner`), so horizontal overflow
   is impossible by construction rather than by tuning.

   ── Why the HEIGHT is OUT OF FLOW (2026-08-05 redesign) ──
   The rail used to be an in-flow grid item, so a rail taller than its
   bubble STRETCHED the message row: a one-line user turn with many MCP
   servers connected showed ~200px of dead space under the bubble before
   the Agent reply (owner report, conv msftgnt3ezhmtt). The rail is
   metadata marginalia — it has no business sizing the prose row. It is
   now `position:absolute` inside `.message` (already `position:relative`):
   it keeps the track's box (right edge, top aligned) but contributes
   NOTHING to track sizing, so the row height is `max(avatar, content)`
   and the bubble-to-bubble rhythm is the content's own. The rail's box
   owns NO height cap: the sticky follower (info-rail.js) sets an exact
   pixel `max-height` each pass — the free track down to the next round's
   rail / the pane's content bottom — so the rail fills the gutter it
   glides through and SCROLLS only when the facts genuinely outgrow that.

   ── Sticky travel (2026-09-08) ──
   An input turn is often ONE line, so a purely box-bound rail scrolled
   away with its bubble while the round's reply filled screens below it
   (owner report: "when a conversation is scrolling, the turn ctx should
   move along until it reaches the next round"). The follower in
   info-rail.js re-implements sticky-header stacking WITHOUT a DOM
   restructure: on scroll/resize it translates each rail down by
   clamp(stickTop − hostTop, 0, nextRailTop − railHeight − hostTop) —
   pinned to the pane's top inside its round, pushed out exactly when
   the next round's rail arrives, in one continuous motion. The travel
   carries the rail BEYOND its host's border box, which is why rail
   hosts drop content-visibility's paint containment (the
   `.message:has(> .turn-ctx)` carve-out below); the track it glides
   through is empty gutter on every non-input turn. A turn with no rail
   (legacy history) is not a boundary — the previous rail keeps its seat
   until the next railed turn. The height budget is the SAME geometry that
   clamps the travel: `nextTop − visibleTop`, written as an inline
   `max-height` — the rail uses the whole free gutter beside the reply
   (the empty space the 2026-09-23 report pointed at) instead of a fixed
   share of the viewport or its one-line host.

   ── Why there is no hover overlay ──
   `.message` carries `content-visibility:auto`, which applies PAINT
   containment and clips any overflowing descendant. The old design needed
   `.message:has(> .turn-ctx){contain:none}` to escape it — a real perf
   carve-out that existed solely to let a hover panel spill out. Keeping the
   overlay would mean keeping the carve-out, so the overlay is gone: the rail
   renders its content permanently and inline, and expanding the tool list is
   a CLICK that changes in-flow height (no escape needed). The carve-out
   below exists for a DIFFERENT reason — sticky travel — and keeps
   layout+style containment, dropping only paint.

   ── Drawer open → the rail leaves entirely ──
   With the inspector open the pane can be as narrow as 74px (has-rail
   sidebar @1280). Nothing legible fits there, so the rail is not squeezed —
   the container query simply never grants the track, `.turn-ctx` collapses,
   and the turn's context survives as the compact `.tctx-fold` summary line
   under the message header. The information is never silently lost.
   ═══════════════════════════════════════════════════════════════════ */
.turn-ctx{
  /* Out of flow: keeps the third track's BOX (right edge, top-aligned)
   * but never contributes to the row's height — see the block comment. */
  position:absolute;
  top:0;
  right:0;
  width:var(--rail-w);
  /* No CSS height cap: info-rail.js writes the exact free-track budget as
   * an inline max-height every follower pass (see the block comment). A
   * CSS cap here would fight that per-frame geometry. */
  max-height:none;
  box-sizing:border-box;
  min-width:0;
  font-size:var(--font-size-sm);
  font-weight:var(--weight-medium);
  line-height:1.5;
  user-select:text;
  /* The rail IS hit-testable: the height backstop below SCROLLS (needs the
   * pointer), paths expose their full path via hover title, and hovering
   * the rail keeps `.message:hover` true regardless (the rail is a child
   * of `.message`), so the message's hover action-bar is unaffected. What
   * the rail must never do is impersonate a message click — the delegated
   * guard in info-rail.js stopPropagations every click inside it. */
  pointer-events:auto;
}
/* Sticky travel carries the rail BEYOND its host's border box (see the
 * block comment) — content-visibility:auto's paint containment would clip
 * it at the host's edge, and bare .message sets no overflow clip, so paint
 * is the only thing to drop. Rail hosts render eagerly (input turns are
 * few and short); layout+style containment stays. `.cv-off` keeps its
 * !important win. */
.message:has(> .turn-ctx){ content-visibility:visible; contain:layout style; }
/* A rail travels beside later Turns. Their layout containment creates new
 * stacking contexts: lift only populated rail hosts so those transparent
 * sibling boxes cannot intercept the rail's disclosure buttons. */
.message:has(> .turn-ctx:not([hidden])){ z-index:var(--z-turn-context); }
/* While pinned, the rail's height is the follower's inline budget — no
 * class-based cap. The old fixed 60vh left the gutter beside the reply
 * empty while the rail's own facts scrolled internally. */
/* No rail track (narrow pane / drawer open) → the rail folds away. It is a
 * grid item in a zero-width track, so leaving it visible would smear it. */
.chat-inner{ --rail-shown:0; }
.turn-ctx{ display:none; }
@container chatpane (min-width: 1056px){
  .turn-ctx{
    display:flex;
    flex-direction:column;
    gap:var(--space-4);
    padding:var(--space-2) var(--space-1) var(--space-3) var(--space-4);
    border-radius:0;
    background:transparent;
    border:none;
    /* Reference marginalia, not a card: a single hairline rule separates it
     * from the prose column. The boxed card (bg + border + radius) was one
     * more rectangle competing with the message — the rail now whispers. */
    border-left:1px solid var(--border);
    /* HEIGHT DISCIPLINE, two layers. (1) CONTENT caps in info-rail.js
     * decide what renders up-front (≤4 chips / ≤3 paths, the rest behind
     * the "+N" click) — a typical card renders COMPLETE, which the removed
     * 132px `overflow:hidden` guillotine never allowed (it clipped ordinary
     * cards mid-WORKSPACE with no way to reach the facts — the 2026-07-28
     * complaint). (2) The rail's box is bounded by the MESSAGE's own
     * height (the follower's inline free-track budget) and SCROLLS, so
     * nothing
     * is ever unreachable and — unlike the pre-2026-08-05 in-flow rail —
     * the turn's height is never driven by the rail, expanded or not
     * (guarded by the no-inflation assertion in
     * tests/turn_lifecycle/test_turn_ctx_rail_geometry.py). */
    overflow-x:hidden;
    overflow-y:auto;
    overscroll-behavior:contain;
    scrollbar-width:thin;
  }
}
/* Keep the geometry measurable when no track remains; the follower clears
 * this state as soon as a later layout grants space again. */
.turn-ctx.tctx-no-space{ visibility:hidden; pointer-events:none; }
.turn-ctx .tctx-head{ display:flex; align-items:center; flex-wrap:wrap; gap:var(--space-2); }
.turn-ctx .tctx-logo{ display:inline-flex; flex:0 0 auto; align-items:center; }
.turn-ctx .tctx-logo .stg-brand-icon svg{ display:block; width:100%; height:100%; fill:currentColor; }
/* A compact unit: short labels do not push effort to the rail edge; long
 * labels truncate before the badge instead of wrapping the badge alone. */
.turn-ctx .tctx-model-group{
  display:inline-flex;
  align-items:center;
  gap:6px;
  flex:0 1 auto;
  min-width:0;
}
.turn-ctx .tctx-model{
  color:var(--text-secondary);
  flex:0 1 auto;
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.turn-ctx .tctx-depth{
  font-size:var(--font-size-xs);
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:0.04em;
  padding:0 var(--space-1);
  border-radius:5px;
  background:transparent;
  color:var(--text-secondary);
  border:1px solid color-mix(in srgb, currentColor 42%, transparent);
  flex:0 0 auto;
}
/* Mode badge — Endpoint / Autopilot / Swarm / a named flow. */
.turn-ctx .tctx-mode-badge{
  flex:0 0 auto;
  padding:1px 6px;
  border-radius:6px;
  font-size:var(--font-size-xs);
  line-height:1.4;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:0.03em;
  white-space:nowrap;
  background:transparent;
  color:var(--text-secondary);
  border:1px solid color-mix(in srgb, currentColor 42%, transparent);
}

.turn-ctx .tctx-row{ display:flex; flex-direction:column; gap:var(--space-2); }
.turn-ctx .tctx-row + .tctx-row{ padding-top:var(--space-3); border-top:var(--control-edge-inset) solid var(--border-light); }
/* The heading carries only the row label (+ count); the "+N" toggle moved
 * inline into the chips/paths flow, so no space-between spread is needed. */
.turn-ctx .tctx-row-heading{ display:flex; align-items:center; }
.turn-ctx .tctx-row-count{ font-weight:var(--weight-regular); font-variant-numeric:tabular-nums; color:var(--text-secondary); }
.turn-ctx .tctx-row-h{
  font-size:var(--font-size-xs);
  font-weight:700;
  display:inline-flex;
  align-items:baseline;
  gap:var(--space-2);
  letter-spacing:normal;
  color:var(--text-secondary);
}
.turn-ctx .tctx-chips{ display:flex; flex-wrap:wrap; gap:var(--space-1); }
.turn-ctx .tctx-chip{
  font-size:var(--font-size-sm);
  font-weight:var(--weight-medium);
  padding:var(--space-1) var(--space-2);
  border-radius:var(--radius-xs);
  background:var(--bg-secondary);
  color:var(--text-secondary);
  border:var(--control-edge-inset) solid transparent;
  white-space:nowrap;
  max-width:100%;
  overflow:hidden;
  text-overflow:ellipsis;
}
/* "+N more" — a CLICK toggle, deliberately not hover. Expanding grows the
 * rail IN FLOW, which needs no containment escape (see the block comment).
 * It is the only pointer-reactive thing in the rail. It renders INLINE with
 * the chips it reveals (not parked right on the header line), styled to the
 * rail's marginalia voice — quiet tertiary text, no button box — so the
 * header keeps just its label + count. */
.turn-ctx .tctx-more{
  pointer-events:auto;
  display:inline-flex;
  align-items:center;
  gap:var(--space-1);
  min-height:0;
  cursor:pointer;
  font-size:var(--font-size-xs);
  font-weight:var(--weight-medium);
  padding:1px var(--space-1);
  border-radius:var(--radius-xs);
  background:transparent;
  color:var(--text-tertiary);
  border:none;
  flex:0 0 auto;
  font-family:var(--font-ui);
}
.turn-ctx .tctx-more::after{
  content:'';
  width:var(--space-2);
  height:var(--space-2);
  border-inline-end:var(--control-edge-inset) solid currentColor;
  border-block-end:var(--control-edge-inset) solid currentColor;
  transform:rotate(-45deg);
}
.turn-ctx .tctx-more[aria-expanded="true"]{color:var(--accent)}
.turn-ctx .tctx-more[aria-expanded="true"]::after{transform:rotate(45deg)}
.turn-ctx .tctx-more:hover{color:var(--text-primary)}
.turn-ctx .tctx-more:focus-visible{outline:var(--control-edge-inset) solid var(--accent);outline-offset:var(--space-1)}
@media(pointer:coarse){.turn-ctx .tctx-more{min-height:var(--control-h-sm);padding:var(--space-1) var(--space-2)}}
/* The overflow group must NOT be a flex item of its own: as a single item it
 * cannot wrap internally, so its nowrap chips run straight off the rail's
 * right edge (measured +110px past the pane at 1440). `display:contents`
 * dissolves the wrapper so each chip becomes a direct item of `.tctx-chips`
 * and wraps exactly like the always-visible ones. */
.turn-ctx .tctx-overflow{ display:contents; }
.turn-ctx .tctx-overflow[hidden]{ display:none; }
.turn-ctx .tctx-paths{ display:flex; flex-direction:column; gap:var(--space-2); }
.turn-ctx .tctx-path{
  display:flex;
  align-items:flex-start;
  gap:var(--space-1);
  font-size:var(--font-size-sm);
  line-height:1.4;
  color:var(--text-secondary);
  word-break:break-all;
}
.turn-ctx .tctx-path .tctx-lock{ flex:0 0 auto; margin-top:2px; opacity:0.7; }

/* ── Git branch row — a distinctive chip per root branch ──────────────
 * Branch context is READ state (which branch a turn's writes land on), so
 * it gets its own tone: a green-forward accent that reads as VCS without
 * borrowing the search/mcp/ai families. The branch glyph inherits the
 * chip color via currentColor. */
.turn-ctx .tctx-tone-git{
  color:var(--text-secondary);
  background:var(--bg-secondary);
}
.turn-ctx .tctx-tone-git .tctx-branch-icon{ flex:0 0 auto; }
.turn-ctx .tctx-branch-root{
  font-size:9px;
  font-weight:500;
  opacity:.68;
  margin-left:1px;
  padding-left:4px;
  border-left:1px solid color-mix(in srgb, currentColor 32%, transparent);
}

/* ── Checklist (todo) — ONE integrated unit inside the rail ──────────
 * The whole plan lives in `.tctx-todos` (the rail's own box): a count chip
 * (done/total + status glyph) in the chip stream, the in-flight item as an
 * always-on inline line right after it, and the full per-item list behind
 * the same "+N" toggle the other rows use — all travelling with `.tctx-stuck`.
 * Completed items FADE — never struck through. */
.turn-ctx .tctx-tone-todo{
  color:var(--text-secondary);
  background:var(--bg-secondary);
}
.turn-ctx .tctx-todo-count.is-done{
  color:var(--accent);
  border-color:color-mix(in srgb, var(--accent) 40%, transparent);
  background:color-mix(in srgb, var(--accent) 12%, transparent);
}
/* The checklist is ONE unit inside the rail: the count chip, the always-on
 * in-flight line, and the (collapsed) full list all live in `.tctx-todos`,
 * the rail's own box — so the whole plan travels with `.tctx-stuck` and never
 * paints as a detached full-width block. */
.turn-ctx .tctx-todos{
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  gap:2px 5px;
  min-width:0;
}
/* The always-visible in-flight line sits inline AFTER the count chip, on the
 * SAME row. `flex:0 1 auto` (NOT grow): it sizes to its content up to the
 * row's free space and shrinks/truncates with an ellipsis, so it never claims
 * a full line of its own and pushes the next row (the branch) down. A long
 * task stays one line; the full text remains on its hover title. */
.turn-ctx .tctx-todo-current{
  flex:0 1 auto;
  /* min-width:0 lets the line shrink BELOW its content width so flex-shrink
   * actually engages — without it the item refuses to narrow, wraps to its
   * own line, and pushes the branch row down (the "two separate pieces"). */
  min-width:0;
  align-items:center;
  font-size:var(--font-size-sm);
  color:var(--text-primary);
}
.turn-ctx .tctx-todo-current .tctx-todo-text{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
/* The full list — a clean in-flow column under the chip row, INSIDE the
 * rail (not a detached sibling). It renders inline now (no "+N" collapse), so
 * the list itself is the full-width flex item. Items use the rail's own type
 * scale and completion only fades. */
.turn-ctx .tctx-todos .tctx-todo-list{
  flex:0 0 100%;
  display:flex;
  flex-direction:column;
  gap:3px;
  min-width:0;
  padding-top:4px;
}
.turn-ctx .tctx-todo-item{
  display:flex;
  align-items:center;
  gap:4px;
  font-size:var(--font-size-sm);
  line-height:1.45;
  color:var(--text-secondary);
  min-width:0;
}
/* The status glyph centres on the line box (align-items:center above); the
 * old flex-start + margin-top:2px pushed the 10px mark off the wrapped text's
 * optical centre. A fixed square keeps mark + text on one baseline. */
.turn-ctx .tctx-todo-mark{
  flex:0 0 auto;
  width:10px;
  height:10px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  color:var(--text-tertiary);
}
.turn-ctx .tctx-todo-text{ min-width:0; word-break:break-word; }
.turn-ctx .tctx-todo-completed{ color:var(--text-secondary); }
.turn-ctx .tctx-todo-completed .tctx-todo-mark{ color:var(--accent); }
.turn-ctx .tctx-todo-in_progress .tctx-todo-mark{ color:var(--text-primary); }
.turn-ctx .tctx-todo-in_progress .tctx-todo-text{ color:var(--text-primary); }
.turn-ctx .tctx-todo-blocked .tctx-todo-mark{ color:var(--error-text); }
.turn-ctx .tctx-todo-blocked .tctx-todo-text{ color:var(--error-text); }

/* ── Fold: the rail's content as ONE line under the message header ──
 * Shown exactly when the rail track is absent (narrow pane, or the
 * inspector drawer is open). Guarantees the turn's context is never lost,
 * only compacted.
 * DOM HOME: inside `.message-content`, between header and body — in-flow,
 * the only place this rule's `margin-bottom` means anything. It used to
 * ship as a direct `.message` grid child, where it auto-placed into the
 * ZERO-WIDTH rail track and painted nothing (display:flex, width:0)
 * whenever the rail was hidden — the exact state it exists for. Guarded by
 * the width-aware fold assertion in tests/turn_lifecycle/test_turn_ctx_rail_geometry.py. */
.tctx-fold{
  display:flex;
  align-items:center;
  gap:var(--space-2);
  margin-bottom:var(--space-2);
  font-size:var(--font-size-sm);
  font-weight:var(--weight-medium);
  color:var(--text-secondary);
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.tctx-fold .tctx-fold-dot{ width:5px; height:5px; border-radius:50%; background:var(--accent); flex:0 0 auto; opacity:.7; }
@container chatpane (min-width: 1056px){
  .tctx-fold{ display:none; }
}

/* ═══════════════════════════════════════════════════════════════════
   Background-activity chip (background-activity.js)

   Sits in #convStatusStrip between the context gauge and the turn-nav.
   Hidden (display:none, JS-driven) whenever nothing is executing in the
   background; visible while any swarm sub-agent or detached run_command
   is still working after the foreground turn settled. No ambient
   animation: the single pulse on the dot runs only while the chip is
   visible, i.e. only while real work exists.
   ═══════════════════════════════════════════════════════════════════ */

.bg-activity-chip{
  flex:0 1 auto;
  display:inline-flex;
  align-items:center;
  gap:7px;
  min-width:0;
  padding:5px 11px;
  border-radius:999px;
  user-select:none;
  cursor:pointer;
  font-size:var(--font-size-sm);
  line-height:1;
  color:var(--text-secondary);
  background:color-mix(in srgb, var(--accent) 10%, transparent);
  border:1px solid color-mix(in srgb, var(--accent) 26%, transparent);
  opacity:0;
  animation:ctx-fade-in .35s ease-out forwards;
}
.bg-activity-chip:hover{
  background:color-mix(in srgb, var(--accent) 16%, transparent);
}
.bg-act-dot{
  flex:0 0 auto;
  width:7px;
  height:7px;
  border-radius:50%;
  background:var(--accent);
  animation:bg-act-pulse 1.6s ease-in-out infinite;
}
@keyframes bg-act-pulse{
  0%,100%{ opacity:.45; }
  50%    { opacity:1;   }
}
@media (prefers-reduced-motion: reduce){
  .bg-act-dot{ animation:none; }
}
.bg-act-label{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

/* Popover — anchored fixed above the chip by JS, opens upward. */
.bg-act-popover{
  z-index:1000;
  width:340px;
  max-width:calc(100vw - 24px);
  max-height:min(50vh, 420px);
  overflow-y:auto;
  border-radius:12px;
  background:var(--bg-primary, #fff);
  border:1px solid var(--border-color, rgba(0,0,0,.12));
  box-shadow:0 8px 30px rgba(0,0,0,.18);
  padding:10px var(--space-3) var(--space-3);
  font-size:var(--font-size-sm);
  color:var(--text-primary);
}
.bg-act-pop-head{
  font-weight:600;
  font-size:12.5px;
  margin-bottom:6px;
}
.bg-act-pop-section{
  margin:10px 0 var(--space-1);
  font-size:var(--font-size-xs);
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:.04em;
  color:var(--text-tertiary);
}
.bg-act-pop-section:first-of-type{ margin-top:2px; }
.bg-act-swarm{
  border-radius:8px;
  padding:6px var(--space-2);
  margin-bottom:var(--space-1);
  background:color-mix(in srgb, var(--accent) 6%, transparent);
}
.bg-act-swarm.is-clickable{ cursor:pointer; }
.bg-act-swarm.is-clickable:hover{
  background:color-mix(in srgb, var(--accent) 12%, transparent);
}
.bg-act-swarm-head{
  display:flex;
  align-items:baseline;
  gap:var(--space-2);
  min-width:0;
}
.bg-act-swarm-conv{
  font-weight:600;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.bg-act-swarm-summary{
  color:var(--text-tertiary);
  white-space:nowrap;
}
.bg-act-elapsed{
  margin-left:auto;
  flex:0 0 auto;
  color:var(--text-tertiary);
  font-variant-numeric:tabular-nums;
  white-space:nowrap;
}
.bg-act-agent{
  display:flex;
  flex-wrap:wrap;
  align-items:baseline;
  gap:7px;
  min-width:0;
  margin-top:var(--space-1);
  padding-left:2px;
}
.bg-act-agent-role{
  flex:0 0 auto;
  padding:1px 6px;
  border-radius:6px;
  font-size:10.5px;
  font-weight:600;
  background:color-mix(in srgb, var(--accent) 14%, transparent);
  color:var(--accent);
}
.bg-act-agent-id{
  flex:1 0 100%;
  min-width:0;
  max-width:100%;
  min-height:32px;
  padding:var(--space-1) 6px;
  border:1px solid var(--border-color);
  border-radius:6px;
  background:var(--bg-primary);
  color:var(--text-primary);
  font-family:var(--font-mono, ui-monospace, monospace);
  font-size:var(--font-size-xs);
  text-align:left;
  overflow-wrap:anywhere;
  user-select:text;
  cursor:copy;
}
.bg-act-agent-id:focus-visible{
  outline:2px solid var(--accent);
  outline-offset:2px;
}
.bg-act-agent-objective{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  color:var(--text-secondary);
}
.bg-act-agent-status{
  margin-left:auto;
  flex:0 0 auto;
  color:var(--text-tertiary);
  white-space:nowrap;
}
.bg-act-agent[data-status="running"] .bg-act-agent-status{ color:var(--accent); }
.bg-act-agent[data-status="failed"] .bg-act-agent-status,
.bg-act-agent[data-status="error"]  .bg-act-agent-status{ color:#c44747; }
.bg-act-cmd{
  display:flex;
  align-items:baseline;
  gap:var(--space-2);
  min-width:0;
  padding:5px var(--space-2);
  border-radius:8px;
  margin-bottom:var(--space-1);
  background:color-mix(in srgb, var(--accent) 6%, transparent);
}
.bg-act-cmd-text{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  font-family:var(--font-mono, ui-monospace, monospace);
  font-size:11.5px;
}
/* ──────────────────────────────────────────────────────────────────────
   Artifacts subsystem — chips in chat + right-side panel + library
   See static/js/artifacts.js.

   Design: clean, monochrome with a single accent.  No emoji glyphs in
   chrome — all icons are inline SVGs rendered with currentColor.
   ──────────────────────────────────────────────────────────────────── */

/* ── Chip strip below the file-changes bar ──────────────────────── */
.artifact-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: 10px;
}

.artifact-chip {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: var(--space-2) var(--space-3) var(--space-2) 10px;
  border: 1px solid var(--border, #2a2a35);
  border-radius: 10px;
  background: var(--bg-secondary, #111115);
  color: var(--text-primary, #e8e8ed);
  font-family: inherit;
  font-size: var(--font-size-sm);
  text-align: left;
  cursor: pointer;
  transition: border-color .15s ease, background .15s ease, transform .05s ease;
  user-select: none;
  max-width: 360px;
  position: relative;
}
.artifact-chip:hover {
  border-color: var(--accent, #6e56cf);
  background: var(--bg-hover, #22222b);
}
.artifact-chip:active {
  transform: translateY(1px);
}

.artifact-chip-icon {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent, #6e56cf) 14%, transparent);
  color: var(--accent, #6e56cf);
}
.artifact-chip-icon svg {
  width: 18px;
  height: 18px;
}

.artifact-chip-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 1px;
}
.artifact-chip-title {
  font-weight: 600;
  font-size: 12.5px;
  color: var(--text-primary, #e8e8ed);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.artifact-chip-meta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 10.5px;
  color: var(--text-secondary, #9898a8);
}
.artifact-chip-fmt {
  display: inline-block;
  padding: 1px 6px;
  border-radius: 3px;
  font-weight: 700;
  font-size: 9.5px;
  letter-spacing: .04em;
  background: var(--bg-tertiary, #1a1a21);
  color: var(--text-secondary, #9898a8);
  text-transform: uppercase;
}
.artifact-chip-size {
  font-variant-numeric: tabular-nums;
}

/* ── Panel container ────────────────────────────────────────────── */
.artifact-panel {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: clamp(360px, 46vw, 760px);
  background: var(--bg-primary, #0a0a0c);
  border-left: 1px solid var(--border, #2a2a35);
  box-shadow: -16px 0 48px rgba(0, 0, 0, .42);
  display: flex;
  flex-direction: column;
  z-index: 9000;
  transform: translateX(0);
  transition: transform .24s cubic-bezier(.32, .72, 0, 1);
  font-family: inherit;
}
.artifact-panel-hidden {
  transform: translateX(100%);
  pointer-events: none;
}

body.artifact-panel-open {
  /* Reserve no extra space — panel overlays.  Future split mode
     can reclaim the layout shift here. */
}

/* Drag-to-resize handle on the panel's left edge */
.artifact-panel-resize {
  position: absolute;
  top: 0; bottom: 0;
  left: 0;
  width: 4px;
  cursor: ew-resize;
  background: transparent;
  z-index: 1;
  transition: background .15s ease;
}
.artifact-panel-resize:hover,
.artifact-panel-resize:active {
  background: var(--accent, #6e56cf);
}

/* ── Header ─────────────────────────────────────────────────────── */
.artifact-panel-header {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: 14px var(--space-4);
  border-bottom: 1px solid var(--border, #2a2a35);
  background: var(--bg-secondary, #111115);
  flex: 0 0 auto;
}
.artifact-panel-titleblock {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}
.artifact-panel-titleinfo {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
  flex: 1;
}
.artifact-panel-titlerow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
}
.artifact-panel-title {
  font-weight: 600;
  font-size: var(--font-size-lg);
  color: var(--text-primary, #e8e8ed);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.artifact-panel-subtitle {
  font-size: var(--font-size-xs);
  color: var(--text-tertiary, #6a6a7a);
  font-variant-numeric: tabular-nums;
  letter-spacing: .01em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Format pill — appears in title row + library rows */
.artifact-format-pill {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .04em;
  background: var(--bg-tertiary, #1a1a21);
  color: var(--text-secondary, #9898a8);
  text-transform: uppercase;
  flex: 0 0 auto;
}
.artifact-format-pill:empty {
  display: none;
}
.artifact-format-pill[data-format="markdown"],
.artifact-format-markdown {
  color: #c5b3ff;
  background: color-mix(in srgb, #6e56cf 22%, transparent);
}
.artifact-format-pill[data-format="html"],
.artifact-format-html {
  color: #ffd194;
  background: color-mix(in srgb, #f59e0b 22%, transparent);
}
.artifact-format-pill[data-format="svg"],
.artifact-format-svg {
  color: #a3e7c8;
  background: color-mix(in srgb, #10b981 24%, transparent);
}

.artifact-version-select {
  appearance: none;
  -webkit-appearance: none;
  border: 1px solid var(--border, #2a2a35);
  background: var(--bg-tertiary, #1a1a21);
  color: var(--text-primary, #e8e8ed);
  font-family: inherit;
  font-size: var(--font-size-xs);
  padding: var(--space-1) 22px var(--space-1) 10px;
  border-radius: 6px;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%239898a8' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><polyline points='6 9 12 15 18 9'/></svg>");
  background-repeat: no-repeat;
  background-position: right 6px center;
  background-size: 12px 12px;
  cursor: pointer;
  flex: 0 0 auto;
}
.artifact-version-select:hover {
  border-color: var(--accent, #6e56cf);
}
.artifact-version-select:focus {
  outline: none;
  border-color: var(--accent, #6e56cf);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent, #6e56cf) 25%, transparent);
}

/* ── Action toolbar in the header ───────────────────────────────── */
.artifact-panel-actions {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  flex: 0 0 auto;
}

.artifact-iconbtn {
  width: 30px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 7px;
  color: var(--text-secondary, #9898a8);
  font-family: inherit;
  font-size: var(--font-size-xs);
  font-weight: 700;
  letter-spacing: .04em;
  padding: 0;
  cursor: pointer;
  transition: background .15s ease, color .15s ease, border-color .15s ease;
}
.artifact-iconbtn:hover {
  background: var(--bg-hover, #22222b);
  color: var(--text-primary, #e8e8ed);
}
.artifact-iconbtn:focus-visible {
  outline: none;
  border-color: var(--accent, #6e56cf);
  color: var(--text-primary, #e8e8ed);
}
.artifact-iconbtn:active {
  background: var(--bg-active, #2a2a35);
}
.artifact-iconbtn-active {
  color: var(--accent, #7c66d4);
  background: color-mix(in srgb, var(--accent, #6e56cf) 14%, transparent);
}
.artifact-iconbtn-text {
  font-size: 10.5px;
  letter-spacing: .06em;
  text-transform: uppercase;
  font-weight: 700;
}
.artifact-iconbtn-close:hover {
  color: #f87171;
}
.artifact-iconbtn-back {
  flex: 0 0 auto;
}
.artifact-iconbtn-back:hover {
  color: var(--accent, #7c66d4);
}

.artifact-actions-sep {
  width: 1px;
  height: 18px;
  background: var(--border, #2a2a35);
  margin: 0 var(--space-1);
}

/* ── Banner (e.g. "scripts blocked") ───────────────────────────── */
.artifact-panel-banner {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px var(--space-4);
  background: color-mix(in srgb, #f59e0b 16%, transparent);
  border-bottom: 1px solid color-mix(in srgb, #f59e0b 32%, transparent);
  font-size: var(--font-size-sm);
  color: var(--text-primary, #e8e8ed);
  flex: 0 0 auto;
}
.artifact-banner-icon {
  width: 18px;
  height: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #f59e0b;
  flex: 0 0 auto;
  margin-top: 1px;
}
.artifact-banner-text {
  flex: 1;
  line-height: 1.55;
  color: var(--text-secondary, #9898a8);
}
.artifact-banner-text strong {
  color: var(--text-primary, #e8e8ed);
}
.artifact-banner-action {
  border: 1px solid color-mix(in srgb, #f59e0b 60%, transparent);
  background: transparent;
  color: var(--text-primary, #e8e8ed);
  font-family: inherit;
  font-size: 11.5px;
  font-weight: 600;
  padding: 6px var(--space-3);
  border-radius: 6px;
  cursor: pointer;
  transition: background .15s ease;
  flex: 0 0 auto;
}
.artifact-banner-action:hover {
  background: color-mix(in srgb, #f59e0b 18%, transparent);
}

/* ── Body ───────────────────────────────────────────────────────── */
.artifact-panel-body {
  flex: 1;
  overflow: auto;
  background: var(--bg-primary, #0a0a0c);
  position: relative;
}

.artifact-md {
  padding: var(--space-6) 30px 60px;
  color: var(--text-primary, #e8e8ed);
  line-height: 1.65;
  font-size: var(--font-size-lg);
  max-width: 760px;
  margin: 0 auto;
}
.artifact-md > :first-child { margin-top: 0; }
.artifact-md h1 {
  font-size: 24px;
  margin: 0 0 var(--space-4);
  padding-bottom: var(--space-2);
  border-bottom: 1px solid var(--border, #2a2a35);
}
.artifact-md h2 { font-size: 19px; margin: 28px 0 var(--space-3); }
.artifact-md h3 { font-size: var(--font-size-xl); margin: 22px 0 10px; }
.artifact-md p,
.artifact-md ul,
.artifact-md ol { margin: var(--space-3) 0; }
.artifact-md pre {
  background: var(--bg-secondary, #111115);
  padding: var(--space-3) 14px;
  border-radius: 8px;
  border: 1px solid var(--border, #2a2a35);
  overflow: auto;
  font-size: 12.5px;
}
.artifact-md code:not(pre code) {
  background: var(--bg-tertiary, #1a1a21);
  padding: 1px 5px;
  border-radius: 4px;
  font-size: var(--font-size-sm);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}
.artifact-md table {
  border-collapse: collapse;
  margin: 14px 0;
  font-size: var(--font-size-md);
}
.artifact-md th,
.artifact-md td {
  border: 1px solid var(--border, #2a2a35);
  padding: 7px var(--space-3);
}
.artifact-md th { background: var(--bg-secondary, #111115); }
.artifact-md blockquote {
  border-left: 3px solid var(--accent, #6e56cf);
  margin: var(--space-3) 0;
  padding: var(--space-1) 14px;
  color: var(--text-secondary, #9898a8);
  background: color-mix(in srgb, var(--accent, #6e56cf) 6%, transparent);
  border-radius: 0 6px 6px 0;
}
.artifact-md a {
  color: var(--accent-hover, #7c66d4);
  text-decoration: none;
  border-bottom: 1px solid color-mix(in srgb, var(--accent, #6e56cf) 35%, transparent);
}
.artifact-md a:hover {
  border-bottom-color: var(--accent, #6e56cf);
}
.artifact-md img {
  max-width: 100%;
  height: auto;
  border-radius: 6px;
}

.artifact-iframe {
  width: 100%;
  height: 100%;
  border: 0;
  background: #fff;
  display: block;
}

.artifact-svg {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 28px;
  height: 100%;
  background:
    repeating-conic-gradient(var(--bg-secondary, #111115) 0 25%, transparent 0 50%) 0 0/24px 24px;
}
.artifact-svg img {
  max-width: 100%;
  max-height: 100%;
  filter: drop-shadow(0 4px 24px rgba(0, 0, 0, .4));
  background: #fff;
  border-radius: 4px;
}

.artifact-source-view {
  margin: 0;
  padding: 18px 22px;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-primary, #e8e8ed);
  background: transparent;
  border: 0;
  tab-size: 4;
}

/* ── Loading / error / empty states ────────────────────────────── */
.artifact-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 60px var(--space-6);
  color: var(--text-tertiary, #6a6a7a);
  font-size: var(--font-size-md);
}
.artifact-loading svg {
  width: 18px;
  height: 18px;
  opacity: .6;
  animation: artifactPulse 1.6s ease-in-out infinite;
}
@keyframes artifactPulse {
  0%, 100% { opacity: .35; }
  50%      { opacity: 1; }
}

.artifact-error {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  margin: var(--space-6);
  padding: var(--space-4) 18px;
  border: 1px solid color-mix(in srgb, #ef4444 40%, var(--border, #2a2a35));
  background: color-mix(in srgb, #ef4444 8%, transparent);
  border-radius: 10px;
  color: var(--text-primary, #e8e8ed);
  font-size: var(--font-size-md);
  line-height: 1.55;
}
.artifact-error svg {
  color: #f87171;
  flex: 0 0 auto;
  margin-top: 2px;
}
.artifact-error-detail {
  margin-top: var(--space-1);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11.5px;
  color: var(--text-secondary, #9898a8);
  word-break: break-all;
}

.artifact-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 80px var(--space-8) 60px;
  color: var(--text-secondary, #9898a8);
}
.artifact-empty-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-secondary, #111115);
  border: 1px solid var(--border, #2a2a35);
  margin-bottom: var(--space-4);
  color: var(--text-tertiary, #6a6a7a);
}
.artifact-empty-icon svg {
  width: 24px;
  height: 24px;
}
.artifact-empty-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary, #e8e8ed);
  margin-bottom: 6px;
}
.artifact-empty-text {
  font-size: 12.5px;
  line-height: 1.55;
  max-width: 320px;
  color: var(--text-secondary, #9898a8);
}

/* ── Library mode ──────────────────────────────────────────────── */
.artifact-lib {
  padding: 14px 14px var(--space-6);
}
.artifact-lib-search {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  margin-bottom: var(--space-3);
  background: var(--bg-secondary, #111115);
  border: 1px solid var(--border, #2a2a35);
  border-radius: 8px;
}
.artifact-lib-search-icon {
  display: inline-flex;
  align-items: center;
  color: var(--text-tertiary, #6a6a7a);
  flex: 0 0 auto;
}
.artifact-lib-search input {
  flex: 1;
  border: 0;
  background: transparent;
  color: var(--text-primary, #e8e8ed);
  font-family: inherit;
  font-size: var(--font-size-md);
  padding: var(--space-1) 0;
  outline: none;
  min-width: 0;
}
.artifact-lib-search input::placeholder {
  color: var(--text-tertiary, #6a6a7a);
}

.artifact-lib-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.artifact-lib-noresult {
  padding: 14px var(--space-2);
  text-align: center;
  font-size: 12.5px;
  color: var(--text-tertiary, #888);
}

.artifact-lib-row {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: 10px var(--space-3);
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  cursor: pointer;
  width: 100%;
  text-align: left;
  font-family: inherit;
  color: var(--text-primary, #e8e8ed);
  transition: background .12s ease, border-color .12s ease;
}
.artifact-lib-row:hover {
  background: var(--bg-secondary, #111115);
  border-color: var(--border-light, #33333f);
}
.artifact-lib-row:focus-visible {
  outline: none;
  border-color: var(--accent, #6e56cf);
  background: var(--bg-secondary, #111115);
}

.artifact-lib-icon {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent, #6e56cf) 12%, transparent);
  color: var(--accent, #7c66d4);
}
.artifact-lib-icon svg { width: 18px; height: 18px; }

.artifact-lib-main {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  flex: 1;
}
.artifact-lib-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary, #e8e8ed);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.artifact-lib-meta {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--font-size-xs);
  color: var(--text-tertiary, #6a6a7a);
}
.artifact-lib-dim { color: var(--text-tertiary, #6a6a7a); }

.artifact-lib-pin {
  width: 30px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  flex: 0 0 auto;
  color: var(--text-tertiary, #6a6a7a);
  transition: color .15s ease, background .15s ease;
}
.artifact-lib-pin:hover {
  color: var(--text-primary, #e8e8ed);
  background: var(--bg-hover, #22222b);
}
.artifact-lib-pin.is-pinned {
  color: var(--accent, #7c66d4);
}

/* ── Mobile fallback: full-screen ─────────────────────────────── */
@media (max-width: 720px) {
  .artifact-panel {
    width: 100vw;
    max-width: 100vw;
    box-shadow: none;
  }
  .artifact-md {
    padding: 18px 18px 60px;
  }
  .artifact-panel-actions .artifact-iconbtn-text {
    /* "PDF" still helpful on mobile, leave visible */
  }
}

/* ── Light theme overrides ──────────────────────────────────────── */
[data-theme="light"] .artifact-svg {
  background: repeating-conic-gradient(#f0f0f4 0 25%, transparent 0 50%) 0 0/24px 24px;
}
[data-theme="light"] .artifact-iframe {
  background: #fff;
}

/* ── Typed error envelope (kind/severity-aware error block) ───────────
 * Backend emits errors as a structured dict; renderErrorEnvelope() in
 * core.js produces the markup below. Falls back gracefully for legacy
 * string errors via normalizeErrorEnvelope(). */
.error-block-title{display:flex;align-items:center;gap:var(--space-2);font-weight:600;font-size:var(--font-size-sm);text-transform:uppercase;letter-spacing:0.4px;margin-bottom:6px;opacity:0.85}
.message .error-block{margin-top:10px;text-align:left;user-select:text}
.error-block-kind{padding:1px var(--space-2);border-radius:10px;background:rgba(220,38,38,0.12);color:inherit;font-size:var(--font-size-xs);letter-spacing:0.3px}
.error-block-ctx{font-size:10px;opacity:0.55;font-family:'JetBrains Mono',monospace}
.error-block-message{font-size:var(--font-size-md);line-height:1.55;white-space:pre-wrap}
.error-block-hint{margin-top:var(--space-2);padding-top:var(--space-2);border-top:1px dashed rgba(220,38,38,0.18);font-size:var(--font-size-sm);line-height:1.5;opacity:0.85;white-space:pre-wrap}
.error-block-detail{margin-top:var(--space-2);font-size:var(--font-size-xs);font-family:'JetBrains Mono',monospace;opacity:0.6;word-break:break-all;white-space:pre-wrap}
.error-block--warning{border-color:rgba(245,158,11,0.4);background:rgba(245,158,11,0.06);color:#f59e0b}
.error-block--warning .error-block-kind{background:rgba(245,158,11,0.15)}
.error-block--warning .error-block-hint{border-top-color:rgba(245,158,11,0.18)}

/* ═══════════════════════════════════════════════════════════════════
   ★ PERF: conversation-list windowing sentinel (see conversation_list.js
   _renderConvWindow). Zero-height tripwire; the prefetch margin lives in
   the IntersectionObserver rootMargin, so it needs no visible size. ── */
.conv-window-sentinel{height:1px;margin:0;padding:0;pointer-events:none}

/* ═══════════════════════════════════════════════════════════════════
   ★ A11Y: tofu-theme colour-contrast fixes (WCAG AA, 4.5:1 on the beige
   ~#F5F3ED/#EDEBE2/#F0EAE0 surfaces). Lighthouse flagged these labels at
   1.4–4.1:1. Scoped to the tofu theme only — the dark themes use light
   text on dark surfaces where these same colours already pass. Placed at
   EOF so source order beats the original rules without needing !important
   except where an opacity multiplier was dragging the effective ratio. ── */

/* Token bump: many sidebar greys resolve through --text-tertiary. */
[data-theme="tofu"]{--text-tertiary:#6B6452}

/* Project rail: count badges */
[data-theme="tofu"] .folder-tab-count{background:#CFC7B2;color:#574F3D}
[data-theme="tofu"] .folder-tab.active .folder-tab-count{background:#8A6A45;color:#fff}

/* Streaming message meta (timestamp + elapsed timer) — opacity neutralised */
[data-theme="tofu"] .message-time,
[data-theme="tofu"] .conv-date-text,
[data-theme="tofu"] .conv-date-time,
[data-theme="tofu"] .conv-date-sep{color:#6B6452;opacity:1}
[data-theme="tofu"] .stream-elapsed,
[data-theme="tofu"] .stream-elapsed-timer{color:#6B6452}

/* Project-tool panel: label. The info/err badge color now comes from the
 * shared --chip-{tone}-* tokens (11-tofu-theme-foundation.css) so tofu badges
 * are one consistent kinako/azuki cast; this file previously overrode them
 * with a one-off khaki/clay pair. */
[data-theme="tofu"] .ptool-panel-label{color:#7A5E12}

/* File-changes bar: summary, path dir/fname, action verb */
[data-theme="tofu"] .fc-summary-text{color:#1E7350}
[data-theme="tofu"] .fc-dir{color:#7C7560}
[data-theme="tofu"] .fc-fname{color:#574F3D}
[data-theme="tofu"] .fc-action{color:#6B6452}

/* Turn-nav label + context-health capacity readout */
[data-theme="tofu"] .turn-nav-label{color:#4A4436}
[data-theme="tofu"] .ctx-bar-cap{color:#6B5413}
/* ── WCAG AA contrast fixes (tofu light theme, ≥4.5:1) ──
   Lighthouse color-contrast audit flagged these light-on-light labels.
   Each value is darkened against the tofu surface it sits on; where a base
   rule dims the element via opacity (which blends the rendered color toward
   the background and tanks the ratio) we also raise the opacity. */
[data-theme="tofu"] .conv-date-count{color:#6B6452;opacity:0.9}
[data-theme="tofu"] .fc-undo-btn{color:#7A5226}
[data-theme="tofu"] .fc-undo-all-btn{color:#9E3A2C}
[data-theme="tofu"] .msg-branch-btn:hover{color:#6E5A3E}
[data-theme="tofu"] .bilingual-type{color:#6E5A3E}
[data-theme="tofu"] .bilingual-model{color:#7A5226}
[data-theme="tofu"] .ptool-turn-label{color:#8A5A00}
[data-theme="tofu"] .ctx-health-bar > .ctx-bar-cap{opacity:0.9}

/* ═══════════════════════════════════════════════════════════════════
   ★ Dark/default theme — sidebar + topbar depth polish (2026-06)
   Scoped to NON-light, NON-tofu so the hand-built light & tofu themes
   are untouched. Goal: replace flat solid fills + hairline borders with
   subtle layering (gradient panels, edge highlights, a real separating
   shadow and an accent bar on the active conversation).
   Primary chat controls use the shared shell owner.
   ═══════════════════════════════════════════════════════════════════ */
:root{--sb-edge:rgba(255,255,255,0.04);--tb-glass:rgba(17,17,21,0.72)}

/* ── Sidebar: soft vertical gradient + inner edge highlight reads as a raised panel ── */
html:not([data-theme="light"]):not([data-theme="tofu"]) .sidebar{
  background:linear-gradient(180deg,#121217 0%,#0e0e12 100%);
  border-right:1px solid #1f1f27;
  box-shadow:inset -1px 0 0 var(--sb-edge);
}
html:not([data-theme="light"]):not([data-theme="tofu"]) .sidebar-header{
  border-bottom:1px solid #1f1f27;
  box-shadow:0 1px 0 var(--sb-edge);
}

/* ── Header action buttons: a touch more contrast on hover with a hairline edge ── */
html:not([data-theme="light"]):not([data-theme="tofu"]) .action-btn:hover{
  background:var(--bg-hover);
  box-shadow:inset 0 0 0 1px var(--border-light);
}

/* ── Conversation rows: lift the active row with a left accent bar (Linear/ChatGPT move) ── */
html:not([data-theme="light"]):not([data-theme="tofu"]) .conv-item{border-radius:var(--radius-sm)}
html:not([data-theme="light"]):not([data-theme="tofu"]) .conv-item::before{
  content:'';position:absolute;left:0;top:50%;transform:translateY(-50%);
  width:3px;height:0;border-radius:0 3px 3px 0;
  background:linear-gradient(180deg,#8b6cf6,#6e56cf);
  transition:height .18s cubic-bezier(.34,1.56,.64,1);pointer-events:none;
}
html:not([data-theme="light"]):not([data-theme="tofu"]) .conv-item.active::before{height:58%}
html:not([data-theme="light"]):not([data-theme="tofu"]) .conv-item.active{
  background:linear-gradient(90deg,var(--accent-subtle) 0%,var(--bg-active) 60%);
}

/* ── Topbar: frosted glass + gradient + a real separating shadow instead of a flat hairline ── */
html:not([data-theme="light"]):not([data-theme="tofu"]) .topbar{
  background:linear-gradient(180deg,rgba(20,20,26,0.85),var(--tb-glass));
  -webkit-backdrop-filter:blur(12px) saturate(1.2);
  backdrop-filter:blur(12px) saturate(1.2);
  border-bottom:1px solid #1f1f27;
  box-shadow:0 1px 0 rgba(255,255,255,0.03),0 4px 16px -8px rgba(0,0,0,0.6);
}

/* ═══════════════════════════════════════════════════════════════════
   Project Brain — signal-driven read model (2026-09 redesign).
   Board / Feed / Charter / Status are READ-ONLY projections of
   the storage event authority; the only owned commands are Watch maintenance
   and versioned Checker registration/execution. The Integration tab keeps its
   own operational density in static/project-integration.css.
   Every class name below is load-bearing for project-brain.js — do not
   rename without updating the JS.
   ═══════════════════════════════════════════════════════════════════ */

/* Local design tokens (scoped) so the whole surface stays internally
   consistent and easy to retune. */
.project-brain-overlay{
  --pb-radius:12px; --pb-radius-sm:9px; --pb-radius-chip:999px;
  --pb-card-bg:color-mix(in srgb,var(--bg-tertiary) 82%,var(--bg-secondary));
  --pb-card-hover:color-mix(in srgb,var(--bg-hover) 70%,var(--bg-tertiary));
  --pb-green:#22c55e; --pb-red:#ef4444; --pb-amber:#eab308;
}
/* Light surfaces: the dark-theme status hues above wash out on paper. Deepen
   the same hues so badges, lane rails and tab colour keep ≥ ~4.4:1 on the
   light card ground. */
[data-theme="light"] .project-brain-overlay,
[data-theme="tofu"] .project-brain-overlay{
  --pb-green:#15803d; --pb-red:#dc2626; --pb-amber:#854d0e;
}

/* Overlay + sliding panel. */
.project-brain-overlay{position:fixed;inset:0;height:100vh;height:var(--vh100,100vh);background:rgba(6,6,10,0.58);backdrop-filter:blur(4px);z-index:9998;display:flex;align-items:stretch;justify-content:flex-end;animation:fadeIn 0.16s ease}
.project-brain-overlay[hidden]{display:none}
/* WebView quirk: a position:fixed element sizes to the initial containing
   block, which this Android WebView measures as height:0 (same root cause as
   the blank-screen/modal fixes) — so inset:0 alone collapsed the overlay and
   its height:100% panel to nothing. Pin an explicit height from the known-good
   --vh100 px var (set by _installViewportHeightGuard), plain 100vh fallback. */
.project-brain-panel{position:relative;background:var(--bg-secondary);border-left:1px solid var(--border-light);width:min(960px,94vw);height:100%;min-height:var(--vh100,100vh);display:flex;flex-direction:column;box-shadow:-24px 0 64px rgba(0,0,0,0.5);animation:pbSlideIn 0.24s cubic-bezier(0.16,1,0.3,1)}
/* Accent hairline running down the panel's leading edge — ties it to the brand. */
.project-brain-panel::before{content:'';position:absolute;top:0;left:0;width:3px;height:100%;background:linear-gradient(180deg,var(--accent),color-mix(in srgb,var(--accent) 30%,transparent));opacity:0.9}
@keyframes pbSlideIn{from{transform:translateX(28px);opacity:0}to{transform:translateX(0);opacity:1}}

/* Head. */
.project-brain-head{display:flex;align-items:center;justify-content:space-between;padding:var(--space-4) 22px;border-bottom:1px solid var(--border);background:linear-gradient(180deg,color-mix(in srgb,var(--accent) 7%,var(--bg-tertiary)),var(--bg-secondary))}
.project-brain-title{display:flex;align-items:center;gap:10px;font-size:15.5px;font-weight:700;letter-spacing:0.01em;color:var(--text-primary)}
.project-brain-title-ico{display:inline-flex;color:var(--accent)}
.project-brain-title-ico svg{display:block}
.project-brain-close{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;background:transparent;border:none;color:var(--text-tertiary);font-size:var(--font-size-xl);line-height:1;cursor:pointer;border-radius:var(--radius-xs);transition:color var(--transition),background var(--transition),transform 0.12s ease}
.project-brain-close:hover{color:var(--text-primary);background:var(--bg-hover)}
.project-brain-close:active{transform:scale(0.9)}
.project-brain-head-actions{display:flex;align-items:center;gap:var(--space-2)}

/* ── Tab bar: the six surfaces shown one-at-a-time ──
   Six side-by-side columns would collapse to unreadable slivers on a narrow
   panel (width:min(960px,94vw)) — so we tab between them and give the ACTIVE
   surface the full width. Each tab carries a colour-coded dot + an optional
   count badge. */
/* Six tabs overflow the bar on a phone-width panel, and macOS auto-hides
   overlay scrollbars — so the trailing tabs looked like they simply weren't
   there. Lea-Verou scroll shadows: an edge shadow shows ONLY on a side that
   can still scroll (the `local` cover gradients mask the `scroll` shadow
   gradients at the extremes); the scrollbar itself stays hidden. */
.project-brain-tabs{display:flex;align-items:stretch;gap:2px;padding:0 var(--space-3);background-color:var(--bg-secondary);border-bottom:1px solid var(--border);overflow-x:auto;flex-shrink:0;scrollbar-width:none;
  background-image:linear-gradient(to right,var(--bg-secondary) 30%,transparent),linear-gradient(to right,transparent,var(--bg-secondary) 70%),radial-gradient(farthest-side at 0 50%,rgba(0,0,0,0.22),rgba(0,0,0,0)),radial-gradient(farthest-side at 100% 50%,rgba(0,0,0,0.22),rgba(0,0,0,0));
  background-position:0 0,100% 0,0 0,100% 0;background-repeat:no-repeat;
  background-size:32px 100%,32px 100%,10px 100%,10px 100%;
  background-attachment:local,local,scroll,scroll}
.project-brain-tabs::-webkit-scrollbar{height:0}
.pb-tab{position:relative;display:inline-flex;align-items:center;gap:7px;padding:var(--space-3) 15px;background:transparent;border:none;border-bottom:2px solid transparent;color:var(--text-tertiary);font-family:inherit;font-size:12.5px;font-weight:600;letter-spacing:0.01em;cursor:pointer;white-space:nowrap;transition:color var(--transition),border-color var(--transition)}
.pb-tab::before{content:'';width:7px;height:7px;border-radius:50%;background:currentColor;opacity:0.45;flex-shrink:0}
.pb-tab:hover{color:var(--text-secondary)}
.pb-tab-active{color:var(--text-primary);border-bottom-color:var(--accent)}
.pb-tab-active::before{opacity:1}
.pb-tab[data-pb-tab="charter"].pb-tab-active{color:var(--accent)}
.pb-tab[data-pb-tab="board"].pb-tab-active{color:var(--pb-green)}
.pb-tab[data-pb-tab="activity"].pb-tab-active{color:var(--pb-amber)}
.pb-tab-count{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 5px;font-size:10.5px;font-weight:700;line-height:1;border-radius:999px;background:var(--bg-tertiary);border:1px solid var(--border);color:var(--text-secondary)}
.pb-tab-count[hidden]{display:none}

/* ── Keyboard focus rings ──
   Every control is a real <button>/<input> reachable by Tab; one shared ring
   keeps keyboard navigation visible (`:focus-visible` never fires on mouse
   click, so pointer users see no change). */
.project-brain-overlay .pb-tab:focus-visible,
.project-brain-overlay .pb-btn:focus-visible,
.project-brain-overlay .pb-watch-composer select:focus-visible,
.project-brain-overlay .pb-watch-composer input:focus-visible,
.project-brain-overlay .pb-watch-composer button:focus-visible,
.project-brain-overlay .pb-watch-actions button:focus-visible,
.project-brain-overlay .pb-note-editor input:focus-visible,
.project-brain-overlay .project-brain-close:focus-visible{
  outline:2px solid color-mix(in srgb,var(--accent) 60%,transparent);
  outline-offset:2px;
  border-radius:var(--pb-radius-sm,4px);
}

/* Tab-panel host: the active panel fills the panel; the rest are hidden.
   NOTE: the panels carry BOTH .project-brain-col AND .pb-tab-panel, so the
   show/hide rules MUST out-specify .project-brain-col (which sets display:flex);
   a bare .pb-tab-panel selector has equal specificity and loses on source order,
   leaving every panel visible → tab clicks appear to do nothing. */
.project-brain-columns{flex:1;display:block;background:var(--bg-secondary);overflow:hidden;min-height:0}
.project-brain-col.pb-tab-panel{display:none;height:100%}
.project-brain-col.pb-tab-panel-active{display:flex}
.project-brain-col{background:var(--bg-secondary);display:flex;flex-direction:column;min-height:0;flex:1}
.project-brain-col-body{flex:1;overflow-y:auto;padding:var(--space-4) 18px;display:flex;flex-direction:column;max-width:820px;width:100%;margin:0 auto;box-sizing:border-box}
.project-brain-col-body::-webkit-scrollbar{width:8px}
.project-brain-col-body::-webkit-scrollbar-thumb{background:var(--border);border-radius:4px}
.project-brain-col-body::-webkit-scrollbar-thumb:hover{background:var(--border-light)}

/* Empty states — a centered, quiet dashed frame instead of bare text.
   .pb-board-empty doubles as the shared placeholder: project-brain.js renders
   it through _empty() on every surface. */
.pb-charter-empty,.pb-board-empty,.pb-activity-empty,.pb-status-empty{flex:1;display:flex;align-items:center;justify-content:center;min-height:200px;color:var(--text-tertiary);font-size:var(--font-size-md);text-align:center;padding:var(--space-6);margin:2px;border:1px dashed var(--border);border-radius:var(--pb-radius);background:color-mix(in srgb,var(--bg-tertiary) 30%,transparent)}

/* ── Shared card grammar ──
   One shape for every projected item — board work card, feed event, charter
   decision/checker row, watch item — so the eye learns the surface once.
   Status and severity read from the leading rail, never from saturated
   fills. */
.pb-board-card,.pb-activity-item,.pb-charter-decision,.pb-watch-item{background:var(--pb-card-bg);border:1px solid var(--border);border-radius:var(--pb-radius);padding:11px 13px;margin-bottom:9px;transition:border-color var(--transition),background var(--transition),transform 0.12s ease;animation:pbRowIn 0.24s cubic-bezier(0.16,1,0.3,1)}
.pb-board-card:hover,.pb-activity-item:hover,.pb-charter-decision:hover,.pb-watch-item:hover{border-color:var(--border-light);background:var(--pb-card-hover);transform:translateY(-1px)}
@keyframes pbRowIn{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:translateY(0)}}

/* Section block + small-caps head shared by Board lanes, Charter sections and
   the Watch lane. */
.pb-board-lane,.pb-charter-section,#pbWatchSection{margin-bottom:var(--space-5)}
.pb-board-lane:last-child,.pb-charter-section:last-child,#pbWatchSection:last-child{margin-bottom:0}
.pb-board-lane>h3,.pb-charter-section>h3,#pbWatchSection>h3{font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:var(--text-tertiary);margin:0 0 9px}

/* Card-internal type scale: title leads, body recedes, meta whispers. */
.pb-board-card-title{font-size:13.5px;font-weight:600;line-height:1.5;color:var(--text-primary);overflow-wrap:anywhere;word-break:break-word}
.pb-board-card-meta{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:6px;font-size:11.5px;color:var(--text-tertiary)}
.pb-board-card-desc{margin-top:6px;font-size:var(--font-size-sm);line-height:1.55;color:var(--text-secondary);overflow-wrap:anywhere;word-break:break-word}
.pb-activity-item time{display:block;margin-top:7px;font-size:10.5px;color:var(--text-tertiary)}

/* ── Board: active work + recent outcomes (read-only projection) ──
   The leading rail carries the status: active = green, completed = quiet
   green, failed = red, cancelled = neutral. */
.pb-board-card.pb-board-active{border-left:3px solid color-mix(in srgb,var(--pb-green) 65%,var(--border))}
.pb-board-card.pb-board-completed{border-left:3px solid color-mix(in srgb,var(--pb-green) 38%,var(--border));opacity:0.78}
.pb-board-card.pb-board-failed{border-left:3px solid color-mix(in srgb,var(--pb-red) 45%,var(--border))}
.pb-board-card.pb-board-cancelled{border-left:3px solid var(--border);opacity:0.7}

/* ── Activity feed ── */
.pb-activity-list{display:flex;flex-direction:column;min-height:100%}
.pb-activity-body{flex:1;min-width:0;display:flex;flex-direction:column;gap:var(--space-1)}
.pb-activity-body strong{font-size:var(--font-size-xs);font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:var(--accent)}
.pb-activity-body p{margin:0;font-size:12.5px;line-height:1.55;color:var(--text-primary);overflow-wrap:anywhere;word-break:break-word}

/* ── Charter: executable decisions + versioned checker catalog ── */
.pb-charter-decision{display:flex;align-items:flex-start;gap:10px;border-left:3px solid color-mix(in srgb,var(--accent) 55%,var(--border))}
.pb-decision-text{flex:1;min-width:0;font-size:var(--font-size-md);line-height:1.5;color:var(--text-primary);overflow-wrap:anywhere;word-break:break-word}
.pb-decision-text strong{font-weight:600}
.pb-decision-text code{display:inline-block;margin-top:3px;font-family:var(--font-mono,ui-monospace,monospace);font-size:var(--font-size-xs);color:var(--text-secondary);background:color-mix(in srgb,var(--bg-tertiary) 55%,transparent);border:1px solid var(--border);border-radius:5px;padding:2px 7px;overflow-wrap:anywhere;word-break:break-all}
.pb-decision-meta{margin-top:5px;font-size:var(--font-size-xs);color:var(--text-tertiary)}
/* One button vocabulary panel-wide: quiet default, accent fill for the single
   forward action (register / run). */
.pb-btn{display:inline-flex;align-items:center;gap:5px;align-self:center;flex-shrink:0;background:var(--bg-secondary);color:var(--text-secondary);border:1px solid var(--border);border-radius:var(--pb-radius-sm);padding:5px 11px;font-size:11.5px;font-weight:600;font-family:inherit;cursor:pointer;transition:color var(--transition),border-color var(--transition),background var(--transition)}
.pb-btn:hover{color:var(--text-primary);border-color:var(--border-light)}
.pb-btn:disabled{opacity:0.55;cursor:default}
.pb-btn.pb-btn-primary{background:var(--accent);color:#fff;border-color:var(--accent)}
.pb-btn.pb-btn-primary:hover{background:var(--accent-hover);color:#fff;border-color:var(--accent-hover)}
/* Checker registration form — stacked, full-width fields; argv/globs are
   JSON, so they read in mono. */
.pb-note-editor{display:flex;flex-direction:column;gap:var(--space-2);margin-top:var(--space-3);padding:var(--space-3);background:color-mix(in srgb,var(--bg-tertiary) 30%,transparent);border:1px solid var(--border);border-radius:var(--pb-radius)}
.pb-note-editor input{width:100%;box-sizing:border-box;background:var(--bg-primary);border:1px solid var(--border);border-radius:var(--pb-radius-sm);padding:7px 10px;font-size:var(--font-size-sm);color:var(--text-primary);font-family:inherit}
.pb-note-editor input[name="argv"],.pb-note-editor input[name="pathGlobs"]{font-family:var(--font-mono,ui-monospace,monospace);font-size:11.5px}
.pb-note-editor input:focus{outline:none;border-color:var(--accent)}
.pb-note-editor .pb-btn{align-self:flex-end}

/* ── Status & Watch: derived counters + the one human-maintained list ── */
.pb-status-evidence{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:18px;opacity:0.85}
.pb-status-ev-chip{font-size:var(--font-size-xs);font-weight:600;color:var(--text-secondary);padding:2px 9px;background:var(--bg-tertiary);border:1px solid var(--border);border-radius:999px}
.pb-watch-composer{display:flex;align-items:center;gap:var(--space-2);margin-bottom:var(--space-3);padding:11px var(--space-3);background:color-mix(in srgb,var(--bg-tertiary) 30%,transparent);border:1px solid var(--border);border-radius:var(--pb-radius)}
.pb-watch-composer select{flex-shrink:0;padding:6px var(--space-2);font:inherit;font-size:var(--font-size-sm);color:var(--text-primary);background:var(--bg-primary);border:1px solid var(--border);border-radius:var(--pb-radius-sm)}
.pb-watch-composer input{flex:1;min-width:0;padding:6px 10px;font:inherit;font-size:12.5px;color:var(--text-primary);background:var(--bg-primary);border:1px solid var(--border);border-radius:var(--pb-radius-sm)}
.pb-watch-composer select:focus,.pb-watch-composer input:focus{outline:none;border-color:color-mix(in srgb,var(--accent) 55%,transparent)}
.pb-watch-composer button{flex-shrink:0;padding:6px 14px;font:inherit;font-size:var(--font-size-sm);font-weight:600;color:#fff;background:var(--accent);border:1px solid var(--accent);border-radius:var(--pb-radius-sm);cursor:pointer;transition:opacity var(--transition)}
.pb-watch-composer button:hover{opacity:0.9}
@media (max-width:560px){.pb-watch-composer{flex-wrap:wrap}.pb-watch-composer input{flex-basis:100%}}
.pb-watch-item{display:flex;align-items:flex-start;gap:var(--space-3)}
.pb-watch-main{flex:1;min-width:0}
.pb-watch-main>strong{font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:0.04em;color:var(--text-secondary);padding:1px var(--space-2);background:var(--bg-tertiary);border:1px solid var(--border);border-radius:999px}
.pb-watch-main>p{margin:7px 0 0;font-size:var(--font-size-md);line-height:1.5;color:var(--text-primary);overflow-wrap:anywhere;word-break:break-word}
.pb-watch-verdict{margin-top:7px;padding:var(--space-2) 10px;font-size:var(--font-size-sm);line-height:1.55;color:var(--text-secondary);background:color-mix(in srgb,var(--bg-tertiary) 40%,transparent);border-radius:var(--pb-radius-sm);overflow-wrap:anywhere;word-break:break-word}
.pb-watch-actions{display:flex;flex-direction:column;gap:6px;flex-shrink:0}
.pb-watch-actions button{padding:var(--space-1) 11px;font:inherit;font-size:var(--font-size-xs);font-weight:600;color:var(--text-secondary);background:transparent;border:1px solid var(--border);border-radius:var(--pb-radius-sm);cursor:pointer;transition:color var(--transition),border-color var(--transition)}
.pb-watch-actions button:hover{color:var(--text-primary);border-color:var(--text-tertiary)}
.pb-watch-actions button:disabled{opacity:0.5;cursor:default}
.pb-watch-actions button[data-pb-action="delete-watch"]:hover{color:var(--pb-red);border-color:color-mix(in srgb,var(--pb-red) 55%,transparent)}

/* ── Responsive: narrow panel ──
   NOTE: .project-brain-columns is a display:block tab host (one panel visible
   at a time), NOT a grid. Tighten the body gutter, which is what actually
   buys reading width on a phone. */
@media (max-width:720px){
  .project-brain-col-body{padding:var(--space-3) var(--space-3)}
  .project-brain-tabs{padding:0 6px}
}
/* ══════════════════════════════════════════════════════════════════
   Local Knowledge workbench — independent from Settings → Tools
   ══════════════════════════════════════════════════════════════════ */
body.kb-open { overflow: hidden; }
.kb-overlay { padding: var(--space-5); background: rgba(10, 10, 12, .58); backdrop-filter: blur(5px); }
.kb-workbench {
  width: min(1120px, 94vw);
  height: min(860px, calc(var(--vh100, 100vh) - 40px));
  max-height: 94vh;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  overflow: hidden;
  color: var(--text-primary);
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 18px;
  box-shadow: 0 30px 90px rgba(0, 0, 0, .34);
}
.kb-workbench * { box-sizing: border-box; }
.kb-header {
  min-height: 76px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  padding: 14px var(--space-6);
  border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 94%, var(--accent) 6%);
}
.kb-heading { min-width: 0; display: flex; align-items: center; gap: var(--space-3); }
.kb-heading-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  color: var(--accent);
  background: var(--accent-subtle);
  border: 1px solid color-mix(in srgb, var(--accent) 45%, var(--border));
  border-radius: 11px;
}
.kb-eyebrow {
  margin-bottom: 2px;
  color: var(--accent);
  font: 700 10px/1.2 'JetBrains Mono', monospace;
  letter-spacing: .12em;
}
.kb-heading h2 { margin: 0; font-size: 20px; font-weight: 700; line-height: 1.25; letter-spacing: -.02em; }
.kb-heading p { max-width: 620px; margin: 3px 0 0; color: var(--text-secondary); font-size: var(--font-size-xs); line-height: 1.5; }
.kb-header-actions { flex: 0 0 auto; display: flex; align-items: center; gap: 10px; }
.kb-access-copy { max-width: 200px; display: flex; flex-direction: column; align-items: flex-end; gap: 2px; text-align: right; }
.kb-access-title { color: var(--text-primary); font-size: 12.5px; font-weight: 600; }
.kb-access-hint { color: var(--text-tertiary, var(--text-secondary)); font-size: var(--font-size-xs); line-height: 1.35; }
.kb-access-hint[data-tone="on"] { color: #38a169; }
.kb-access-hint[data-tone="off"] { color: #d69e2e; }
.kb-switch {
  position: relative;
  width: 42px;
  height: 24px;
  flex: 0 0 auto;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-tertiary);
  cursor: pointer;
  transition: background .18s ease, border-color .18s ease;
}
.kb-switch span {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--text-secondary);
  box-shadow: 0 1px 3px rgba(0, 0, 0, .22);
  transition: transform .18s ease, background .18s ease;
}
.kb-switch[aria-checked="true"] { background: var(--accent); border-color: var(--accent); }
.kb-switch[aria-checked="true"] span { transform: translateX(18px); background: white; }
.kb-switch:disabled { opacity: .42; cursor: not-allowed; }
.kb-switch:focus-visible, .kb-icon-btn:focus-visible, .kb-primary-btn:focus-visible,
.kb-dropzone:focus-visible, .kb-search-row input:focus-visible, .kb-search-row button:focus-visible,
.kb-doc-delete:focus-visible, .kb-doc-reindex:focus-visible, .kb-doc-view:focus-visible,
.kb-preview-head button:focus-visible, .kb-preview-status button:focus-visible,
.kb-category-tabs button:focus-visible, .kb-pagination button:focus-visible,
.kb-catalog-clear:focus-visible, .kb-preview-more:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.kb-icon-btn {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  padding: 0;
  color: var(--text-secondary);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 9px;
  cursor: pointer;
}
.kb-icon-btn:hover { color: var(--text-primary); background: var(--bg-hover); border-color: var(--border); }
.kb-stats {
  padding: 0 var(--space-6);
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border);
}
.kb-stats[data-empty="true"] { display: none; }
.kb-stats-text { display: block; padding: var(--space-2) 0; color: var(--text-secondary); font-size: var(--font-size-xs); line-height: 1.5; }
.kb-body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(330px, .8fr); overflow: hidden; }
.kb-library { min-width: 0; overflow-y: auto; padding: var(--space-5) var(--space-6) var(--space-6); }
.kb-search-panel {
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  padding: var(--space-5) var(--space-6) var(--space-6);
  background: var(--bg-primary);
  border-left: 1px solid var(--border);
}
.kb-section-head { display: flex; align-items: flex-start; gap: var(--space-4); margin-bottom: var(--space-3); }
.kb-section-head > div { flex: 1; min-width: 0; }
.kb-section-head h3, .kb-search-head h3 { margin: 0; font-size: 13.5px; font-weight: 700; line-height: 1.35; }
.kb-section-head p, .kb-search-head p { margin: 3px 0 0; color: var(--text-secondary); font-size: var(--font-size-xs); line-height: 1.5; }
.kb-primary-btn {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: 0 14px;
  color: #fff;
  background: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 8px;
  font: 600 12.5px/1 inherit;
  cursor: pointer;
  transition: transform .12s ease, filter .12s ease;
}
.kb-primary-btn:hover { filter: brightness(1.06); transform: translateY(-1px); }
.kb-primary-btn:disabled { opacity: .55; cursor: wait; transform: none; }
.kb-dropzone {
  min-height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
  padding: var(--space-3) var(--space-4);
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--bg-tertiary) 72%, transparent);
  border: 1.5px dashed color-mix(in srgb, var(--text-secondary) 45%, transparent);
  border-radius: 12px;
  cursor: pointer;
  transition: border-color .15s ease, background .15s ease, color .15s ease, min-height .2s ease;
}
.kb-dropzone:hover, .kb-dropzone.is-dragging {
  color: var(--accent);
  background: var(--accent-subtle);
  border-color: var(--accent);
}
.kb-drop-icon {
  width: 36px;
  height: 36px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 10px;
}
.kb-dropzone strong { display: block; color: var(--text-primary); font-size: 12.5px; font-weight: 600; }
.kb-dropzone small { display: block; margin-top: 2px; color: var(--text-secondary); font-size: var(--font-size-xs); line-height: 1.4; }
/* Empty corpus: the wide two-column frame reads as a stretched void when
   there is nothing to list, so the stage narrows into a single centered
   column — a hero dropzone with the catalog chrome (filter/sort/tabs/
   pagination) out of the way until there is something to filter. The fixed
   two-column stage returns as soon as documents exist: the catalog then
   needs a stable frame for filtering and pagination. */
.kb-workbench[data-has-docs="false"] { width: min(860px, 94vw); height: auto; }
.kb-workbench[data-has-docs="false"] .kb-body { display: flex; flex-direction: column; overflow-y: auto; }
.kb-workbench[data-has-docs="false"] .kb-library { display: flex; flex-direction: column; overflow: visible; padding: 26px var(--space-8) 10px; }
.kb-workbench[data-has-docs="false"] .kb-dropzone {
  min-height: 190px;
  flex: 1 0 auto;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-1);
  padding: 30px var(--space-6);
  text-align: center;
  background: color-mix(in srgb, var(--accent-subtle) 45%, transparent);
}
.kb-workbench[data-has-docs="false"] .kb-drop-icon {
  width: 52px;
  height: 52px;
  color: var(--accent);
  background: var(--accent-subtle);
  border-color: color-mix(in srgb, var(--accent) 32%, var(--border));
  border-radius: 14px;
}
.kb-workbench[data-has-docs="false"] .kb-dropzone strong { font-size: 13.5px; }
.kb-workbench[data-has-docs="false"] .kb-catalog-toolbar,
.kb-workbench[data-has-docs="false"] .kb-category-tabs,
.kb-workbench[data-has-docs="false"] .kb-catalog-summary,
.kb-workbench[data-has-docs="false"] .kb-pagination { display: none; }
.kb-workbench[data-has-docs="false"] .kb-doc-list { min-height: 0; }
.kb-workbench[data-has-docs="false"] .kb-empty-state { min-height: 0; padding: var(--space-2) var(--space-5) 6px; }
.kb-workbench[data-has-docs="false"] .kb-empty-mark { display: none; }
/* …and the right search column folds into a compact bottom band: test-query
   form on the left, vision/privacy settings on the right, so the empty stage
   keeps a balanced portrait proportion instead of two hollow columns. */
.kb-workbench[data-has-docs="false"] .kb-search-panel {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, .75fr);
  column-gap: 28px;
  overflow: visible;
  margin-top: 10px;
  padding: 18px var(--space-8) var(--space-5);
  border-top: 1px solid var(--border);
  border-left: 0;
}
.kb-workbench[data-has-docs="false"] .kb-search-head { grid-column: 1; grid-row: 1; margin-bottom: 10px; }
.kb-workbench[data-has-docs="false"] .kb-search-form { grid-column: 1; grid-row: 2; }
.kb-workbench[data-has-docs="false"] .kb-search-results { grid-column: 1; grid-row: 3; min-height: 0; margin-top: 10px; }
.kb-workbench[data-has-docs="false"] .kb-search-empty {
  min-height: 0;
  flex-direction: row;
  gap: 10px;
  justify-content: flex-start;
  padding: 10px 2px 0;
  text-align: left;
}
.kb-workbench[data-has-docs="false"] .kb-search-empty > span { font-size: var(--font-size-2xl); }
.kb-workbench[data-has-docs="false"] .kb-search-empty p { max-width: none; margin: 0; }
.kb-workbench[data-has-docs="false"] .kb-panel-foot {
  grid-column: 2;
  grid-row: 1 / 4;
  align-self: start;
  margin-top: 0;
  padding-top: 2px;
  padding-left: 26px;
  border-top: 0;
  border-left: 1px solid var(--border);
}
.kb-upload-report { display: none; }
.kb-upload-report.is-visible {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: var(--space-3);
  padding: 10px var(--space-3);
  border: 1px solid var(--border);
  border-radius: 10px;
  font-size: var(--font-size-xs);
}
.kb-upload-report.is-loading { background: var(--accent-subtle); border-color: color-mix(in srgb, var(--accent) 38%, var(--border)); }
.kb-upload-report.is-success { background: rgba(56, 161, 105, .09); border-color: rgba(56, 161, 105, .35); }
.kb-upload-report.is-warning { background: rgba(214, 158, 46, .1); border-color: rgba(214, 158, 46, .38); }
.kb-upload-report > div { flex: 1; min-width: 0; }
.kb-upload-report strong, .kb-upload-report span { display: block; }
.kb-upload-report > div > span { margin-top: 2px; color: var(--text-secondary); line-height: 1.45; overflow-wrap: anywhere; }
.kb-upload-report > button { padding: 0 3px; color: var(--text-secondary); background: none; border: 0; font-size: var(--font-size-xl); cursor: pointer; }
.kb-report-mark { width: 18px; height: 18px; display: grid !important; place-items: center; border-radius: 50%; font-weight: 700; }
.is-success .kb-report-mark { color: #38a169; background: rgba(56, 161, 105, .14); }
.is-warning .kb-report-mark { color: #b7791f; background: rgba(214, 158, 46, .14); }
.kb-catalog-toolbar { display: flex; align-items: stretch; gap: var(--space-2); margin: 0 0 var(--space-2); }
.kb-catalog-search {
  min-width: 0;
  height: 36px;
  flex: 1;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: 0 10px;
  color: var(--text-tertiary, var(--text-secondary));
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: 10px;
}
.kb-catalog-search:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-subtle); }
.kb-catalog-search input { min-width: 0; flex: 1; padding: 0; color: var(--text-primary); background: transparent; border: 0; outline: 0; font: 400 12.5px/1.3 inherit; }
.kb-catalog-search input::-webkit-search-cancel-button { display: none; }
.kb-catalog-clear { width: 24px; height: 24px; padding: 0; color: var(--text-secondary); background: transparent; border: 0; border-radius: 6px; font-size: var(--font-size-xl); cursor: pointer; }
.kb-catalog-clear:hover { color: var(--text-primary); background: var(--bg-hover); }
.kb-sort-field { position: relative; min-width: 128px; height: 36px; display: flex; align-items: center; }
.kb-sort-field > span { position: absolute; left: 10px; z-index: 1; color: var(--text-tertiary, var(--text-secondary)); font-size: 10px; pointer-events: none; }
.kb-sort-field select { width: 100%; height: 36px; padding: 0 26px 0 var(--space-10); color: var(--text-primary); background: var(--bg-primary); border: 1px solid var(--border); border-radius: 10px; outline: 0; font: 600 12px/1 inherit; cursor: pointer; }
.kb-sort-field select:focus-visible { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-subtle); }
.kb-category-tabs { display: flex; gap: 6px; margin: 0 -2px var(--space-2); padding: 2px; overflow-x: auto; scrollbar-width: none; }
.kb-category-tabs::-webkit-scrollbar { display: none; }
.kb-category-tabs button { min-width: max-content; height: 30px; display: inline-flex; align-items: center; gap: 6px; padding: 0 10px; color: var(--text-secondary); background: transparent; border: 1px solid transparent; border-radius: 8px; font: 600 12px/1 inherit; cursor: pointer; }
.kb-category-tabs button strong { color: var(--text-tertiary, var(--text-secondary)); font: 700 10px/1 'JetBrains Mono', monospace; }
.kb-category-tabs button:hover { color: var(--text-primary); background: var(--bg-hover); }
.kb-category-tabs button[aria-pressed="true"] { color: var(--accent); background: var(--accent-subtle); border-color: color-mix(in srgb, var(--accent) 28%, transparent); }
.kb-category-tabs button[aria-pressed="true"] strong { color: var(--accent); }
.kb-catalog-summary { min-height: 20px; display: flex; align-items: center; justify-content: space-between; color: var(--text-tertiary, var(--text-secondary)); font-size: var(--font-size-xs); }
.kb-catalog-refresh { display: inline-flex; }
.kb-catalog-refresh .kb-spinner { width: 12px; height: 12px; border-width: 1.5px; }
.kb-doc-list { min-height: 120px; display: flex; flex-direction: column; gap: var(--space-2); }
.kb-doc-card {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-3) 14px;
  background: color-mix(in srgb, var(--bg-primary) 96%, var(--accent) 4%);
  border: 1px solid var(--border-light, var(--border));
  border-radius: 12px;
  transition: border-color .14s ease, background .14s ease;
}
.kb-doc-card:hover { background: var(--bg-hover); border-color: color-mix(in srgb, var(--accent) 36%, var(--border)); }
.kb-doc-kind {
  width: 36px;
  height: 40px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  color: var(--accent);
  background: var(--accent-subtle);
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--border));
  border-radius: 8px;
  font: 700 9px/1 'JetBrains Mono', monospace;
  letter-spacing: .04em;
}
.kb-doc-content { flex: 1; min-width: 0; padding-top: 1px; }
.kb-doc-title-row { display: flex; align-items: center; gap: var(--space-2); }
.kb-doc-title-row strong { min-width: 0; overflow: hidden; color: var(--text-primary); font-size: 12.5px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.kb-warning-count { flex: 0 0 auto; padding: 2px 6px; color: #b7791f; background: rgba(214, 158, 46, .11); border-radius: 6px; font-size: 10px; font-weight: 700; }
.kb-doc-meta { margin-top: 3px; color: var(--text-secondary); font-size: var(--font-size-xs); line-height: 1.45; overflow-wrap: anywhere; }
.kb-doc-warnings { margin-top: var(--space-1); color: #b7791f; font-size: var(--font-size-xs); }
.kb-doc-warnings summary { cursor: pointer; }
.kb-doc-warnings ul { margin: var(--space-1) 0 0; padding-left: var(--space-4); color: var(--text-secondary); line-height: 1.45; }
.kb-doc-actions { flex: 0 0 auto; display: flex; align-items: center; gap: 2px; }
.kb-doc-view {
  min-width: 30px;
  height: 30px;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 var(--space-2);
  color: var(--accent);
  background: var(--accent-subtle);
  border: 1px solid color-mix(in srgb, var(--accent) 22%, transparent);
  border-radius: 8px;
  font: 600 11px/1 inherit;
  cursor: pointer;
}
.kb-doc-view:hover, .kb-doc-view[aria-expanded="true"] {
  border-color: color-mix(in srgb, var(--accent) 48%, var(--border));
  filter: brightness(1.04);
}
.kb-doc-delete, .kb-doc-reindex { width: 30px; height: 30px; flex: 0 0 auto; display: grid; place-items: center; padding: 0; color: var(--text-tertiary, var(--text-secondary)); background: transparent; border: 1px solid transparent; border-radius: 8px; cursor: pointer; }
.kb-doc-reindex:hover { color: var(--accent); background: var(--accent-subtle); border-color: color-mix(in srgb, var(--accent) 24%, transparent); }
.kb-doc-delete:hover { color: #e05252; background: rgba(224, 82, 82, .09); border-color: rgba(224, 82, 82, .22); }
.kb-doc-preview {
  flex: 0 0 100%;
  min-width: 0;
  margin-top: var(--space-1);
  overflow: hidden;
  background: color-mix(in srgb, var(--bg-secondary) 94%, var(--accent) 6%);
  border: 1px solid color-mix(in srgb, var(--accent) 20%, var(--border));
  border-radius: 10px;
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--accent) 68%, transparent);
}
.kb-preview-head {
  min-height: 42px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-3);
  border-bottom: 1px solid var(--border);
}
.kb-preview-head strong, .kb-preview-head span { display: block; }
.kb-preview-head strong { color: var(--text-primary); font-size: 12.5px; font-weight: 600; }
.kb-preview-head span { margin-top: 2px; color: var(--text-secondary); font-size: var(--font-size-xs); }
.kb-preview-head button {
  width: 28px;
  height: 28px;
  padding: 0;
  color: var(--text-secondary);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 8px;
  font-size: var(--font-size-xl);
  cursor: pointer;
}
.kb-preview-head button:hover { color: var(--text-primary); background: var(--bg-hover); border-color: var(--border); }
.kb-preview-body { max-height: 460px; overflow: auto; padding: var(--space-3); overscroll-behavior: contain; scrollbar-gutter: stable; }
.kb-preview-chunk + .kb-preview-chunk { margin-top: var(--space-3); }
.kb-preview-chunk-head { display: flex; align-items: center; gap: var(--space-2); padding: 0 2px 6px; }
.kb-preview-chunk-head strong { min-width: 0; flex: 1; color: var(--text-primary); font-size: var(--font-size-sm); font-weight: 600; overflow-wrap: anywhere; }
.kb-preview-chunk-head span { flex: 0 0 auto; color: var(--text-tertiary, var(--text-secondary)); font: 400 10px/1.3 'JetBrains Mono', monospace; }
.kb-preview-chunk-head span.kb-preview-ordinal { width: 20px; height: 20px; display: grid; place-items: center; color: var(--accent); background: var(--accent-subtle); border-radius: 6px; font-weight: 700; }
.kb-preview-chunk pre {
  margin: 0;
  padding: var(--space-3) 14px;
  color: var(--text-primary);
  background: var(--bg-primary);
  border: 1px solid var(--border-light, var(--border));
  border-radius: 8px;
  font: 400 12.5px/1.7 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.kb-preview-more { width: 100%; min-height: 34px; margin-top: var(--space-3); color: var(--accent); background: var(--accent-subtle); border: 1px solid color-mix(in srgb, var(--accent) 24%, transparent); border-radius: 8px; font: 600 12px/1 inherit; cursor: pointer; }
.kb-preview-more:hover { border-color: color-mix(in srgb, var(--accent) 48%, var(--border)); }
.kb-preview-more:disabled { opacity: .6; cursor: wait; }
.kb-preview-status { min-height: 88px; display: flex; align-items: center; justify-content: center; gap: var(--space-2); padding: var(--space-4); color: var(--text-secondary); font-size: var(--font-size-xs); }
.kb-preview-status.is-error { color: #e05252; }
.kb-preview-status button { padding: 6px 10px; color: var(--text-primary); background: var(--bg-tertiary); border: 1px solid var(--border); border-radius: 8px; font-size: var(--font-size-xs); cursor: pointer; }
.kb-empty-state, .kb-error-state {
  min-height: 150px;
  display: flex;
