  align-items: center;
  justify-content: center;
  padding: var(--space-5) var(--space-6);
  text-align: center;
  color: var(--text-secondary);
}
.kb-empty-mark { margin-bottom: 6px; color: var(--accent); font-size: 26px; font-weight: 300; line-height: 1; }
.kb-empty-state strong, .kb-error-state strong { color: var(--text-primary); font-size: 13.5px; font-weight: 600; }
.kb-empty-state p, .kb-error-state span { max-width: 420px; margin: var(--space-1) 0 0; font-size: var(--font-size-xs); line-height: 1.55; }
.kb-empty-state button, .kb-error-state button { margin-top: 10px; padding: 6px var(--space-3); color: var(--text-primary); background: transparent; border: 1px solid var(--border); border-radius: 8px; font-size: var(--font-size-sm); cursor: pointer; }
.kb-empty-state button:hover, .kb-error-state button:hover { color: var(--accent); border-color: var(--accent); }
.kb-pagination { display: flex; align-items: center; justify-content: center; gap: var(--space-3); padding-top: var(--space-3); }
.kb-pagination[hidden] { display: none; }
.kb-pagination span { min-width: 90px; color: var(--text-tertiary, var(--text-secondary)); font-size: var(--font-size-xs); text-align: center; }
.kb-pagination button { height: 32px; padding: 0 var(--space-3); color: var(--text-primary); background: var(--bg-primary); border: 1px solid var(--border); border-radius: 8px; font: 600 12px/1 inherit; cursor: pointer; }
.kb-pagination button:hover:not(:disabled) { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 45%, var(--border)); }
.kb-pagination button:disabled { opacity: .4; cursor: not-allowed; }
.kb-loading, .kb-search-loading { min-height: 110px; display: flex; align-items: center; justify-content: center; gap: var(--space-2); color: var(--text-secondary); font-size: var(--font-size-xs); }
.kb-spinner { width: 15px; height: 15px; flex: 0 0 auto; border: 2px solid color-mix(in srgb, var(--text-secondary) 24%, transparent); border-top-color: var(--accent); border-radius: 50%; animation: kb-spin .75s linear infinite; }
@keyframes kb-spin { to { transform: rotate(360deg); } }
.kb-search-head { margin-bottom: var(--space-3); }
.kb-search-form label { display: block; margin-bottom: 6px; color: var(--text-secondary); font-size: var(--font-size-xs); font-weight: 600; }
.kb-search-row { display: flex; gap: var(--space-2); }
.kb-search-row input {
  min-width: 0;
  flex: 1;
  height: 38px;
  margin: 0;
  padding: 0 var(--space-3);
  color: var(--text-primary);
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 10px;
  outline: 0;
  font: 400 12.5px/1.3 inherit;
}
.kb-search-row input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-subtle); }
.kb-search-row button { flex: 0 0 auto; height: 38px; padding: 0 var(--space-4); color: #fff; background: var(--accent); border: 1px solid var(--accent); border-radius: 10px; font: 700 12.5px/1 inherit; cursor: pointer; }
.kb-search-row button:disabled { opacity: .55; cursor: wait; }
.kb-search-results { min-height: 200px; flex: 1 0 auto; margin-top: var(--space-3); }
.kb-search-empty { min-height: 180px; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: var(--space-5); color: var(--text-secondary); text-align: center; }
.kb-search-empty > span { color: var(--accent); font-size: 26px; font-weight: 300; }
.kb-search-empty p { max-width: 260px; margin: var(--space-1) 0 0; font-size: var(--font-size-xs); line-height: 1.55; }
.kb-search-message { padding: var(--space-3) 14px; color: var(--text-secondary); background: var(--bg-secondary); border: 1px solid var(--border); border-radius: 10px; }
.kb-search-message.is-error { border-color: rgba(224, 82, 82, .35); }
.kb-search-message strong, .kb-search-message span { display: block; }
.kb-search-message strong { color: var(--text-primary); font-size: 12.5px; font-weight: 600; }
.kb-search-message span { margin-top: 3px; font-size: var(--font-size-xs); line-height: 1.5; }
.kb-result-summary { margin-bottom: var(--space-2); color: var(--text-secondary); font-size: var(--font-size-xs); font-weight: 600; }
.kb-result { margin-bottom: var(--space-2); padding: var(--space-3); background: var(--bg-secondary); border: 1px solid var(--border-light, var(--border)); border-radius: 10px; }
.kb-result-head { display: flex; align-items: center; gap: var(--space-2); }
.kb-result-head > span { width: 18px; height: 18px; display: grid; place-items: center; color: var(--accent); background: var(--accent-subtle); border-radius: 6px; font-size: 10px; font-weight: 700; }
.kb-result-head strong { min-width: 0; overflow: hidden; font-size: 12.5px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.kb-result-location { margin: var(--space-1) 0 0 26px; color: var(--accent); font-size: var(--font-size-xs); line-height: 1.35; }
.kb-result-assets { display: flex; gap: var(--space-2); margin-top: var(--space-2); overflow-x: auto; }
.kb-result-assets a { position: relative; width: 92px; height: 68px; flex: 0 0 auto; overflow: hidden; color: #fff; background: var(--bg-tertiary); border: 1px solid var(--border); border-radius: 8px; }
.kb-result-assets img { width: 100%; height: 100%; display: block; color: var(--text-secondary); font-size: 9px; line-height: 1.3; object-fit: cover; }
.kb-result-assets span { position: absolute; right: 3px; bottom: 3px; left: 3px; overflow: hidden; padding: 2px var(--space-1); background: rgba(0, 0, 0, .66); border-radius: 4px; font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.kb-result pre { max-height: 210px; overflow: auto; margin: var(--space-2) 0 0; padding: 10px var(--space-3); color: var(--text-secondary); background: var(--bg-primary); border-radius: 8px; font: 400 11px/1.6 'JetBrains Mono', monospace; white-space: pre-wrap; overflow-wrap: anywhere; }
.kb-panel-foot { margin-top: var(--space-4); padding-top: var(--space-3); border-top: 1px solid var(--border); }
.kb-vision-row { display: flex; align-items: center; gap: var(--space-3); }
.kb-vision-copy { min-width: 0; flex: 1; }
.kb-vision-copy strong, .kb-vision-copy span { display: block; }
.kb-vision-copy strong { font-size: 12.5px; font-weight: 600; }
.kb-vision-copy span { margin-top: 2px; color: var(--text-secondary); font-size: var(--font-size-xs); line-height: 1.45; }
.kb-privacy-note { display: flex; align-items: flex-start; gap: 6px; margin: 10px 0 0; color: var(--text-tertiary, var(--text-secondary)); font-size: var(--font-size-xs); line-height: 1.5; }
.kb-privacy-note svg { flex: 0 0 auto; margin-top: 2px; color: #38a169; }
[data-theme="tofu"] .kb-workbench { background: #fffdf7; border-color: rgba(74, 63, 47, .22); box-shadow: 10px 10px 0 rgba(74, 63, 47, .24), 0 24px 70px rgba(74, 63, 47, .2); }
[data-theme="tofu"] .kb-header { background: #fff9e8; }
[data-theme="tofu"] .kb-stats, [data-theme="tofu"] .kb-search-panel,
[data-theme="tofu"] .kb-doc-card, [data-theme="tofu"] .kb-result pre,
[data-theme="tofu"] .kb-catalog-search, [data-theme="tofu"] .kb-sort-field select { background: #faf6ec; }
[data-theme="tofu"] .kb-primary-btn, [data-theme="tofu"] .kb-search-row button { color: #1a1814; }
@media (max-width: 980px) {
  .kb-workbench { width: min(920px, 96vw); }
  .kb-body { grid-template-columns: minmax(0, 1.2fr) minmax(300px, .8fr); }
  .kb-access-copy { max-width: 90px; }
  .kb-access-hint { display: none; }
}
@media (max-width: 768px), (max-width: 1024px) and (pointer: coarse) {
  .kb-overlay { padding: 0; }
  .kb-workbench { width: 100%; height: var(--vh100, 100dvh); max-height: none; border: 0; border-radius: 0; box-shadow: none; }
  .kb-workbench[data-has-docs="false"] { width: 100%; height: var(--vh100, 100dvh); }
  .kb-header { min-height: 64px; padding: var(--space-3) var(--space-4); gap: 10px; }
  .kb-heading { gap: 10px; }
  .kb-heading-icon { width: 36px; height: 36px; border-radius: 10px; }
  .kb-heading-icon svg { width: 18px; height: 18px; }
  .kb-eyebrow, .kb-heading p { display: none; }
  .kb-heading h2 { font-size: var(--font-size-2xl); }
  .kb-header-actions { gap: var(--space-2); }
  .kb-access-copy { max-width: 68px; }
  .kb-access-title { font-size: var(--font-size-xs); line-height: 1.25; }
  .kb-stats { padding: 0 var(--space-4); }
  .kb-body { display: block; overflow-y: auto; }
  .kb-library, .kb-search-panel { overflow: visible; padding: var(--space-4) var(--space-4) var(--space-5); }
  .kb-search-panel { border-top: 1px solid var(--border); border-left: 0; }
  .kb-search-results { min-height: 160px; }
  .kb-workbench[data-has-docs="false"] .kb-body { overflow: visible; }
  .kb-workbench[data-has-docs="false"] .kb-library,
  .kb-workbench[data-has-docs="false"] .kb-search-panel { display: flex; flex-direction: column; margin-top: 0; padding: var(--space-4) var(--space-4) var(--space-5); }
  .kb-workbench[data-has-docs="false"] .kb-panel-foot { margin-top: var(--space-4); padding-top: var(--space-3); padding-left: 0; border-top: 1px solid var(--border); border-left: 0; }
  .kb-workbench[data-has-docs="false"] .kb-dropzone { min-height: 180px; }
  .kb-section-head { gap: 10px; }
  .kb-primary-btn { padding: 0 var(--space-3); }
  .kb-dropzone { padding: var(--space-3) 14px; }
