@media (max-width: 460px) {
  .kb-workbench[data-has-docs="true"] .kb-drop-icon { display: none; }
  .kb-doc-card { padding: 10px; }
  .kb-sort-field { min-width: 108px; }
  .kb-sort-field > span { display: none; }
  .kb-sort-field select { padding-left: 10px; }
  .kb-category-tabs { margin-right: -16px; padding-right: var(--space-4); }
  .kb-doc-kind { width: 32px; height: 36px; }
  .kb-doc-view span { display: none; }
  .kb-preview-body { max-height: 54vh; padding: 10px; }
  .kb-preview-chunk-head { flex-wrap: wrap; }
  .kb-preview-chunk-head strong { flex-basis: calc(100% - 30px); }
  .kb-preview-chunk-head > span:last-child:not(.kb-preview-ordinal) { flex-basis: 100%; margin-left: 28px; }
  .kb-preview-chunk pre { padding: 10px var(--space-3); font-size: var(--font-size-sm); }
