/*
 * Turn reading system.
 *
 * Responsibility: turn layout and round boundaries. Prose, process, evidence,
 * actions, responsive behavior and editing have separate manifest owners.
 */

.conversation-surface {
  font-family: var(--font-ui);
  font-size: var(--conversation-font-size-content);
  line-height: var(--leading-body);
  --turn-rule: color-mix(in srgb, var(--border) 78%, transparent);
  --turn-spine: color-mix(in srgb, var(--text-tertiary) 24%, transparent);
  --turn-process-surface: color-mix(in srgb, var(--bg-secondary) 62%, transparent);
  --turn-process-hover: color-mix(in srgb, var(--bg-hover) 70%, transparent);
  --turn-process-panel: color-mix(in srgb, var(--bg-secondary) 72%, var(--bg-primary));
  --turn-process-line: color-mix(in srgb, var(--border) 74%, var(--bg-primary));
}

[data-theme="tofu"] .conversation-surface {
  --turn-rule: var(--border);
  --turn-spine: var(--border-light);
  --turn-process-surface: color-mix(in srgb, var(--bg-secondary) 72%, transparent);
  --turn-process-hover: color-mix(in srgb, var(--bg-hover) 78%, transparent);
}

.conversation-surface :is(summary, button) {
  touch-action: manipulation;
  -webkit-tap-highlight-color: color-mix(in srgb, var(--accent) 16%, transparent);
}

/* One calm reading column: compact identity at the left, prose on the page. */

.conversation-surface .conversation-turn.message {
  position: relative;
  grid-template-columns: minmax(0, 1fr) var(--rail-w);
  column-gap: var(--space-3);
  margin-bottom: var(--space-10);
  overflow: visible;
}

/* Turn avatars removed (2026-10-19): the role icon box read as clutter and forced
 * a hanging indent on every agent line. The role label in the header carries the
 * identity; the gutter is now flush-left. The node stays in the DOM (keyed slot)
 * but is never shown. */
.conversation-surface .conversation-turn.message > .conversation-turn-avatar.message-avatar {
  display: none;
}

.conversation-surface .conversation-turn-content.message-content {
  grid-column: 1;
  overflow: visible;
  max-width: var(--msg-measure);
  min-width: 0;
  font-size: var(--conversation-font-size-body);
}

.conversation-surface .conversation-turn > .conversation-turn-context-rail { grid-column: 2; }

.conversation-surface .conversation-turn-header.message-header {
  justify-content: flex-start;
  min-height: var(--control-h-md);
  margin: 0 0 var(--space-3);
  gap: var(--space-2);
  line-height: 1.25;
}

.conversation-surface .message-role {
  color: var(--text-primary);
  font-size: var(--conversation-process-font-size);
  font-weight: var(--weight-bold);
  letter-spacing: .006em;
}

.conversation-surface .message-time {
  display: inline-flex;
  align-items: center;
  margin: 0;
  color: var(--text-tertiary);
  font-size: var(--conversation-font-size-caption);
  font-variant-numeric: tabular-nums;
  letter-spacing: .015em;
  white-space: nowrap;
}

.conversation-surface .message-time::before {
  width: 2px;
  height: 2px;
  margin-right: var(--space-2);
  border-radius: 50%;
  background: currentColor;
  content: "";
  opacity: .56;
}

.conversation-surface .conversation-turn-blocks {
  overflow: visible;
  gap: 0;
}

.conversation-surface .conversation-turn-blocks > .conversation-block {
  margin: 0;
}

/* Flush-left reading: with the avatar gutter removed, role text, actions and
 * footer all start at the page margin. */

/* One spacing owner, including the demand-mounted historical process body.
 * Adjacent process rows form a compact run. Prose gets a paragraph's breath
 * on either side without moving, grouping or recreating any keyed leaf. */
.conversation-surface :is(.conversation-turn-blocks, [data-history-process-blocks]) > .conversation-block + .conversation-block {
  margin-block-start: var(--conversation-flow-gap);
}

.conversation-surface :is(.conversation-turn-blocks, [data-history-process-blocks]) > .conversation-block--text + .conversation-block,
.conversation-surface :is(.conversation-turn-blocks, [data-history-process-blocks]) > .conversation-block + .conversation-block--text {
  margin-block-start: var(--conversation-prose-gap);
}

.conversation-surface .conversation-turn-blocks > .conversation-block:last-child {
  margin-bottom: 0;
}

/* Adjacent process leaves form one quiet run. The derived edges describe the
 * mounted order only: narration, deliverables and page boundaries break the
 * run. No extra wrapper, duplicate content or disclosure state.
 *
 * 2026-10-19 declutter: the process column no longer hangs in a separate
 * narrow gutter. Process rows now start at the same reading baseline as the
 * narration and answer text (`--conversation-process-indent`), so the whole
 * turn reads as ONE calm left edge instead of a wire holding a stray column
 * of icons out to the left. The old `data-process-edge` vertical spine and
 * its boxed side borders are gone — grouping is carried by shared alignment
 * and rhythm, not a rail. */
.conversation-surface :is(.conversation-turn-blocks, [data-history-process-blocks]) > .conversation-block[data-process-edge] {
  position: relative;
  margin-block-start: 0;
  /* Align the row's icon to the shared reading baseline. The row pads in by
   * the full reading inset (the same edge the role label, narration and answer
   * text use), so the leading icon lands on that one vertical line and the
   * whole turn reads as a single calm left edge — no stray icon gutter. */
  padding-inline-start: var(--conversation-reading-inset);
}

.conversation-surface :is(.conversation-turn-blocks, [data-history-process-blocks]) > .conversation-block[data-process-edge]:is([data-process-edge="start"], [data-process-edge="single"]) {
  margin-block-start: var(--space-4);
}

/* No vertical spine. The 2026-07-08 chrome-less card model removed the rail
 * that welded rounds into one column; the recent `data-process-edge` rail
 * re-introduced it as a faint wire. Both the owner report and the card-model
 * invariant (tests/frontend/test_frontend_segment_timeline.py) agree: the
 * process run groups by shared alignment and spacing, not by a line.
 *
 * ONLY the active (still running) step keeps a whisper of tint. A settled
 * failure gets no wash at all: it previously used the same background as the
 * running state, so the block read as a stuck running indicator long after
 * the round had failed (owner report 2026-10-20). The failure verdict pill
 * and the `conversation-action-state` chip already state the outcome; a
 * persistent full-row tint is redundant emphasis.
 *
 * The tint is clipped to the content box: these rows pad in by the reading
 * inset, so a padding-box background painted a band 33px wider than the row's
 * own content — the running command looked like it had flooded the whole
 * horizontal lane instead of lighting up its own box. */
.conversation-surface .conversation-block[data-process-edge][data-action-state="active"] {
  background-color: color-mix(in srgb, var(--accent) 5%, transparent);
  background-clip: content-box;
  border-radius: var(--radius-sm);
}

/* Leaves remain direct keyed children so streaming never reparents live cards. */

.conversation-surface .conversation-turn-blocks {
  min-width: 0;
  padding-inline-start: 0;
}

.conversation-surface .conversation-round-header {
  margin: var(--space-1) 0 var(--space-2);
  font: inherit;
}

.conversation-surface .conversation-round-header__toggle {
  width: 100%;
  min-width: 0;
  height: auto;
  justify-content: flex-start;
  gap: var(--space-2);
  padding: var(--space-2);
  text-align: start;
  white-space: normal;
}

.conversation-surface .conversation-round-header__chevron {
  width: var(--space-4);
  height: var(--space-4);
  flex: 0 0 auto;
  color: var(--text-secondary);
  transform: rotate(0deg);
}

.conversation-surface .conversation-round-header__toggle[aria-expanded="true"] .conversation-round-header__chevron {
  transform: rotate(90deg);
}

.conversation-surface .conversation-round-header__title {
  color: var(--text-secondary);
  font-weight: var(--weight-medium);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--conversation-font-size-content);
}

.conversation-surface .conversation-round-header__summary {
  flex-shrink: 0;
}

.conversation-surface .conversation-round-header__summary,
.conversation-surface .conversation-round-header__status {
  color: var(--text-secondary);
  font-size: var(--conversation-font-size-meta);
}

.conversation-surface .conversation-round-header__status {
  margin-inline-start: auto;
  text-align: end;
}

.conversation-surface [data-round-state="active"] .conversation-round-header__status {
  color: var(--accent);
}

.conversation-surface [data-round-state="attention"] .conversation-round-header__status {
  color: var(--warning-text);
}

.conversation-surface .conversation-round-header__toggle:focus-visible {
  box-shadow: var(--focus-ring);
}

/* Hidden disclosures must win over card display:flex/grid rules. */

.conversation-surface .conversation-block[hidden] {
  display: none;
}

.conversation-surface .conversation-block + .conversation-block--text[data-deliverable="true"] {
  margin-block-start: var(--conversation-answer-gap);
}

.conversation-surface .conversation-block--text[data-deliverable="true"] > .md-content {
  font-size: var(--conversation-font-size-body);
  line-height: var(--leading-body);
  letter-spacing: .002em;
}

/* Routine success is quiet; errors and active states remain visible. */
.conversation-surface .conversation-tool-card__chip {
  font-size: var(--conversation-font-size-caption);
  line-height: 1.4;
  padding: var(--control-edge-inset) var(--space-2);
  border-radius: 4px;
}
.conversation-surface .conversation-tool-card__chip--ok {
  color: var(--text-tertiary);
  background: transparent;
}
.conversation-surface .conversation-tool-card__chip--err {
  color: var(--error-text);
  background: color-mix(in srgb, var(--error-text) 8%, transparent);
}
.conversation-surface .conversation-tool-card__chip--active {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, transparent);
}
.conversation-surface .conversation-tool-card__chip--muted {
  color: var(--text-tertiary);
  background: transparent;
}

/* Action state indicator on generic result summaries. */
.conversation-surface .conversation-action-state {
  font-size: var(--conversation-font-size-caption);
  line-height: 1.4;
  padding: var(--control-edge-inset) var(--space-2);
  border-radius: 4px;
  margin-left: auto;
  flex-shrink: 0;
}
.conversation-surface .conversation-action-state[data-state="active"] {
  color: var(--accent);
}
.conversation-surface .conversation-action-state[data-state="attention"] {
  color: var(--error-text);
}
.conversation-surface .conversation-action-state[data-state="background"] {
  color: var(--text-tertiary);
}
/* Conversation prose: one readable column with explicit content rhythm.
 * Owner: typed text blocks. Scope excludes tool output, reasoning and editors.
 * Tokens: 00-design-tokens.css; delivery: ordered application manifest.
 */
.conversation-surface .conversation-block--text > .md-content {
  min-width: 0;
  max-width: 100%;
  color: var(--text-primary);
  font-family: var(--font-ui);
  font-size: var(--conversation-font-size-body);
  font-weight: var(--weight-regular);
  line-height: var(--leading-body);
  overflow-wrap: anywhere;
}

/* The rubric is a reading toolbar. Text starts on the exact prose baseline;
 * secondary navigation sits opposite it, never in an extra leading slot. */
.conversation-surface .conversation-answer-label {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-height: var(--control-h-lg);
  margin-block: 0 var(--space-4);
  padding-block-end: var(--space-2);
  border-block-end: var(--control-edge-inset) solid var(--turn-rule);
  color: var(--text-secondary);
  font-size: var(--conversation-process-font-size);
  font-weight: var(--weight-medium);
  line-height: var(--leading-title);
}
.conversation-surface .conversation-answer-title {
  flex: 1;
  min-width: 0;
  color: var(--text-primary);
}
.conversation-surface .conversation-answer-outline { position: relative; }
.conversation-surface .conversation-answer-outline > summary {
  display: flex;
  align-items: center;
  min-height: var(--control-h-lg);
  gap: var(--space-2);
  padding-inline: var(--space-2);
  border-radius: var(--radius-sm);
  list-style: none;
  cursor: pointer;
  font-size: var(--conversation-font-size-meta);
  font-weight: var(--weight-medium);
}
.conversation-surface .conversation-answer-outline > summary::after {
  content: '';
  width: var(--space-2);
  height: var(--space-2);
  border-inline-end: var(--control-edge-inset) solid currentColor;
  border-block-end: var(--control-edge-inset) solid currentColor;
  transform: rotate(-45deg);
}
.conversation-surface .conversation-answer-outline[open] > summary::after { transform: rotate(45deg); }
.conversation-surface .conversation-answer-outline > summary::-webkit-details-marker { display: none; }
.conversation-surface .conversation-answer-outline > summary:hover { background: var(--bg-hover); }
.conversation-surface .conversation-answer-outline > nav {
  position: absolute;
  z-index: 5;
  inset-inline-end: 0;
  inset-block-start: calc(100% + var(--space-1));
  display: grid;
  gap: var(--space-1);
  width: min(var(--tool-source-chip-measure), 65vw);
  max-height: 50vh;
  overflow: auto;
  padding: var(--space-2);
  border: var(--control-edge-inset) solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-primary);
  box-shadow: var(--shadow);
}
.conversation-surface .conversation-answer-outline > nav > button { justify-content: flex-start; text-align: start; }
.conversation-surface .conversation-answer-outline > summary:focus-visible {
  outline: var(--control-edge-inset) solid var(--accent);
  outline-offset: var(--space-1);
}
.conversation-surface .conversation-block--text[data-deliverable="true"] > .md-content > :is(h1, h2, h3):first-child {
  margin-block-start: 0;
  font-size: var(--conversation-font-size-heading-1);
  line-height: var(--leading-tight);
  letter-spacing: -.025em;
}
.conversation-surface .conversation-block--text[data-deliverable="true"] > .md-content > p:first-child {
  font-size: var(--font-size-2xl);
}
.conversation-surface .conversation-history-process .conversation-block--text > .md-content {
  font-size: var(--conversation-process-font-size);
  color: var(--text-secondary);
}

.conversation-surface .conversation-block--text > .md-content :is(p, ul, ol, pre, table, blockquote) {
  margin-block: var(--space-4);
}

.conversation-surface .conversation-block--text > .md-content > :first-child {
  margin-block-start: 0;
}

.conversation-surface .conversation-block--text > .md-content > :last-child {
  margin-block-end: 0;
}

.conversation-surface .conversation-block--text > .md-content :is(h1, h2, h3, h4, h5, h6) {
  margin-block: var(--space-6) var(--space-3);
  color: var(--text-primary);
  font-family: var(--font-ui);
  font-weight: var(--weight-semibold);
  line-height: var(--leading-title);
  letter-spacing: normal;
  border: 0;
  padding: 0;
}

.conversation-surface .conversation-block--text > .md-content h1 {
  font-size: var(--conversation-font-size-heading-1);
}

.conversation-surface .conversation-block--text > .md-content h2 {
  font-size: var(--conversation-font-size-heading-2);
}

.conversation-surface .conversation-block--text > .md-content :is(h3, h4, h5, h6) {
  font-size: var(--conversation-font-size-heading-3);
}

.conversation-surface .conversation-block--text > .md-content :is(ul, ol) {
  padding-inline-start: var(--space-6);
}

.conversation-surface .conversation-block--text > .md-content li {
  margin-block: var(--space-2);
  padding-inline-start: var(--space-1);
}

.conversation-surface .conversation-block--text > .md-content li::marker {
  color: var(--text-secondary);
}

.conversation-surface .conversation-block--text > .md-content blockquote {
  padding: var(--space-1) var(--space-4);
  border-inline-start: 2px solid var(--border);
  color: var(--text-secondary);
  background: transparent;
}

.conversation-surface .conversation-block--text > .md-content pre {
  min-width: 0;
  max-width: 100%;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  box-shadow: none;
  overflow: hidden;
}

.conversation-surface .conversation-block--text > .md-content pre code {
  font-family: var(--font-mono);
  display: block;
  padding: var(--space-4);
  border: 0;
  border-radius: 0;
  background: transparent;
  overflow-x: auto;
  font-size: var(--conversation-font-size-content);
  line-height: var(--leading-body);
  white-space: pre;
  overflow-wrap: normal;
  word-break: normal;
}

.conversation-surface .conversation-block--text > .md-content table {
  max-width: 100%;
  font-size: var(--conversation-font-size-table);
  line-height: var(--leading-body);
  border-color: var(--border);
}

.conversation-surface .conversation-block--text > .md-content .md-table-wrapper {
  max-width: 100%;
  margin-block: var(--space-4);
}

.conversation-surface .conversation-block--text > .md-content .md-table-wrapper > table {
  margin: 0;
}

.conversation-surface .conversation-block--text > .md-content :is(.code-header, .table-header) {
  min-height: var(--control-h-md);
  padding: var(--space-1) var(--space-3);
  color: var(--text-secondary);
  font-family: var(--font-ui);
  font-size: var(--conversation-font-size-meta);
}

.conversation-surface .conversation-block--text > .md-content :is(.code-header, .table-header) button {
  min-height: var(--control-h-sm);
  font-size: var(--conversation-font-size-meta);
  color: var(--text-secondary);
}

.conversation-surface .conversation-block--text > .md-content :is(th, td) {
  padding: var(--space-2) var(--space-3);
  border-color: var(--border);
  text-align: start;
}

.conversation-surface .conversation-block--text > .md-content th {
  color: var(--text-primary);
  font-weight: var(--weight-semibold);
  background: var(--bg-secondary);
}

.conversation-surface .conversation-block--text > .md-content a {
  color: var(--accent);
  text-decoration-thickness: from-font;
  text-underline-offset: .18em;
}

.conversation-surface .conversation-block--text > .md-content a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Projected Markdown images are reading content, not attachment thumbnails. */
.conversation-surface .md-content img.md-image {
  display: inline-block;
  max-width: 100%;
  max-height: none;
  height: auto;
  object-fit: contain;
  vertical-align: middle;
  margin: 0;
  cursor: default;
}

.conversation-surface .md-content img.md-image:hover {
  opacity: 1;
}

.conversation-surface .md-content p.md-image-only {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-3);
}

.conversation-surface .md-content p.md-image-only img.md-image {
  display: block;
}

.conversation-surface .md-content p.md-image-only > br {
  display: none;
}

.conversation-surface .md-content img.md-preview-image {
  cursor: zoom-in;
}

.conversation-surface .md-content a img.md-image {
  cursor: pointer;
}

.conversation-surface .md-content img.md-preview-image:focus-visible {
  outline: calc(2 * var(--control-edge-inset)) solid var(--accent);
  outline-offset: calc(-2 * var(--control-edge-inset));
}

.conversation-surface .md-content p.md-image-only > a {
  display: block;
  max-width: 100%;
}
/* Thinking disclosures and generic tool evidence.
 * Owner: ConversationSurface; tokens: 00-design-tokens.css.
 * Delivery: ordered application manifest; neighboring content owners are independent.
 */

/* A shared disclosure grammar for reasoning, tool results, context notes,
 * checklists, programs and the fallback renderer. Existing native disclosures
 * retain their lifecycle; only the label/marker/evidence columns are shared. */
.conversation-surface :is(
  .thinking-header, .ptool-line, .ptc-head, .conversation-tool-card__summary
) {
  box-sizing: border-box;
  min-height: var(--conversation-process-row-height);
  padding: var(--space-2) var(--conversation-process-inset);
  gap: var(--conversation-process-gap);
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  font-family: var(--font-ui);
  font-size: var(--conversation-process-font-size);
  line-height: var(--leading-title);
}

.conversation-surface :is(
  .thinking-header, .ptool-line, .ptc-head, .conversation-tool-card__summary
):hover {
  background: var(--turn-process-hover);
}

.conversation-surface :is(
  .thinking-label, .ptool-text, .ptc-title, .conversation-tool-card__title
) {
  min-width: 0;
  color: var(--text-secondary);
  font-family: var(--font-ui);
  font-size: var(--conversation-process-font-size);
  font-weight: var(--weight-medium);
  line-height: var(--leading-title);
  white-space: normal;
  overflow-wrap: anywhere;
  letter-spacing: normal;
}

/* Tool identity stays in the leading slot; a single trailing caret is the
 * consistent disclosure affordance. Native summaries still own interaction.
 * The caret is a pseudo-element of the FLEX ROW, so it is an atomic flex item
 * that can never wrap onto a line of its own — the failure the edit card had
 * while its caret was inline text inside the wrapping label. */
.conversation-surface :is(.ptool-result-header, .ptool-results-header, .sw-inbox-row-header, .ptool-todo-header, .ptool-batch-done-header, .conversation-tool-card__summary)::after {
  content: '';
  box-sizing: border-box;
  flex: 0 0 var(--space-2);
  width: var(--space-2);
  height: var(--space-2);
  margin-inline: var(--space-1);
  border-inline-end: var(--control-edge-inset) solid currentColor;
  border-block-end: var(--control-edge-inset) solid currentColor;
  transform: rotate(-45deg);
  color: var(--text-secondary);
}
.conversation-surface details[open] > :is(.ptool-result-header, .sw-inbox-row-header, .ptool-todo-header, .ptool-batch-done-header, .conversation-tool-card__summary)::after,
.conversation-surface .ptool-results-header[aria-expanded="true"]::after {
  transform: rotate(45deg);
}
.conversation-surface :is(.ptool-result-header, .ptool-results-header, .sw-inbox-row-header, .ptool-todo-header) > .ptool-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 var(--conversation-process-marker);
  width: var(--conversation-process-marker);
  height: var(--conversation-process-marker);
  color: var(--text-secondary);
}
.conversation-surface .ptool-results-header > .ptool-results-toggle,
.conversation-surface :is(.ptool-result-header, .sw-inbox-row-header, .ptool-todo-header, .ptool-batch-done-header) .ptool-text::after {
  display: none;
}
.conversation-surface .ptc-head::before,
.conversation-surface .conversation-tool-card__summary::before {
  content: '{}';
  order: -1;
  width: var(--conversation-process-marker);
  flex: 0 0 var(--conversation-process-marker);
  text-align: center;
  color: var(--text-secondary);
  font: var(--weight-medium) var(--conversation-font-size-meta) var(--font-mono);
}
.conversation-surface .ptc-chevron { order: 2; }
