/* Durable activity, failures and compaction receipts.
 * Owner: ConversationSurface; tokens: 00-design-tokens.css.
 * Delivery: ordered application manifest; neighboring content owners are independent.
 */

/* Durable activity reads as a log line, not a stack of colored banners. */

.conversation-surface .conversation-block--activity-event {
  margin-top: 0;
  margin-bottom: 0;
}

.conversation-surface .activity-event {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  min-height: var(--conversation-process-row-height);
  padding: var(--space-2) var(--conversation-process-inset);
  border-bottom: 0;
  border-radius: 0;
  background: transparent;
  box-sizing: border-box;
}

.conversation-surface :is(.activity-event--warning, .activity-event--error, .activity-event--failed) {
  background: transparent;
}

/* The leading glyph is centered inside the row's line box: a fixed offset
 * drifts off the words as soon as the meta type or line height changes. */
.conversation-surface .activity-event__marker {
  position: static;
  display: inline-flex;
  flex-shrink: 0;
  width: var(--space-4);
  height: var(--space-4);
  margin-block-start: calc((var(--conversation-activity-line-height) - var(--space-4)) / 2);
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: transparent;
  box-shadow: none;
  color: var(--text-tertiary);
}

.conversation-surface .activity-event__marker svg {
  width: 12px;
  height: 12px;
}

.conversation-surface :is(.activity-event--error, .activity-event--failed) .activity-event__marker {
  background: var(--bg-primary);
  color: var(--error-text);
}

.conversation-surface .activity-event--warning .activity-event__marker,
.conversation-surface :is(.activity-event--switched, .activity-event--skipped, .activity-event--aborted) .activity-event__marker {
  background: var(--bg-primary);
  color: var(--warning-text);
}

.conversation-surface .activity-event--succeeded .activity-event__marker {
  background: var(--bg-primary);
  color: var(--s-done, var(--success-text));
}

/* Diagnostic icons carry meaning inline; there is no out-of-flow gutter. */
/* A provider retry storm is one fact, not N banners: the run of failed /
 * retried requests collapses into a single closed disclosure that keeps the
 * same log-line geometry as an activity row. Members stay inside unchanged. */

.conversation-surface .conversation-block--activity-event-group {
  margin-top: 0;
  margin-bottom: 0;
}

.conversation-surface .activity-event-group {
  display: block;
  min-width: 0;
}

.conversation-surface .activity-event-group__summary {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  min-height: var(--conversation-process-row-height);
  padding: var(--space-2) var(--conversation-process-inset);
  box-sizing: border-box;
  cursor: pointer;
  list-style: none;
}

.conversation-surface .activity-event-group__summary::-webkit-details-marker {
  display: none;
}

.conversation-surface .activity-event-group__summary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: calc(var(--space-1) * -1);
}

.conversation-surface .activity-event-group__marker {
  display: inline-flex;
  flex-shrink: 0;
  width: var(--space-4);
  height: var(--space-4);
  margin-block-start: calc((var(--conversation-activity-line-height) - var(--space-4)) / 2);
  align-items: center;
  justify-content: center;
  color: var(--warning-text);
}

.conversation-surface .activity-event-group__marker svg {
  width: 12px;
  height: 12px;
}

.conversation-surface .activity-event-group__label {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--text-secondary);
  font-size: var(--conversation-font-size-meta);
  line-height: var(--conversation-activity-line-height);
  overflow-wrap: anywhere;
}

.conversation-surface .activity-event-group__models {
  max-width: 40ch;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.conversation-surface .activity-event-group__chevron {
  display: inline-flex;
  flex: 0 0 auto;
  transition: transform var(--motion-fast) ease;
  transform: rotate(-90deg);
}

.conversation-surface .activity-event-group[open] .activity-event-group__chevron {
  transform: rotate(0);
}

.conversation-surface .activity-event-group__body {
