/* Compaction is a durable context boundary, so it earns one quiet exception
 * to the log-line treatment. The converging token rail carries the before /
 * after accounting; accent chrome distinguishes it from failures. */

.conversation-surface .activity-event--compaction {
  margin: var(--space-1) 0;
  padding: var(--space-2) var(--space-2) var(--space-2) var(--space-3);
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--turn-rule));
  border-radius: 11px;
  background:
    linear-gradient(105deg,
      color-mix(in srgb, var(--accent) 8%, var(--bg-primary)) 0%,
      color-mix(in srgb, var(--accent) 2%, var(--bg-primary)) 74%);
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--accent) 62%, transparent);
}

.conversation-surface .activity-event--compaction .activity-event__marker {
  top: var(--space-2);
  background: var(--bg-primary);
  color: color-mix(in srgb, var(--accent) 84%, var(--text-secondary));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 38%, var(--turn-spine));
}

