/* User notes, narrow screens and reduced motion.
 * Owner: ConversationSurface; tokens: 00-design-tokens.css.
 * Delivery: ordered application manifest; neighboring content owners are independent.
 */

/* User turns are compact notes; they deliberately do not grow an execution spine. */

.conversation-surface .message.user-msg .message-content {
  justify-self: end;
  box-sizing: border-box;
  width: fit-content;
  /* Cap to a chat-bubble measure, not the assistant reading column: a one-liner
     must read as a tight note, not a slab that nearly spans the transcript. */
  max-width: min(72%, 46rem);
  padding: var(--space-3) var(--space-4);
  border: var(--control-edge-inset) solid var(--turn-rule);
  /* Chat geometry: a slightly flattened top-right corner signals the sender's
     side; the rest stay rounded so it reads as one calm bubble, not a card. */
  border-radius: var(--radius) var(--radius) var(--radius-xs) var(--radius);
  background: color-mix(in srgb, var(--user-bubble) 70%, var(--bg-primary));
  box-shadow: none;
}

.conversation-surface .message.user-msg .message-avatar {
  visibility: hidden;
}

.conversation-surface .message.user-msg .message-header {
  margin-block: 0 var(--space-2);
  padding-inline-start: 0;
}

.conversation-surface .message.user-msg .conversation-turn-blocks > .conversation-block {
  margin-bottom: var(--space-1);
}

.conversation-surface .message.user-msg .conversation-block--text > .md-content {
  font-size: var(--conversation-font-size-body);
  line-height: var(--leading-body);
}

/* When the bubble carries attachments, the fixed-size media tiles (80px thumbs,
   300px video cards) are far narrower than a full-length text line. fit-content
   then sizes the bubble to the TEXT, leaving dead space beside the thumbnails.
   Cap the text to a comfortable reading measure so the bubble hugs its real
   content and the attachment row and text row stay visually balanced. */
.conversation-surface .message.user-msg .conversation-turn-blocks:has(.conversation-block--attachments) .conversation-block--text > .md-content {
  max-width: 34rem;
}

.conversation-surface .message.user-msg .conversation-turn-actions {
  margin-top: var(--space-1);
  padding-top: var(--space-1);
}

